window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-18"]={"block":"med:med-clinica-medica-med-clm-18","label":"MED · MED CLM 18","count":443,"questions":[{"id":"med-clinica-medica-med-clm-18-247183","number":"247183","sourceNumber":"247183","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Adolescente Masculino, 16 anos de idade, apresenta história de adenomegalia cervical\nunilateral há seis meses de crescimento progressivo e, nos últimos dois meses, apresenta febre\ndiária, emagrecimento e sudorese. O diagnóstico mais provável é","options":{"A":"Linfoma de Hodgkin.","B":"Linfoma de Burkitt.","C":"Neuroblastoma.","D":"Adenocarcinoma de parótida.","E":"Carcinoma de tireoide."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-217658","number":"217658","sourceNumber":"217658","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa que NÃO apresenta um aspecto prognóstico relevante nas\nLeucemias Linfocíticas Agudas (LLAs).","options":{"A":"Leucometria inicial.","B":"Número de cromossomos no cariótipo.","C":"Febre.","D":"Idade avançada."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-29377","number":"29377","sourceNumber":"29377","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São características fisiopatológicas da Insuficiência Renal Crônica:","options":{"A":"Anemia, hipocalcemia, hiperfosfatemia, hiperparatireoidismo.","B":"Anemia, hipercalcemia, hiperfosfatemia, hiperparatireoidismo.","C":"Anemia, hipocalcemia, hipofosfatemia, hiperparatireoidismo.","D":"Anemia, hipercalcemia, hipofosfatemia, hipoparatireoidismo.","E":"Anemia, hipocalcemia, hiperfosfatemia, hipoparatireoidismo."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-343156","number":"343156","sourceNumber":"343156","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL) na forma crônica pode ter sua\nevolução clínica classificada em tipo desfavorável ou favorável. Sendo correto o item:","options":{"A":"O tipo favorável tem curso rápido, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","B":"O tipo desfavorável tem curso rápido, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","C":"O tipo desfavorável tem curso lento, com sobrevida de 15 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e DHL.","D":"O tipo desfavorável tem curso rápido, com sobrevida de 50 meses. Laboratorialmente, são\nfrequentes as elevações da ureia, creatinina e não DHL."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-343160","number":"343160","sourceNumber":"343160","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A forma linfomatosa da leucemia-linfoma de células T do adulto (ATLL) é:","options":{"A":"Caracterizada por linfonodomegalia, com comprometimento do sangue periférico; representa\n20% dos casos, sendo na maior parte das vezes\numa doença avançada. A hipercalcemia pode\nestar presente, assim como lesões cutâneas, incluindo rash eritematoso, pápulas e nódulos, por\nvezes com ulceração.","B":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior parte das\nvezes uma doença avançada. A\nhipercalcemia pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, por vezes com ulceração.","C":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior\nparte das vezes uma doença avançada. A\nhipercalcemia nunca pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, por vezes com ulceração.","D":"Caracterizada por linfonodomegalia, mas sem comprometimento do sangue periférico;\nrepresenta 20% dos casos, sendo na maior parte das\nvezes uma doença avançada. A\nhipercalcemia pode estar presente, assim como lesões cutâneas, incluindo rash eritematoso,\npápulas e nódulos, mas não com ulceração."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-343170","number":"343170","sourceNumber":"343170","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL), está de acordo com o seguinte item:","options":{"A":"é uma doença não linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","B":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente não associada ao HTLV-1.","C":"é uma doença linfoproliferativa indolente de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","D":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-279045","number":"279045","sourceNumber":"279045","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Das alternativas apresentadas abaixo, assinale a correta considerando-se o diagnóstico\nde neutropenia febril.","options":{"A":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","B":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico.","C":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","D":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215539","number":"215539","sourceNumber":"215539","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No contexto da doença de chagas, o diagnóstico de miocardite torna-se ainda mais\ndifícil e complexo. A doença de chagas é uma\ndoença infecciosa, cujo agente etiológico é o\nTrypanosoma cruzi, com fenótipos heterogêneos na apresentação clínica polimórfica da fase\naguda, crônica e nas reativações. Podemos, apenas, ACEITAR que, o diagnóstico de miocardite:","options":{"A":"Ainda constitui desafio na atualidade, entre outras razões, por ser homogêneo em sua\napresentação clínica, variando desde formas\nsubclínicas e/ou sintomas inespecíficos, até a forma\nfulminante de IC, com grave comprometimento hemodinâmico.","B":"Ainda constitui desafio na atualidade, entre outras razões, pela heterogeneidade da\napresentação clínica, variando desde formas\nsubclínicas e/ou sintomas inespecíficos, mas nunca\naté a forma fulminante de Insuficiência Cardíaca (IC).","C":"Ainda constitui desafio na atualidade, entre outras razões, pela heterogeneidade da\napresentação clínica, variando desde formas\nsubclínicas e/ou sintomas inespecíficos, até a forma\nfulminante de IC, com grave comprometimento hemodinâmico.","D":"Não mais constitui desafio na atualidade, entre outras razões, pela apresentação clínica."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215564","number":"215564","sourceNumber":"215564","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A miocardite é uma das complicações mais frequentes entre doentes em fase aguda da\ndoença de Chagas por transmissão oral.\nQual item se mostra CORRETO?","options":{"A":"Os principais sinais e sintomas na fase aguda da doença de chagas por transmissão oral são\ndispneia, palpitações, taquicardia (sem febre) e, eventualmente, dores precordiais, simulando\ninfarto do miocárdio.","B":"Os principais sinais e sintomas na fase aguda da doença de chagas por transmissão oral são\ndispneia, palpitações, taquicardia (com febre) e, eventualmente, dores precordiais, simulando\ninfarto do miocárdio.","C":"Os principais sinais e sintomas na fase aguda da doença de chagas por transmissão oral são\ndispneia, palpitações, taquicardia (sem febre) e, eventualmente, dores precordiais, nunca\nsimulando infarto do miocárdio.","D":"Os principais sinais e sintomas na fase aguda da doença de chagas por transmissão oral são\ndispneia, palpitações, bradicardia e, eventualmente, dores precordiais, simulando infarto do\nmiocárdio."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215488","number":"215488","sourceNumber":"215488","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Todas as alternativas a seguir estão associadas a risco aumentado de lise tumoral,\nEXCETO:","options":{"A":"Metástase extensa.","B":"Desidratação.","C":"Insuficiência hepática prévia ao diagnóstico de câncer.","D":"Leucócitos aumentados."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-219870","number":"219870","sourceNumber":"219870","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 53 anos procura auxílio médico devido à massa cervical não dolorosa, que\nfoi notada há cerca de dois meses. Relata\nque, quando bebe um a dois copos de vinho, a massa\ncervical se torna dolorosa. Ele também se queixa de febre intermitente, sudorese noturna, prurido e\nperda de peso superior a 10% do peso corporal habitual, no último mês. Ao exame físico, palpa-se\nlinfonodo de aproximadamente 3 cm na região cervical, à esquerda, de consistência fibroelástica.\n\nVários outros linfonodos cervicais são também palpáveis à esquerda, assim como um linfonodo na\nregião axilar esquerda. O fígado está aumentado, mas não há esplenomegalia ao exame. Trouxe\nconsigo radiografia de tórax que estava normal. Considerando-se esses dados, qual é o diagnóstico\nMAIS PROVÁVEL?","options":{"A":"Linfoma de Hodgkin.","B":"Mononucleose infecciosa.","C":"Sarcoidose.","D":"Tricoleucemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216249","number":"216249","sourceNumber":"216249","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Por via oral é uma das formas habituais de transmissão de T. cruzi para o homem,\nocorre quando há ingestão de alimentos\ncontaminados acidentalmente com o parasito, seja o\ntriatomíneo ou suas fezes. Marque, apenas, o item ERRADO.","options":{"A":"Também pode ocorrer por meio da ingestão de carne crua ou mal cozida de caça ou alimentos\ncontaminados pela secreção das glândulas anais de marsupiais infectados.","B":"Ocorre em locais definidos, em um determinado tempo, por diferentes tipos de alimentos ?\ngeralmente encontrando-se vetores ou reservatórios infectados nas imediações da área de\nprodução, manuseio ou utilização do alimento contaminado.","C":"É o tipo de transmissão que geralmente não está associada aos surtos de doença de Chagas\naguda (DCA).","D":"Em grande parte dos casos, tem como possível fundamentação o consumo de alimentos\ncontaminados pela não adoção de boas práticas de higiene na manipulação dos alimentos."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-181419","number":"181419","sourceNumber":"181419","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A síndrome de lise tumoral é uma emergência oncológica caracterizada por\ncomplicações metabólicas decorrentes da morte\ncelular de neoplasias malignas com alto índice\nproliferativo. Qual a alternativa que contempla os principais sinais e sintomas dessa síndrome?","options":{"A":"Hiperfosfatemia, hipercalemia, hipercalcemia falência renal, hiperuricemia.","B":"Hiperfosfatemia, hipercalemia, hipocalcemia, falência renal, arritmias.","C":"Hipofosfatemia, hipercalemia, hipocalcemia, câimbras, arritmias.","D":"Hipofosfatemia, hipercalemia, hipercalcemia, vômitos, arritmias.","E":"Hipocalemia, hiperfosfatemia, hipocalcemia, oligúria, acidose metabólica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-183048","number":"183048","sourceNumber":"183048","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança de 9 anos internada na UTI Pediátrica por Linfoma de Burkitt, terminou primeiro\nciclo de quimioterapia. Evolui com\nSíndrome de Lise Tumoral. Nas últimas 24 horas teve diurese de\n0,25ml/Kg/hora. Das alternativas abaixo, qual é o diagnóstico mais improvável para essa paciente?","options":{"A":"Hiperfosfatemia.","B":"Hiperuricemia.","C":"Hipopotassemia.","D":"Arritmia cardíaca."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-187809","number":"187809","sourceNumber":"187809","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 50 anos procurou atendimento médico devido à gengivorragia, epistaxe e\nfebre há 2 dias. Ao exame, temperatura axilar = 39°C; pressão arterial = 120/70 mmHg; frequência\ncardíaca = 120 bpm e frequência respiratória = 22 irpm. Foram auscultadas crepitações\nteleinspiratórias na base do hemitórax direito. Diante desses achados, optou-se por interná-lo para\ninvestigação adicional. Radiografia de tórax mostrou opacidade com broncograma aéreo na base\ndo pulmão direito. Hemograma evidenciou anemia (hemoglobina = 10,2 g/dl); leucocitose\n(12.000/mm³) com numerosos mieloblastos e plaquetopenia (15.000/mm³). Mielograma revelou\nmedula hipercelular com 45% de mieloblastos. Bastonetes de Auer foram observados nos blastos\npresentes na medula óssea e sangue periférico. Dentre as opções abaixo, qual é o diagnóstico\nMAIS PROVÁVEL para o quadro hematológico?","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia mieloide aguda.","C":"Reação leucemoide.","D":"Síndrome mielodisplásica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-187861","number":"187861","sourceNumber":"187861","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com 65 anos de idade, refere aumento de região cervical com duração maior\nque 60 dias. Ao exame físico foram\nevidenciados linfonodos palpáveis na região cervical posterior,\nindolores e não aderentes aos planos profundos. Após esgotada propedêutica de orofaringe e trato\ndigestivo superior foi realizada biopsia excisional de linfonodo comprometido que demonstrou a\npresença de células grandes, com citoplasma discretamente basofílico, núcleos bilobulados,\ncircundadas por linfócitos T. Assinale a alternativa CORRETA para o diagnóstico MAIS PROVÁVEL\ndesse caso:","options":{"A":"Linfoma de Burkitt","B":"Linfoma de Hodgkin","C":"Linfoma linfoplasmocitário","D":"Linfoma folicular"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-140210","number":"140210","sourceNumber":"140210","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 45 anos, hipertensa de longa data, interna por dor precordial sendo\ndiagnosticado IAM e instituído tratamento medicamentoso com estreptoquinase (trombólise),\nAAS, propranolol e sinvastatina. Evolui com hipotensão e sinais de má perfusão tecidual no\ndécimo dia de internação. Nesta data apresentava Creatinina = 1,0 mg/dl. No dia seguinte\nevoluiu com oligúria, urina escura e os seguintes exames: Cr = 3,8 mg/dl, Exame de urina\n(EAS): pH-6,0 Densidade=1010, presença de hematúria ++/4 em fita reagente. Hemácias:\n2/campo (normal até 6). Sem proteinúria ou leucocitúria. Baseado nestes achados assinale a\nprincipal etiologia da injúria renal:","options":{"A":"Rabdomiólise.","B":"Baixo débito cardíaco.","C":"Nefrite intersticial aguda.","D":"Sepses.","E":"Obstrução intratubular."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-110060","number":"110060","sourceNumber":"110060","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com Insuficiência Renal Aguda evolui com episódio de crise convulsiva.\nExames laboratoriais: creatinina = 3.5 mg/dl, ureia\n= 215 mg/dl, sódio plasmático = 141 mEq/l,\npotássio plasmático = 5.5 mEq/l, cálcio iônico = 1.18 mEq/l. Diante desse caso, Indique a conduta\nMAIS apropriada.","options":{"A":"Gluconato de cálcio.","B":"Diálise.","C":"Sulfato de magnésio.","D":"Fenobarbital."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-110049","number":"110049","sourceNumber":"110049","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com Insuficiência Cardíaca Crônica apresenta elevação da Creatinina\nPlasmática (1,0 mg/dl para 1,3 mg/dl) após introdução de inibidor da enzima conversora da\nAngiotensina. A conduta MAIS apropriada é","options":{"A":"Reduzir a dose da medicação.","B":"Suspender a medicação.","C":"Manter a medicação.","D":"Trocar a medicação por um bloqueador do receptor AT1 da Angiotensina."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-86589","number":"86589","sourceNumber":"86589","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Das causas abaixo de insuficiência renal aguda, qual a que mais frequentemente está\nassociada à hipocalemia?","options":{"A":"Nefrotoxicidade por anfotericina B.","B":"Sépsis.","C":"Rabdomiólise.","D":"Nefrotoxicidade por contraste.","E":"Pós-operatório de cirurgia cardíaca."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-86594","number":"86594","sourceNumber":"86594","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente feminina, 54 anos, 65 kg de peso apresenta-se com Insuficiência Renal aguda\ne creatinina sérica de 2,7. Qual o seu\nclearance de creatinina estimado:","options":{"A":"30 ml/min.","B":"24,2 ml/min.","C":"60 ml/min.","D":"54,6 ml/min.","E":"28,7 ml/min."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-86874","number":"86874","sourceNumber":"86874","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A principal causa de mortalidade em pacientes em hemodiálise crônica é:","options":{"A":"Hemorragia cerebral.","B":"Sepse.","C":"Hemorragia digestiva.","D":"Insuficiência respiratória aguda.","E":"Cardiovascular."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-108582","number":"108582","sourceNumber":"108582","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre as causas de lesão renal aguda é incorreto afirmar:","options":{"A":"Pode ser desencadeada por contrastes iodados.","B":"Na leptospirose muitas vezes cursa com poliuria.","C":"Nas uti?s tem baixa incidência e alta letalidade.","D":"Antibioticos como vancomicina e os aminoglicosideos costumam piorar a lesão.","E":"Todas as anteriores."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-362489","number":"362489","sourceNumber":"362489","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Durante atividade na UBS, você se depara com dois pacientes com astenia há 2\nsemanas e anemia grave. Paciente 1: homem\nde 21 anos de idade, Hb = 8,6 g/dl, VCM = 106,\nleucócitos = 920 mm3, neutrófilos = 210 mm3 e plaquetas 24.000 mm3; Paciente 2: homem de 67\nanos de idade, Hb = 9,5 g/dl, VCM = 94, leucócitos = 220.000 mm3, neutrófilos = 4.500 mm3,\nlinfócitos = 215.000 mm3 e plaquetas = 64.000 mm3. Qual paciente deve ter prioridade no\nencaminhamento para a unidade de urgência e por qual motivo?","options":{"A":"Paciente 1, por apresentar pancitopenia com neutropenia grave, tendo alto risco de neutropenia\nfebril e sangramentos.","B":"Paciente 1, por apresentar anemia mais grave e risco de descompensação hemodinâmica e\nsangramentos.","C":"Paciente 2, por apresentar leucocitose intensa, risco de hiperviscosidade e insuficiência\nrespiratória.","D":"Paciente 2, por apresentar linfocitose intensa e alto risco de síndrome de lise tumoral\nespontânea."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-327224","number":"327224","sourceNumber":"327224","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 46 anos, retorna à consulta ambulatorial para resultado de exames após\nacidente vascular cerebral isquêmico há 5 semanas, com boa evolução da fase aguda.\n\nAntecedente pessoal: cirurgia bariátrica há 6 anos, sem acompanhamento ou medicações\nregulares. Hemoglobina = 14g/dL, VCM = 63fL,\nhemácias = 7.000.000/µL; leucócitos = 18.000/µL\n(segmentados 76%, linfócitos 10%, monócitos 5%; eosinófilos 6%, basófilos 3%), plaquetas =\n1.450.000/µL. Ferritina: 4ng/mL. Exame físico: baço palpável a 2 cm do rebordo costal esquerdo.\nQual é o diagnóstico?","options":{"A":"Trombofilia hereditária","B":"Traço talassêmico","C":"Anemia ferropriva","D":"Policitemia Vera"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-327296","number":"327296","sourceNumber":"327296","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Lactente 11 meses é internado para investigação diagnostica com quadro de dispneia,\nfebre baixa, edema facial, linfodenopatia e\napresenta na maioria das crianças edema ocular indolor.\nAssinale a alternativa CORRETA.","options":{"A":"Fixação ao complemento para tripanosoma.","B":"Biopsia aspirativa da medula para pesquisar de leishmania.","C":"Pesquisa de plasmodium de sangue periférico.","D":"Testes sorológicos treponêmicos."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-298191","number":"298191","sourceNumber":"298191","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Idoso de 75 anos, saudável, sem queixas pregressas, vai ao médico do Programa de\nSaúde da Família (PSF) fazer os exames\nanuais para acompanhamento do seu quadro de\nhipertensão arterial e diabetes. O exame físico não mostrou alterações. O médico solicita um\nhemograma cujo resultado mostra acentuada leucocitose com linfocitose associada (13.470/mm3),\nsem alterações no eritrograma ou contagem de plaquetas. Diante do exposto, o diagnóstico mais\nprovável é de:","options":{"A":"Linfoma.","B":"Infecção viral.","C":"Infecção bacteriana.","D":"Leucemia linfoide crônica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-208401","number":"208401","sourceNumber":"208401","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente de quarenta anos de idade, previamente hígida, relatou metrorragia de\ngrande intensidade, acompanhada do surgimento de petéquias e equimoses disseminadas pelo\ncorpo, com início há cerca de duas semanas, mas há um mês já apresentava fadiga e seus pais\nnotaram palidez cutâneo-mucosa. Na admissão, o exame físico mostrou, além dos sinais\npreviamente citados, hepatomegalia discreta, hemorragias conjuntivais e na mucosa oral. A\nradiografia de tórax não revelou sinais de alargamento mediastinal. O hemograma apresentou os\nseguintes resultados: hemoglobina = 7,0 g/dl; plaquetas = 50.000; leucócitos = 40.000 céls/mm³. A\nanálise citológica do esfregaço do sangue periférico indicou presença de cerca de 20% de\nleucócitos de tamanho aumentado e citoplasma com grânulos e bastonetes de Auer. A hipótese\ndiagnóstica mais provável para esse quadro clínico é a de:","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia linfoide crônica.","C":"Síndrome mielodisplásica.","D":"Leucemia mieloide aguda."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-176055","number":"176055","sourceNumber":"176055","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As bactérias Gram-negativas mais frequentemente isoladas em hemoculturas de\npacientes neutropênicos são:","options":{"A":"Escherichia coli, Klebsiella e Serratia.","B":"Morganella, Proteus e Pseudomonas aeruginosa.","C":"Pseudomonas aeruginosa, Klebsiella e Escherichia coli.","D":"Pseudomonas aeruginosa, Enterobacter e Proteus."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-176085","number":"176085","sourceNumber":"176085","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 45 anos, pardo, com queixas vagas de fadiga e indisposição,\nnáuseas e vômitos. Notou aumento do volume\nabdominal. Ao exame físico: discreta palidez e\nesplenomegalia acentuada e indolor. O estudo hematológico revelou: hemácias = 3,2 milhões/mm³;\nHb = 9,8 g/dl; Ht = 29%; VCM = 90; HCM = 30,6: CHCM = 29,5; leucócitos = 187.000/mm³; blastos\n\n= 2%; promielócitos = 3%; mielócitos = 13%; metamielócitos = 10%; bastonetes = 20%;\n\nsegmentados = 35%; eosinófilos = 3%; basófilos = 2%; linfócitos = 3%; monócitos = 4%; plaquetas\n\n= 1.065.000/mm³. Qual a hipótese diagnóstica mais provável?","options":{"A":"Reação leucemoide.","B":"Trombocitemia essencial.","C":"Leucemia mieloide aguda.","D":"Leucemia mieloide crônica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-151930","number":"151930","sourceNumber":"151930","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O paciente é um homem de 50 anos referindo plenitude pós-prandial mesmo após\ncomer pequenas quantidades. Encontra-se\nhipocorado, anictérico e baço palpável 8 cm abaixo da\nreborda costal. O resto do exame físico é normal. Ht = 37%; plaquetas = 377.000/mm³. Contagem\nde leucócitos com 50.0000/mm³, granulócitos = 43%; bastões = 13%; metamielócitos = 18%;\nmielócitos = 10%; promielócitos = 2%; blastos = 2%; monócitos = 11%; basófilos = 2%, eosinófilos =\n2%; linfócitos = 1%. Qual é o diagnóstico mais provável?","options":{"A":"Leucemia linfocítica crônica.","B":"Leucemia mieloide crônica.","C":"Leucemia mieloide aguda.","D":"Anemia megaloblástica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-129724","number":"129724","sourceNumber":"129724","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Dentre os pacientes abaixo, quem não é definido como portador de Doença Renal\nCrônica?","options":{"A":"Jovem de 16 anos, diabético tipo I, que apresenta microalbuminúria de 450 mg/24 h desde o ano\npassado.","B":"Mulher de 54 anos, histórico de infecções urinárias, com achado ultrassonográfico de cicatrizes\nrenais bilaterais, com taxa de filtração\nglomerular de 72 ml/min.","C":"Homem de 76 anos, diabético, internado por Infarto do miocárdio, em tratamento hemodialítico\nhá 45 dias.","D":"Homem de 63 anos, hipertenso, que apresenta taxa de filtração glomerular de 52 ml/min."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-129811","number":"129811","sourceNumber":"129811","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A mãe leva o filho de 3 anos, portador de síndrome de Down, ao seu consultório porque\na gengiva dele está sangrando há uma semana.\nRelata que ele está menos ativo que o habitual. O\nexame físico revela que a criança apresenta uma temperatura oral de 37,8°C, palidez,\nesplenomegalia, sangramento gengival e equimoses nas extremidades inferiores. Qual das opções\na seguir é o diagnóstico mais provável?","options":{"A":"Leucemia.","B":"Anemia aplástica.","C":"Púrpura trombocitopênica idiopática.","D":"Reação leucemoide."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103835","number":"103835","sourceNumber":"103835","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 55 anos procura atendimento médico no ambulatório Araújo Lima, informa\nque tem se sentido mal, relata astenia, às\nvezes, soluços, \"tique nervoso\", e que ao escrever sente\nsua mão tremendo. Trouxe hemograma com: Hto = 26% e Hb = 6,8. Sua urina é \"normal\". É\ndiabético há 15 anos. Qual o possível diagnóstico?","options":{"A":"Anemia ferropriva.","B":"Neuropatia a esclarecer. Encaminhar ao neurologista.","C":"Anemia a esclarecer. Possível insuficiência renal.","D":"Alcoolismo crônico. Encaminhar ao gastro."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103840","number":"103840","sourceNumber":"103840","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 55 anos procura atendimento médico no Ambulatório Araújo Lima, informa\nque tem se sentido mal, relata astenia, às\nvezes, soluços, \"tique nervoso\", e que ao escrever sente\nsua mão tremendo. Trouxe Hemograma com Hto 26% e Hb 6,8. Sua urina é \"normal\". É diabético\nhá 15 anos. Que/quais exames poderiam ser solicitados na sua investigação?","options":{"A":"Proteinúria de 24h.","B":"Glicemia, uréia, creatinina, sódio, potássio, reticulócitos, VCM, USG rins, próstata, EAS, estudo\ndo ferro.","C":"Estudo do ferro e eletroforese de albumina.","D":"Urinocultura para pesquisa de Clamídia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-80955","number":"80955","sourceNumber":"80955","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente de 60 anos com 50 kg de peso tem diabete melito tipo 2 há 16 anos.\nEvoluiu de microalbuminúria, há quatro anos,\npara uma proteinúria de 5,3 g/24H nos últimos dois\nanos. Considerando que sua creatinina é de 2,0 mg/dl, em qual estágio de doença renal crônica ela\nse encontra?","options":{"A":"Estágio 1","B":"Estágio 2","C":"Estágio 3","D":"Estágio 4","E":"Estágio 5"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-60912","number":"60912","sourceNumber":"60912","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Transplante de Medula Óssea (TMO) consiste na infusão venosa de células\nprogenitoras hematopoiéticas, com o objetivo de\nrestabelecer a função medular nos pacientes com\nmedula óssea danificada ou defeituosa. Em relação ao TMO, é INCORRETO que:","options":{"A":"As 3 modalidades de TMO são: autogênico, alogênico e singênico.","B":"As células-tronco podem ser coletadas da crista ilíaca, do sangue periférico ou do sangue de\ncordão umbilical.","C":"Entre as complicações do pós-TMO não se incluem as diarreias, as infecções virais e a doença\ndo enxerto contra o hospedeiro.","D":"Entre os exames solicitados para o receptor no pré-TMO estão o mielograma, a biópsia de\nmedula óssea e as sorologias para diversas doenças infecciosas.","E":"Entre as indicações neoplásicas para o TMO estão as leucemias e linfomas, e entre as não\nneoplásicas estão a anemia aplástica grave e algumas hemoglobinopatias (como talassemia maior\ne anemia falciforme)."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-46708","number":"46708","sourceNumber":"46708","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Adolescente, quinze anos, sexo feminino, apresenta tosse, febre, perda de peso,\ndispneia, palidez, dor torácica, disfagia,\nderrame pleural, linfadenopatia cervical e axilar. RX de\ntórax: massa mediastinal estendendo-se para hemitórax superior direito e comprimindo a carina. A\nhipótese diagnóstica é:","options":{"A":"Bócio mergulhante.","B":"Linfoma não Hodgkin.","C":"Carcinoma pulmonar indeterminado.","D":"Tuberculose.","E":"Tumor de Wilms."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-34122","number":"34122","sourceNumber":"34122","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à Insuficiência Renal Aguda (IRA renal), podemos afirmar que:","options":{"A":"A fase oligúrica da IRA renal caracteriza-se por volume urinário < 500 ml/dia e concentração\nurinária de sódio < 20 mEq/L.","B":"A utilização de diuréticos na IRA renal só traz benefícios se realizada na fase oligúrica.","C":"A indicação de diálise deve aguardar 72 horas de instalação de quadro de IRA renal, pelo risco\nde piora do estado nutricional.","D":"As complicações infecciosas são raras, porém implicam aumento significativo da mortalidade.","E":"Na fase poliúrica da IRA renal, a magnitude da diurese não depende do estado de hidratação do\npaciente."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-34179","number":"34179","sourceNumber":"34179","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São causas de Insuficiência Renal Aguda na infância:","options":{"A":"Tumor/urolitíase.","B":"Desidratação/hemorragia.","C":"Necrose cortical/ureterocele.","D":"Lúpus/síndrome hemolítico-urêmica.","E":"Trombose de veia renal/tumor."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-26683","number":"26683","sourceNumber":"26683","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pacientes com insuficiência renal crônica, é correto:","options":{"A":"Raramente têm Hipertensão Arterial Sistêmica","B":"Raramente têm anemia","C":"Pode ser devido à nefrose lipoide","D":"Poderão ter Hiperparatireoidismo Secundário","E":"Não necessitam de restrição de sal"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-10009","number":"10009","sourceNumber":"10009","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pacientes com insuficiência renal crônica:","options":{"A":"Raramente têm Hipertensão Arterial Sistêmica.","B":"Poderão ter Hiperparatireoidismo Secundário.","C":"Raramente têm anemia.","D":"Pode ser devido à nefrose lipoide.","E":"Não necessitam de restrição de sal."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-10018","number":"10018","sourceNumber":"10018","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação à Glomerulonefrite pós-estreptocócica, podemos afirmar que:","options":{"A":"A oligúria e a hipertensão persistem, nas apresentações típicas, por um período de 2 semanas.","B":"A redução dos níveis séricos das frações do complemento persiste por até 4 semanas.","C":"Não é necessária a restrição hídrica no tratamento, bastando a restrição de sódio.","D":"A hematúria microscópica no indivíduo adulto pode perdurar por até 1 ano, sem indicar\ncomplicação.","E":"O período de latência após uma faringite é de 14 a 28 dias."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-62850","number":"62850","sourceNumber":"62850","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, oito anos de idade, procedente da zona rural, com quadro de febre há 30\ndias, acompanhada de adinamia, palidez e aumento do volume abdominal. Ao exame físico,\napática, febril, pálida. Ausculta cardiopulmonar com murmúrio rude sem creptos, bulhas\ntaquicárdicas. Abdome volumoso, fígado a 5 cm do RCD, baço a 12 cm do RCE. Os exames\nlaboratoriais mostravam hemoglobina = 5,2 g/dl; leucócitos = 2.800 (2% eosinófilos; 1% bastões;\n34% segmentados; 1% linfócitos atípicos; 60% linfócitos); plaquetas = 98.000/mm³. O exame\nindispensável para o estudo desse caso é:","options":{"A":"Mielograma.","B":"Morfologia das hemácias.","C":"Eletroforese de hemoglobina.","D":"Prova do laço.","E":"Formogel."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-343344","number":"343344","sourceNumber":"343344","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia-linfoma de células T do adulto (ATLL), está de acordo com o seguinte item:","options":{"A":"é uma doença não linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","B":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente não associada ao HTLV-1.","C":"é uma doença linfoproliferativa indolente de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1.","D":"é uma doença linfoproliferativa agressiva de células T maduras, com diversas características\nclínicas, etiologicamente associada ao HTLV-1."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215588","number":"215588","sourceNumber":"215588","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 9 anos, com diagnóstico de linfoma de Burkitt, encontra-se internada na\nUTI pediátrica. Realizou primeiro ciclo de\nquimioterapia. Evoluiu com síndrome de lise tumoral. Nas\núltimas 24 horas, teve diurese de 0,25 ml/kg/hora. Das alternativas abaixo, qual é o diagnóstico\nmais improvável para essa paciente?","options":{"A":"Hiperfosfatemia.","B":"Hiperuricemia.","C":"Hipopotassemia.","D":"Insuficiência renal."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215619","number":"215619","sourceNumber":"215619","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na fase crônica da doença de Chagas a parasitemia é baixa e intermitente. Inicialmente\né assintomática e sem sinais de comprometimento\ncardíaco e/ou digestivo, e pode apresentar-se\ncom as forma indeterminada, somente sendo INCORRETO que:","options":{"A":"Paciente assintomático e sem sinais de comprometimento do aparelho circulatório (clínica,\neletrocardiograma e radiografia a de tórax normais).","B":"Aparelho digestivo (avaliação clínica e radiológica normais de esôfago e cólon).","C":"Esse quadro poderá perdurar por toda a vida do indivíduo infectado.","D":"Nunca pode evoluir tardiamente para a forma cardíaca, digestiva ou associada cardiodigestiva."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-321318","number":"321318","sourceNumber":"321318","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar, 6 anos, sexo masculino, iniciou há 2 meses quadro de dor em joelho esquerdo,\npersistente, predominando no período noturno e chegando a despertá-lo. Nega febre. Nega trauma.\nRelata uso de corticoide por 7 dias no início do quadro. Ao exame físico: Leve palidez. Ausculta\ncárdio-pulmonar sem alterações. Abdome indolor com fígado palpável a 3 cm do rebordo costal\ndireito. Marcha antálgica, dor à mobilização do joelho, ausência de sinais flogísticos. Traz exames\nque realizou na semana anterior: hemoglobina - 9,4 g/dL, hematócrito - 29%; 3.900 leucócitos/mm³\n(0% mielócitos, 1% bastões, 10 % segmentados, 80% linfócitos, 7% monócitos, 1% eosinófilos, 1%\nbasófilos), 152.000 plaquetas. VHS=60mm. Qual é a conduta diagnóstica mais indicada neste\nmomento?","options":{"A":"Solicitar RNM do joelho esquerdo.","B":"Solicitar aspirado de medula óssea.","C":"Solicitar sorologias virais, FAN e fator reumatoide.","D":"Solicitar ultrassonografia de joelhos com power doppler."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-292843","number":"292843","sourceNumber":"292843","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de cinco anos de idade chega ao ambulatório por apresentar dor óssea\nem membros inferiores, dificultando a\ndeambulação e sem ceder facilmente aos analgésicos\nhabituais. Também apresenta dor toracolombar e astenia. Ao exame físico, é identificado febre e\nhepatomegalia, esplenomegalia e linfonodomegalias generalizadas. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Leucemia linfoide aguda.","B":"Leucemia mieloide aguda.","C":"Mononucleose infecciosa.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-259725","number":"259725","sourceNumber":"259725","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 68 anos é admitido na sala de urgência com quadro de pico febril isolado,\nastenia, mialgias, vômitos e diarreia aquosa com uma semana de evolução. Diagnóstico há 3\nmeses de leucemia mieloide crônica, em fase blástica, com necessidade de esplenectomia e\nposterior citoredução eficaz. Medicado com imatinib 800mg ao dia. Ao exame físico,\n\napresentava-se colaborativo, frequência respiratória 22 incursões/minuto, anictérico, temperatura\n37ºC, frequência cardíaca 112 batimentos/minuto e\npressão arterial 130 x 80mmHg. Sem outras\nalterações relevantes. Exames complementares mostrando leucocitose (32.5000/mm³), anemia\nmicrocítica hipocrômica (hemoglobina 11,0 g/dL) com pesquisa de esquizócitos negativa,\ntrombocitopenia (130.000 /mm3), creatinina de 1,5 mg/dL (basal de 0.69 mg/dL), potássio 6,5 mg/dl\n(VR: 3,5-5,0); eletrocardiograma sem alterações, cálcio 7,7 mg/dL (VR: 8,5-10,2), elevação de LDH\nsérica de 7130 U/L, proteína C reactiva de 0,5 mg/dL (VR < 0,5), (VR Qual o diagnóstico mais\nprovável e tratamento inicial recomendado para o paciente?","options":{"A":"Síndrome de lise tumoral ? iniciar hidratação venosa e rasburicase ou alopurinol.","B":"Síndrome hemolítico-urêmica ? iniciar plasmaférese imediatamente.","C":"Sepse por infecção bacteriana ? iniciar ciprofloxacina endovenoso.","D":"Púrpura trombocitopênica trombótica ? iniciar rituximab."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-259730","number":"259730","sourceNumber":"259730","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Gabriel, 5 anos de idade, há 2 meses vem apresentando palidez cutâneo-mucosa\nprogressiva e febre moderada. Há 15 dias, mãe\nnotou o aparecimento de petéquias e equimoses e\nrefere que seu filho acorda com dor óssea de forte intensidade em membros inferiores que pouco\ncede com analgésicos comuns. Ao exame físico, apresenta palidez cutâneo-mucosa (++/4+),\nhepatoesplenomegalia e petéquias e equimoses em membros inferiores e região torácica.\n\nRealizado hemograma que evidenciou anemia, leucocitose e plaquetopenia. O diagnóstico mais\nprovável de Gabriel é:","options":{"A":"Leucemia aguda.","B":"Anemia falciforme.","C":"Leishmaniose visceral.","D":"Artrite idiopática juvenil."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-173025","number":"173025","sourceNumber":"173025","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de 11 anos de idade chega ao ambulatório por linfoadenopatias afebril,\nlocalizada na região cervical de início há\ncerca de dois meses; os pais relatam aumento progressivo\ndesses gânglios e perda de peso acentuada nos últimos meses. Não há outros sintomas. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Tuberculose ganglionar.","B":"Linfoma não-Hodgkin.","C":"Leucemia linfoide.","D":"Toxoplasmose."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-150826","number":"150826","sourceNumber":"150826","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Você atende uma criança de oito anos de idade com adenopatia cervical, indolor, de\ninício há 4 semanas. Com a história clínica, você fica sabendo de outros sintomas clínicos tipo:\nsudorese noturna, perda de peso e febre ocasional. Ao exame físico, não há esplenomegalia. É\ndetectado assimetria de tonsilas palatinas. Qual a principal hipótese diagnóstica?","options":{"A":"Linfoma.","B":"Histiocitose.","C":"Neuroblastoma.","D":"Doença de arranhadura do gato."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-126962","number":"126962","sourceNumber":"126962","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menino de 9 anos é encaminhado ao ambulatório de pediatria por apresentar gânglio\ncervical anteroinferior unilateral palpável há 6\nsemanas, indolor, sem sinais inflamatórios, com 3 cm\nde diâmetro. Apresenta bom estado geral sem outras queixas. A conduta adequada nesse caso é:","options":{"A":"Solicitar sorologia para mononucleose, pois o quadro descrito é característico.","B":"Iniciar de imediato antibioticoterapia, pois o quadro clínico é clássico de adenite cervical\npiogênica.","C":"Aguardar e reavaliar em duas semanas, pois a hipótese mais provável é adenite cervical viral,\nde evolução benigna.","D":"Iniciar investigação imediata pelas características apresentadas no caso, que inclui as\nneoplasias como doença de Hodgkin, leucemias ou outra forma de linfoma."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-65755","number":"65755","sourceNumber":"65755","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma jovem de 25 anos de idade há um mês apresentou quadro de massa cervical à\nesquerda, medindo 4,5 x 4,5 cm. Na avaliação, a radiografia de tórax mostrou presença de\nadenopatia hilar esquerda. Ao exame físico, a jovem apresentava-se com estado geral bom,\ncorada, normotensa, sem outras adenopatias ou visceromegalias palpáveis. Foi realizada biópsia\nda lesão cervical, cuja microscopia está reproduzida a seguir (hematoxilina-eosina, 400x). (VER\nIMAGEM) O diagnóstico mais provável é de:","options":{"A":"Linfoma de Burkitt.","B":"Linfoma de Hodgkin.","C":"Linfoma linfoplasmocítico.","D":"Linfoma de zona marginal nodal.","E":"Linfoma de grandes células B mediastinal."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-51208","number":"51208","sourceNumber":"51208","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 58 anos foi encaminhado ao ambulatório de Nefrologia por apresentar, em\nexame de rotina, ureia sérica de 78 mg/dl,\ncreatinina sérica de 1,8 mg/dl, creatinina urinária de 80\nmg/dl, volume urinário de 24h de 1440 ml. Sua superfície corporal é de 1,73 m². Relata diabetes\nmellitus há 15 anos, sendo tratado com glibenclamida 5 mg/dia e metformina 1.000 mg/dia. Exame\nfísico: estado geral bom, PA = 120/80 mmHg, auscultas cardíaca e pulmonar normais, abdome e\nmembros inferiores sem alterações. Qual a análise correta quanto à extensão da lesão renal desse\npaciente?","options":{"A":"A taxa de filtração glomerular calculada se encontra no estágio V da doença renal crônica.","B":"A taxa de filtração glomerular calculada se encontra no estágio III da doença renal crônica.","C":"A taxa de filtração glomerular está abaixo de 15 ml/min devendo-se considerar tratamento\ndialítico.","D":"A taxa de filtração glomerular calculada se encontra no estágio IV da doença renal crônica,\nprovavelmente devido à nefropatia diabética."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-141601","number":"141601","sourceNumber":"141601","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual o distúrbio hidroeletrolítico mais comumente relacionado à hemodiálise?","options":{"A":"Hipocalemia.","B":"Hipercalemia.","C":"Hiponatremia.","D":"Hipernatremia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-45370","number":"45370","sourceNumber":"45370","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 40 anos, pesando 72 Kg, apresenta volume urinário total de 100 mL nas\núltimas 24h. A creatinina sérica atual é 2 mg/dL. Considerando que o mesmo tinha função renal\nnormal até há 2 dias, qual o clearance de creatinina (em mL/min/1,73 m²) deste paciente?","options":{"A":"\"menor que\" 30","B":"42,5","C":"50","D":"75","E":"100"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-36996","number":"36996","sourceNumber":"36996","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 65 anos, portador de diabetes mellitus tipo 2, necessita de realização de\ntomografia contrastada. Qual das estratégias abaixo é a mais efetiva na proteção da função renal?","options":{"A":"Uso de n-acetilcisteína IV.","B":"Hidratação venosa com solução salina.","C":"Uso de corticoides e anti-histamínicos.","D":"Uso de gadolínio no lugar de contraste iônico."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-36965","number":"36965","sourceNumber":"36965","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menino de 2 anos de idade está há 6 dias apresentando dor abdominal, vômitos e\ndiarreia. Nos primeiros 3 dias de doença, teve febre. Não apresentou desidratação em nenhum\nmomento. A mãe começou a perceber oligúria, palidez e no exame físico foram observadas\npetéquias e equimoses. O patógeno mais comumente envolvido nesse caso é:","options":{"A":"Escherichia coli.","B":"Enterococcus sp.","C":"Entamoeba histolylitica.","D":"Adenovírus."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-30878","number":"30878","sourceNumber":"30878","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 40 anos, acompanhado ambulatorialmente por insuficiência hepática, é\ninternado para controle de anasarca. No primeiro dia de internamento pesava 80 kg, sendo\nsubmetido à terapia diurética e controle de dieta. No terceiro dia estava com 70 kg, redução\nimportante do edema, porém com náuseas e sonolência. A revisão dos exames mostrou elevação\nprogressiva da creatinina sérica (Cr) em mg/dl: Admissão = 0,3; Segundo dia = 0,6; Terceiro dia =\n1,6. Qual o clearance de creatinina (em ml/min/1,73 m²) deste paciente no terceiro dia de\ninternamento?","options":{"A":"Menor que 20.","B":"Entre 20 e 40.","C":"Entre 40 e 60.","D":"Entre 60 e 80.","E":"Maior que 80."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-27703","number":"27703","sourceNumber":"27703","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 60 anos é avaliado durante plantão. Está internado há 4 dias para\ntratamento de neutropenia febril e há 36\nhoras não apresenta diurese. Exame físico evidenciou\nmucosas algo ressecadas e taquicardia leve (110 bpm). Sondagem vesical extraiu mínima\nquantidade de urina (< 10 ml). Além de outras condutas, é solicitada a correção da dose do\nantibiótico em uso para a função renal. O paciente pesa 60 kg, tem 1,60 m de altura. Exame da\nurgência mostra creatinina = 2,5 mg/dl. Com base nos dados expostos, assinale o item que\ncontenha o clearance de creatinina deste paciente.","options":{"A":"< 11.","B":"11 ? 29.","C":"30 ? 59.","D":"60 ? 90.","E":"> 90."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-25295","number":"25295","sourceNumber":"25295","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 52 anos, tabagista, diabético, hipertenso, evoluindo com insuficiência renal\nrapidamente progressiva e indicação de tratamento dialítico, necessitando de acesso vascular para\nhemodiálise. Qual das opções abaixo é a mais correta?","options":{"A":"Implante de catéter de curta permanência para hemodiálise em veia subclávia direita.","B":"Implante de catéter de longa permanência em veia jugular esquerda.","C":"Realização de fístula arteriovenosa com enxerto de PTFE braquioaxilar no membro superior não\ndominante.","D":"Implante de catéter de curta permanência para hemodiálise em veia jugular interna.","E":"Realização de fístula arteriovenosa radiocefálica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-7297","number":"7297","sourceNumber":"7297","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar de 8 anos de idade, após rash grosseiro e pruriginoso, apresenta edema\nabrupto, hipertensão arterial, dispneia, oligúria,\nhematúria macroscópica e proteinúria discreta. Os\nexames mais importantes para o diagnóstico e acompanhamento do prognóstico seriam:","options":{"A":"sumário de urina e antiestreptolisina.","B":"sumário de urina e complemento C3.","C":"dosagem de proteínas e lipídeos séricos.","D":"proteinúria de 24 horas e eletroforese de proteínas.","E":"antiestreptolisina O e complemento C3."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-6948","number":"6948","sourceNumber":"6948","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menina, 5 anos, apresenta edema, hipertensão e hematúria. Há 2 semanas teve\npiodermite. Qual exame complementar durante o seguimento clínico dessa criança apresenta\nmelhor valor prognóstico?","options":{"A":"Sumário de urina.","B":"Complemento.","C":"Ureia.","D":"Ultrassonografia abdominal.","E":"Antidesoxirribonuclease."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-17808","number":"17808","sourceNumber":"17808","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 62 anos é avaliado de forma rotineira no ambulatório de Clínica Médica e\nretorna trazendo seus exames. Todos os resultados encontram-se normais, exceto a pesquisa de\nsangue oculto nas fezes: das três amostras seriadas colhidas, uma foi positiva. O paciente\nencontra-se bem disposto e sem quaisquer queixas ou alterações de exame físico. Qual o próximo\npasso a ser adotado?","options":{"A":"Repetir a pesquisa de sangue oculto em fezes","B":"Dispensar o paciente e reavaliá-lo após um ano","C":"Solicitar endoscopia digestiva alta","D":"Solicitar colonoscopia","E":"Dispensar o paciente e reavaliá-lo após 6 meses"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-349700","number":"349700","sourceNumber":"349700","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A respeito de doenças hematológicas em crianças, assinale a alternativa correta.","options":{"A":"A anemia falciforme é uma doença genética e adquirida que afeta os glóbulos vermelhos do\nsangue.","B":"A Leucemia Linfocítica Aguda (LLA) se origina nas células linfoides, que são um tipo de glóbulo\nbranco, e tem uma evolução rápida. A causa da maioria dos casos é desconhecida, mas envolve\nalterações no DNA das células da medula óssea.","C":"Na anemia falciforme, os glóbulos vermelhos são ovalados e muito flexíveis, podendo causar\nobstrução dos vasos, dor, inflamação e lesão de órgãos.","D":"Em crianças, as causas menos comuns de anemia macrocítica são a deficiência de vitamina\nB12 ou de ácido fólico.","E":"A anemia falciforme pode ser tratada com medicamentos, e a cura ocorre antes dos dez anos de\nidade."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-305325","number":"305325","sourceNumber":"305325","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Distinguir um linfonodo inflamatório de um neoplásico pode ser um desafio para o\npediatra. Qual das situações a seguir sugere benignidade, sem necessidade de investigação?","options":{"A":"Ausência de linfonodos palpáveis em recém-nascidos.","B":"Nódulo linfático maior que 1 cm, em dois locais anatômicos.","C":"Linfonodo epitroclear com 0,7 cm.","D":"Linfonodo inguinal com 2 cm.","E":"Linfonodomegalia localizada, com febre por mais de 7 dias."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274398","number":"274398","sourceNumber":"274398","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Os exames laboratoriais são fundamentais no diagnóstico e no estadiamento dos\nlinfomas não Hodgkin. Em relação ao tema, assinale a alternativa CORRETA.","options":{"A":"O hemograma está sempre alterado.","B":"A velocidade de hemossedimentação, muito específica, costuma estar aumentada.","C":"A desidrogenase lática está tão mais elevada quanto a quantidade de células tumorais e a\nintensidade de apoptose e, quanto mais elevada, pior o prognóstico.","D":"Mielograma, para avaliar a infiltração medular, deve ser feito em um único ponto e deve ser\navaliado somente através do exame microscópico direto.","E":"A imunofenotipagem não está indicada para a maioria dos pacientes."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-255714","number":"255714","sourceNumber":"255714","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 50 anos de idade com eritema marginatum, pancardite, nódulos\nsubcutâneos, febre e artralgia procurou o\nreumatologista para receber um diagnóstico. Além disso,\napresentava anúria e atrito pericárdico. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Tratamento com hemodiálise nunca é considerado em\ncontextos infecciosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-239347","number":"239347","sourceNumber":"239347","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 64 anos de idade, acamado, é recebido, junto a dois familiares, em seu\ndomicílio por equipe de Estratégia de Saúde da Família. Os familiares demonstram possuir diversas\ndúvidas quanto ao prognóstico da doença apresentada pelo paciente, diagnosticado com linfoma\nde Hodgkin há três meses, com metástases extranodais de acordo com investigação da equipe de\noncologia assistente, a qual instituiu manejo de conforto para cuidados paliativos na última\ninternação hospitalar há duas semanas, com prescrição de morfina para uso domiciliar. Um dos\nfamiliares acompanhantes afirma que está gravando o áudio do atendimento atual sem aviso prévio\ne alega que gostaria de pausá-lo, para mostrar a gravação realizada na referida internação\nhospitalar, com as orientações fornecidas pela equipe de oncologia assistente, questionando se a\nconduta dos profissionais não se trata de erro médico. Na gravação, escutam-se as explicações\ncompatíveis com planos de início de medidas que focassem no bem-estar do paciente, garantindo\num final de vida digno e com menor sofrimento, haja vista presença de estágio de terminalidade.\n\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\ndoença de base do paciente (linfoma de\nHodgkin) possui prevalência maior na população com\ninfecção por HIV do que a média populacional geral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-196673","number":"196673","sourceNumber":"196673","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Certo paciente de 35 anos de idade compareceu a uma consulta, informando histórico\nde febre, emagrecimento e linfonodomegalias\nmediastinais, sendo que há linfonodos de 3 cm em\ncadeia paratraqueal esquerda e paratraqueal direita. Ele também apresenta linfonodomegalia em\ncadeias axilares e inguinais. Diante desse quadro, é levantada a hipótese de linfoma. A respeito\ndesse caso clínico, julgue o item a seguir. Deve-se indicar mediastinoscopia, pois a cadeia\nparatraqueal, além de ser bem abordada, oferece um linfonodo de melhor rendimento para o\ndiagnóstico de linfoma, se comparado ao inguinal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-131807","number":"131807","sourceNumber":"131807","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação à insuficiência renal aguda, assinale a alternativa correta.","options":{"A":"Nesse caso, ocorre a queda acentuada da concentração sérica da creatinina.","B":"O uso de bloqueadores do receptor de angiotensina (BRA) tem efeito protetivo para lesão\nirreversível na insuficiência renal aguda.","C":"A terapia com vasodilatadores potentes deve ser a primeira medida adotada quando a causa da\ninsuficiência renal aguda for depleção de volume.","D":"Quando o paciente é portador de cirrose hepática, pode ocorrer insuficiência renal aguda por\nvasodilatação periférica e shunt arteriovenoso.","E":"Para aumentar a perfusão renal, utilizam-se anti-inflamatórios não esteroides (AINEs)."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-82045","number":"82045","sourceNumber":"82045","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem de trinta e oito anos de idade chegou ao ambulatório de clínica médica com\nrelato de diminuição da diurese e fraqueza, com evolução havia vários meses. Seus exames\ncomplementares mostraram: creatinina sérica = 5,2 mg/dl; ureia = 123 mg/dl e potássio = 3,5\nmEq/L. Realizou-se hemograma completo, no qual não foram verificadas alterações no leucograma\ne nas plaquetas. O eritrograma mostrou: eritrócitos = 3,8 x 10? céls/L (valores de referência =\n\n4,3-5,7 x 10? céls/L); hematócrito = 33% (valores de referência = 39-49%); hemoglobina = 11 g/dl\n(valores de referência = 13,5-17,5 g/dl); volume corpuscular médio = 85 (fl) (valores de referência\n=\n80-98 fl); hemoglobina corpuscular média = 30 pg/cél (valores de referência = 26-34 pg/cél);\nconcentração de hemoglobina corpuscular média = 32% (valores de referência = 31-35%). Com\nbase no caso clínico apresentado e acerca da interpretação do eritrograma, julgue o item a seguir:\nos achados desse eritrograma expressam a alteração mais comum do principal diagnóstico em tela\ne tem como principal base etiofisiopatogenética a redução da produção de eritropoetina.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-366241","number":"366241","sourceNumber":"366241","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Trata-se\nde vírus pertencente à família herpersviridae composto de DNA linear de fita dupla.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-366240","number":"366240","sourceNumber":"366240","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Durante\nou logo após a quadro, pode ocorrer uma complicação neurológica, na qual acontece o fenômeno\nde metamorfopsia que podem durar entre 4 e 6 semanas, também conhecida como \"Síndrome de\nAlice no País das Maravilhas\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-366239","number":"366239","sourceNumber":"366239","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. Entre as\nneoplasias malignas associadas, incluem-se Linfoma de Burkitt Africano, Linfoma de Hodgkin bem\ncomo o carcinoma nasofaríngeo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-334882","number":"334882","sourceNumber":"334882","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 40 anos de idade, com diagnóstico de leucemia mieloide aguda e\nneutropenia, apresenta quadro de febre de 39 ºC, em uso de esquema antimicrobiano constituído\npor vancomicina e carbapenêmico há cinco dias. O exame físico não mostra evidência clínica que\njustifique a persistência da febre, e o hemograma realizado tem resultado semelhante ao feito\nquando do início do tratamento do paciente. Assinale a alternativa que indica a medida mais\nadequada nesse caso.","options":{"A":"Suspender o esquema antimicrobiano.","B":"Realizar uma punção liquórica.","C":"Acrescentar um fármaco antifúngico ao esquema prescrito.","D":"Solicitar uma transfusão de sangue.","E":"Indicar o transplante de medula."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-263417","number":"263417","sourceNumber":"263417","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente com 45 anos de idade apresenta queixa de astenia, mal-estar e tosse\nseca persistente. Ela procurou assistência médica\nem Unidade Básica de Saúde. Em seu exame\nfísico, notou-se adenomegalia cervical bilateral, sem outros achados. Foi realizada a radiografia de\ntórax, conforme exibido na imagem. No atendimento ambulatorial, foi realizada a biópsia de um dos\nnódulos que revelou células gigantes, multinucleadas em aspecto de \"olhos de coruja\" e do subtipo\nesclerose nodular. De acordo com os achados radiográficos e histopatológicos, a conduta indicada\né encaminhar a paciente para","options":{"A":"rede UNACON/CACON de assistência oncológica.","B":"hospital terciário para tratamento especializado em infectologia.","C":"hospital terciário para tratamento especializado em Cirurgia Torácica.","D":"hospital terciário para tratamento especializado em Cirurgia de Cabeça e Pescoço."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-244477","number":"244477","sourceNumber":"244477","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 19 anos de idade, estudante, foi atendido na emergência do hospital\nem decorrência de quadro de febre, dores\nmusculares, vômitos e tosse seca, associado a dispneia\nprogressiva e iniciado há seis horas. Há 10 dias, fez quimioterapia de consolidação para leucemia\nlinfoblástica aguda (LLA) de células B precursora. Seus medicamentos atuais são bactrim\nprofilático. Sinais vitais de admissão: temperatura = 38,6 ºC, FR = 26 irpm, FC = 104 bpm, PA = 98\nmmHg x 64 mmHg, SatO2 = 93% em ar ambiente. Exames laboratoriais: contagem de leucócitos =\n540 mm3 (VR = 4.000-12.000), contagem absoluta de neutrófilos (CAN) = 30 células/µ (VR =\n1.200-8.000); Hb = 7,1 g/d (VR = 12-15), hematócrito = 23,1% (VR = 35-50), contagem de\n\nplaquetas = 3.000 µL (VR = 140.000-450.00) e nível de glicose = 50 mg/dL (VR = 7-100). Com base\nnesse caso clínico e nos conhecimentos\nmédicos correlatos, assinale a alternativa correta.","options":{"A":"O paciente deverá iniciar, na admissão de urgência, com antifúngico parenteral do espectro de\nanfotericina ou voriconazol em razão do risco de germes filamentosos pelo quadro de neutropenia\nfebril.","B":"A transfusão de plaquetas nesse paciente deve ser indicada apenas nos casos de sangramento\ncutâneo mucoso, independentemente da contagem\nde plaquetas.","C":"O paciente necessita de exames complementares de imagem de urgência (tomografia de tórax)\nantes da definição da antibioticoterapia.","D":"A terapia precoce direcionada a esse paciente inclui ressuscitação hídrica, monitorização e\nadministração precoce de agentes antimicrobianos de amplo espectro. Essas intervenções\ncomprovadamente diminuem a taxa de mortalidade nesse perfil de paciente.","E":"O uso de G-CSF reduz a necessidade de uso de antibiótico de amplo espectro em decorrência\nda rápida recuperação imunológica, podendo ser\niniciado antibiótico betalactâmico oral para o\nreferido paciente."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-203008","number":"203008","sourceNumber":"203008","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 28 anos de idade, vítima de acidente de motocicleta, deu entrada no\npronto-socorro com quadro de dor abdominal, pressão arterial de 90 mmHg x 40 mmHg e\nfrequência cardíaca de 120 bpm. Ao exame físico, estava consciente e orientado e apresentava dor\nà palpação no abdome. O paciente foi submetido à laparotomia, com achado de lesão esplênica, e\nfoi realizada esplenectomia. Quais achados são possíveis no pós-operatório?","options":{"A":"Fístula colônica e plaquetopenia.","B":"Fístula pancreática e plaquetopenia.","C":"Fístula colônica e plaquetose.","D":"Fístula pancreática e plaquetose.","E":"Fístula gástrica e plaquetopenia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-203101","number":"203101","sourceNumber":"203101","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Quanto à Leucemia Mieloide Crônica (LMC), assinale a alternativa correta.","options":{"A":"O esfregaço do sangue periférico mostra leucocitose com desvio escalonado, com neutrófilos\napresentando granulações tóxicas, associados a elevação do VHS e PCR.","B":"A presença de anemia, esplenomegalia e trombocitopenia (contagem de plaquetas inferior a\n90.000) são achados comuns ao diagnóstico e são critérios de doença crônica (considerada fase\nindolente da doença).","C":"É considerada doença indolente semelhante à Leucemia Linfocítica Crônica (LLC) e deve ser\nmonitorada sem tratamento até critérios clínicos de início de tratamento como: trombocitopenia,\npresença de blastos na periferia acima de 10% e basofilia.","D":"As translocações envolvendo os cromossomos 9 e 22 são presentes em 90% a 95% dos casos,\nsendo o respectivo gene de fusão o gene\nBCR-ABL.","E":"Os inibidores de tirosina quinase (TKI) não modificaram a sobrevida média desses pacientes,\nque continua sendo de quatro anos a partir da fase\nacelerada da doença."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-212057","number":"212057","sourceNumber":"212057","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente de 28 anos de idade, percebendo uma massa indolor em crescimento\nlento no lado esquerdo do pescoço, procurou\num clínico geral. A paciente tinha sudorese noturna e\nepisódios de febre de 38°C, sem motivo aparente. Depois de ela negar existência de infecções no\ntrato respiratório superior e perda de peso, o médico constatou que não havia mais alterações\ndignas de nota. No exame físico, encontrava-se afebril, com sinais vitais dentro da normalidade,\nmas foi encontrada uma massa de 4 cm, móvel, firme, arredondada e indolor à palpação na metade\ndireita do pescoço. Não tinha outra linfadenopatia periférica. O fígado e o baço não estavam\naumentados. O médico levantou a hipótese diagnóstica de linfoma de Hodgkin. A partir do caso\nclínico descrito, julgue o item a seguir. O método mais adequado para a confirmação do diagnóstico\nem tela é a punção aspirativa da massa cervical com agulha fina, seguida pela realização de cortes\nde tecido, buscando-se o reconhecimento do Vírus do Epstein-Barr (VEB).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-183941","number":"183941","sourceNumber":"183941","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Julgue o item seguinte, a respeito da doença de Chagas. A fase crônica indeterminada\né a mais frequente em portadores da doença\nde Chagas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-168515","number":"168515","sourceNumber":"168515","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma mulher com 66 anos de idade foi encaminhada ao ambulatório de hematologia de\num hospital geral para investigação\ndiagnóstica de pancitopenia. Em consulta, a paciente refere\nastenia progressiva nos últimos 3 meses e relata também que passou a apresentar, há 2 semanas,\npetéquias e gengivorragia. Diante disso, procurou atendimento médico, quando foi realizado\nhemograma completo que revelou anemia normocítica normocrômica, com baixa contagem de\nreticulócitos, leucopenia com diferencial normal e plaquetopenia. Um exame hematoscópico revelou\na presença de elevada porcentagem de dacriócitos (\"hemácias em lágrima\"). Nessa situação, qual\né o diagnóstico mais provável da paciente e que exame complementar deve ser solicitado para sua\nconfirmação?","options":{"A":"Mielofibrose; biópsia de medula óssea.","B":"Leucemia mieloide aguda; aspirado de medula óssea.","C":"Mielodisplasia; citometria de fluxo de sangue periférico.","D":"Aplasia de medula óssea; sorologia para parvovírus B19."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-154472","number":"154472","sourceNumber":"154472","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente feminino, de 3 anos, comparece ao pronto atendimento acompanhada de sua\nmãe com queixa de tosse seca há 6 semanas,\ndor no corpo persistente, discreto edema de joelhos,\nhiporexia, adinamia e febre baixa há 10 dias. Ao exame físico apresenta palidez cutaneomucosa,\nausculta cardíaca com sopro sistólico suave 1+/6+ em mesocárdio, fígado palpável a 3 cm do RCD\ne baço a 2 cm do RCE. Hemograma mostrava Hb 8,7 g/dL; Ht 25% com normocitose e\nnormocromia; 3850 leucócitos e 56% de linfócitos. A principal hipótese diagnóstica ao atender a\ncriança deverá ser:","options":{"A":"Febre reumática.","B":"Síndrome mononucleose-like.","C":"Artrite Idiopática Juvenil.","D":"Lúpus Eritematoso Sistêmico.","E":"Leucemia Linfóide Aguda."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-159537","number":"159537","sourceNumber":"159537","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de cinquenta anos de idade procurou atendimento médico queiando-se de\nfadiga, perda de peso, mal-estar e empachamento pós-prandial. Em seu exame clínico, o achado\nde destaque foi esplenomegalia. O hemograma apresentou os seguintes resultados: leucocitose =\n\n320.000 leucócitos/mL, com predominio de neutrotófilos e desvio à esquerda, estendendo-se até\nblastos; basofilia e eosinofilia presentes; plaquetas com contagem normal; e anemia normocrêmica\ne normocítica discreta. Ademais, constatou-se a presença do cromossomo Filadélfia (Ph) em\ncélulas da medula óssea. Com relação a esse caso clínico, julgue o próximo item. No caso em\napreço, o principal diagnóstico é leucemia mieloide crônica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-158044","number":"158044","sourceNumber":"158044","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Determinado paciente, 72 anos de idade, comparece ao pronto-socorro queixando-se\nde que, há vários meses, evolui com cefaleia\nholocraniana, turvação visual, face e olhos\navermelhados e prurido generalizado após o banho. Começou também a apresentar pressão alta,\nsendo que realiza consultas médicas anuais sem detecção de nenhuma patologia. Ao exame físico,\nnotam-se hepatomegalia e PA = 180 mmHg x 100 mmHg, eritema conjuntival e face eritematosa.\n\nFoi realizado hemograma que revelou hemoglobina = 19 mg/dL, leucócitos = 15.700 e plaquetas =\n500 mil. Acerca desse caso clínico, assinale\na alternativa CORRETA.","options":{"A":"O tratamento envolve fludarabina e rituximab.","B":"O transplante de medula óssea é o tratamento de escolha para a maioria dos pacientes.","C":"O uso de sangrias terapêuticas é indicado.","D":"A anticoagulação é indicada em razão da hiperviscosidade sanguínea.","E":"A mutação JAK 2 confirma o diagnóstico e é exigida para ele."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-168487","number":"168487","sourceNumber":"168487","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma menina com 8 anos de idade encontra-se internada em unidade hospitalar para\ntratamento de leucemia linfoide aguda. Cerca de 15 dias após uma sessão de quimioterpia, a\npaciente apresenta episódio de febre de 38.5 ºC. Ao exame, verifica-se que a frequência cardíaca,\na frequência respiratória e a pressão arterial estão normais para a idade, não havendo nenhum\nsinal de localização da febre. O hemograma vem mantendo contagem de neutrófilos abaixo de 500\ncélulas/mm³ nos últimos 7 dias. A conduta apropriada a ser adotada para essa paciente é","options":{"A":"colher hemocultura (2 amostras) e urinocultura, realizar radiografia de tórax e tomografia de\nseios da face, e iniciar antibioticoterapia de acordo com os resultados dos exames","B":"colher hemocultura (2 amostras), avaliar a realização de radiografia de tórax e uroanálise, e\niniciar antibioticoterapia empírica de amplo espectro","C":"tratar o caso como choque séptico, iniciando expansão volêmica e antibioticoerapia empírica de\namplo espectro","D":"iniciar antibioticoterapia empírica de amplo espectro, após serem afastadas as causas não\ninfecciosas da febre"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-168484","number":"168484","sourceNumber":"168484","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança do sexo masculino com 5 anos de idade apresenta, há 3 semanas, astenia\ne febre baixa diária, redução do apetite e\nmanchas arroxeadas nos membros. Além disso, acorda\nquase todas as noites com queixa de dores em membros inferiores. Ao exame físico, ela apresenta\nhepatoesplenomegalia, equimoses em membros inferiores e poliadenomegalia. O hemograma\nevidencia anemia normocítica e normocrômica, contagem de leucócitos normal (9.000\nlecócitos/mm³), com linfocítose e presença de linfócitos atípicos e plaquetopenia (80.000\nplaquetas/mm³). A dosagem de desidrogenase lática mostra-se elevada. Pesquisa de anticorpo\nanticapsídeo viral de Epstein Barr e sorologia para citomegalvírus evidenciam IgG positivo e IgM\nnegativo. A velocidade de hemossedimentação (VHS) está elevada e as aminotransferases estão\nnormais. De acordo com o presente quadro clínico-laboratorial o diagnóstico é","options":{"A":"mielofibrose.","B":"artrite idiopática juvenil.","C":"mononucleose infecciosa.","D":"leucemia linfoblástica aguda."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-159526","number":"159526","sourceNumber":"159526","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O item a seguir apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a propósito da fisiopatologia, do diagnóstico precoce e do tratamento de doenças em\ncrianças e adolescentes. Um médico assistiu a um parto e observou, na história clínica materna,\nque a parturiente é portadora de doença de Chagas na fase indeterminada, e suspeitou que o\nrecém-nascido pudesse estar infectado por via transplacentária. Nesse caso, um método eficaz\npara o diagnóstico da infecção congênita é a realização da pesquisa do Trypanosoma cruzi no\ncreme leucocitário.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-104746","number":"104746","sourceNumber":"104746","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à Injúria (Insuficiência) Renal Aguda (IRA) do tipo intrínseca, assinale a\nalternativa CORRETA:","options":{"A":"Nunca é precedida por IRA pré-renal.","B":"Na maioria das vezes, é secundária à IRA pós-renal.","C":"Ocorre mais frequentemente em adolescentes.","D":"É sempre reversível.","E":"Pode ser causada por ingestão de altas doses de anti-inflamatórios não esteroidais."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-80738","number":"80738","sourceNumber":"80738","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Para avaliar a ingestão de álcool e a função renal, os melhores marcadores bioquímicos\nsão, respectivamente:","options":{"A":"Gama-Glutamil-Transpetidase (GGT) e creatinina.","B":"Fosfatase alcalina e ureia.","C":"TGO e creatinina.","D":"TGP e ureia.","E":"Fosfatase ácida e creatinina."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-97833","number":"97833","sourceNumber":"97833","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem com 30 anos de idade apresenta linfadenomegalia da cadeia cervical\nposterior e subclavicular. Refere episódios\nde febre, sudorese ? principalmente no período noturno\n\n? e perda de peso. Nega outras queixas. O exame físico geral e o específico não mostraram outras\nalterações. O resultado da punção biópsia aspirativa de um linfonodo cervical foi compatível com\nlinfoma de Hodgkin. Foi realizada tomografia computadorizada de tórax e abdome que não mostrou\nmassas ou envolvimento de outras cadeias de linfonodos, além das citadas acima. Qual a opção\nterapêutica mais adequada para o paciente?","options":{"A":"Radioterapia.","B":"Cirurgia e radioterapia.","C":"Cirurgia e quimioterapia.","D":"Quimioterapia e radioterapia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-75494","number":"75494","sourceNumber":"75494","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menina com 3 anos de idade é admitida na Enfermaria de um hospital regional, no\ninterior do estado, por apresentar, há três\nsemanas, dor na região lateral do pescoço, com\nadenomegalia cervical bilateral, febre e queda do estado geral. Fez uso de anti-inflamatório não\nhormonal, tendo diminuído o desconforto, mas persistido a adenomegalia à direita, a febrícula e a\ninapetência. O exame físico mostra cadeias ganglionares cervicais bilaterialmente palpáveis, sendo\nque, à direita, palpa-se massa de consistência elástica, com aproximadamente 1 cm em seu maior\ndiâmetro, levemente dolorosa. Há, neste mesmo lado, nodulação em região supraclavicular, indolor,\ncom aproximadamente 0,8 cm em seu maior diâmetro. Hemograma: hemácias = 3.5 x 10¹²/mm³;\nhematócrito = 32%; hemoglobina = 10,4 g%; leucograma:16.000 leucócitos/mm³ - linfócitos: 65%;\nlinfócitos atípicos: 32%. A principal justificativa de transferência dessa criança para avaliação\nimediata com especialista é:","options":{"A":"febre e adenomegalia persistentes.","B":"presença de nodulação supraclavicular.","C":"dor à palpação de cadeia ganglionar cervical.","D":"hemograma com atipia linfocitária exagerada.","E":"consistência elástica de gânglio cervical à palpação."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-137585","number":"137585","sourceNumber":"137585","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um pré-escolar de 3 anos de idade foi levado ao pediatra de um pequeno\nCentro de Saúde regional para avaliação de\npalidez cutâneo-mucosa. A mãe relatou que a\ncriança sempre gozou de boa saúde. Entretanto, há cerca de 2 meses, tem se apresentado\nprostrada. Além disso, tem se mostrado cada vez mais pálida e, no último mês, surgiram\npequenas manchas vermelhas na pele. Ao exame: a criança se apresentava hipoativa,\nhipocorada 2+/4+, hidratada, anictérica e acianótica. Foi detectada poliadenomegalia cervical\ne inguinal. As auscultas respiratória e cardíaca estavam normais. O abdome estava distendido,\nflácido, indolor, com fígado palpável a 5 cm do rebordo costal direito e o baço palpável a 3 cm do\nrebordo costal esquerdo. Foi detectado rash petequial disseminado. O\n\nhemograma evidencia hematócrito de 22% (valor de referência = 36 ± 4%), hemoglobina de 7\ng/dL (valor de referência = 11,8 ± 1,2 g/dL), volume corpuscular médio de 85 fL (valor de\nreferência = 80 fL), concentração de hemoglobina corpuscular média de 32 g/dL (valor de\nreferência = 32 g/dL), 75 000 leucócitos/mm³ (valor de referência = 4 000 a 14 000\nleucócitos/mm³ ) com atipia linfocitária acima de 30%, e plaquetometria de 15 000\nplaquetas/mm³ (valor de referência = 140 000 a 400 000 plaquetas/mm³ ). Tendo em vista o\nprovável diagnóstico, qual dos fatores descritos neste caso está associado a um bom\nprognóstico para este paciente?","options":{"A":"Leucometria > 50 000 leucócitos/mm³.","B":"Plaquetometria < 150 000/mm³.","C":"Evolução de doença < 6 meses.","D":"Atipia linfocitária > 30%.","E":"Idade do paciente > 1 ano."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-359207","number":"359207","sourceNumber":"359207","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um senhor de 58 anos foi encaminhado do Serviço de Hematologia, devido a linfoma\nprimário esplênico das células da zona marginal, após tratamento com quimioterapia, já com\nindicação de tratamento cirúrgico. Nesse caso, a conduta CORRETA é indicar:","options":{"A":"Vacinação; esplenectomia com linfadenectomia e drenagem da cavidade mandatória.","B":"Vacinação; esplenectomia subtotal e drenagem da cavidade mandatória.","C":"Vacinação; esplenectomia com linfadenectomia e biópsia hepática.","D":"Esplenectomia com linfadenectomia e drenagem da cavidade mandatória, não sendo necessária\na vacinação."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-359214","number":"359214","sourceNumber":"359214","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em pacientes em uso de quimioterapia, o desenvolvimento de neutropenia pode ser\ncomum em muitos casos. Sobre este conceito, assinale a alternativa INCORRETA.","options":{"A":"A cobertura de Pseudomonas aeruginosa é realizada devido à gravidade gerada pelas infecções\npelo germe nesses pacientes, apesar de muito\nraras.","B":"A medição de temperatura retal não é recomendada em neutropênicos pelo risco de\nmicrosangramentos gerando bacteremia ou sangramentos maiores.","C":"Neutropenia grave é definida, quando há um valor absoluto de neutrófilos < 500 cels/microL.","D":"A síndrome de reconstituição mieloide se dá por um processo inflamatório novo ou a piora de um\nprévio em associação temporal com a recuperação de neutrófilos de aplasia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-368200","number":"368200","sourceNumber":"368200","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Durante o tratamento de algumas doenças oncológicas, pode aparecer a chamada\nsíndrome de lise tumoral, que vem acompanhada\nde alterações metabólicas características e que\ndevem ser abordadas prontamente. Quais são as principais alterações metabólicas na lise tumoral?","options":{"A":"Hiperuricemia, hipocalemia, hipercalcemia.","B":"Hipouricemia, hipocalcemia, hipofosfatemia.","C":"Hipercalcemia, hipercalemia, hipofosfatemia.","D":"Hiperuricemia, hipercalemia, hiperfosfatemia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-334760","number":"334760","sourceNumber":"334760","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No câncer infantil é correto afirmar:","options":{"A":"Os cânceres pediátricos mais frequentes são as leucemias, os tumores do sistema nervoso\ncentral e os linfomas.","B":"O câncer na faixa etária pediátrica geralmente é hereditário e, na maioria dos casos, apresentam\nhistória familiar e/ou associações com\nalterações genéticas ou congênitas. Entretanto, o\nretinoblastoma (tumor maligno intraocular) raramente tem origem genética.","C":"A trissomia 21 tem envolvido o gene GATA 1 que interfere na diferenciação celular. Esses\npacientes têm risco aumentado para o\ndesenvolvimento de neoplasia de sistema nervoso central\n(cerca de 10 vezes maior) e câncer de estômago.","D":"A leucemia aguda raramente acomete as crianças, possuindo um período de latência grande\ncom história tardia de surgimento dos sintomas."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-336310","number":"336310","sourceNumber":"336310","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 70 anos, hipertensa e diabética, portadora de neoplasia no estômago, em\nquimioterapia com última sessão há 1 semana. Apresenta astenia e febre há 24 horas. Ao exame:\nconfusa, PA: 80/50 mmhg, FC 112 bpm, tempo enchimento capilar lentificado, sat02 94% em ar\nambiente, FR 21 irpm, temp axilar 38,4ºC. Exames laboratoriais: hb 6,5 g/dl/ leucócitos 1000 (70%\nPMN)/ plaquetas: 44.000 | Cr 1,2 / Ur 68 / K 3,8 / Na 130 / AST 27 / ALT 32 / BT 1,0 (BD 0,2). É\n\ncorreto afirmar:","options":{"A":"Recomenda-se prescrição de salina hipertônica diante da hiponatremia sintomática.","B":"Recomenda-se a prescrição de plaquetas com alvo de manutenção >50.000.","C":"Cefepime + Vancomicina é uma opção adequada para esquema antimicrobiano empírico.","D":"O início de antibioticoterapia deve aguardar investigação complementar pormenorizada dada a\nausência de urgência."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-313276","number":"313276","sourceNumber":"313276","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Para um paciente de 29 anos, que chega ao Pronto Atendimento, com um quadro de\nfebre a esclarecer, sem queixas álgicas e com SSVV estáveis, o Clínico solicita, inicialmente, um\nhemograma. No resultado, observa-se Atipias Pelger, que o médico entender como:","options":{"A":"Alteração benigna dos leucócitos.","B":"Alteração maligna dos leucócitos.","C":"Alteração benigna da forma dos eritrócitos.","D":"Alteração maligna da forma dos eritrócitos.","E":"Alteração na contagem de plaquetas."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-313279","number":"313279","sourceNumber":"313279","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Toxoplasma gondii infecta o homem de três diferentes modos: I- Pela ingestão de\noocistos; II- Pela ingestão de cistos teciduais; III- Por infecção congênita por bradizoítos. Dos\nitens\nacima:","options":{"A":"Apenas o item I está correto.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Todos os itens estão corretos."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-313298","number":"313298","sourceNumber":"313298","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Cerca de 90% dos pacientes com Leucemia Linfocítica Aguda - LLA apresentam\nalterações laboratoriais hematológicas, no\ndiagnóstico, e estas representam o grau de envolvimento\nda Medula Óssea pelos blastos. Aproximadamente, 80% dos pacientes apresentam anemia:","options":{"A":"Macrocítica e hipocrômica, com contagem de reticulócitos alta.","B":"Microcítica e hipocrômica, com contagem de reticulócitos alta.","C":"Microcítica e normocrômica, com contagem de reticulócitos baixa.","D":"Normocítica e hipocrômica, com contagem de reticulócitos baixa.","E":"Normocítica e normocrômica, com contagem de reticulócitos baixa."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-304874","number":"304874","sourceNumber":"304874","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar, três anos e nove meses, sexo feminino, vem apresentando dores ósseas\ndifusas iniciadas há três meses, que não\nmelhoram com o uso de analgésicos comuns, associados\na febre baixa intermitente, cefaleia, vômitos frequentes, anorexia, perda ponderal de quatro quilos\ne\nirritação com prejuízo de sono. A partir do resultado do hemograma, foi diagnosticado \"anemia\ndiscreta\" tendo sido prescrito sulfato ferroso por seis meses. Há um mês, a mãe notou palidez que\nvem se acentuando. Exame físico: irritabilidade, fáceis de sofrimento, dificuldade para deambular\npela dor, hipocorada +/4+, adenomegalias cervicais, axilares e inguinais móveis, fibroelásticas, não\ncoalescentes, medindo de 0,5 a 1 cm de diâmetro, fígado palpável a 5 cm, do rebordo costal direito,\nbaço a 4 cm do rebordo costal esquerdo, petéquias em membros inferiores e sopro sistólico +/4+\npancardíaco, sem irradiação. A principal hipótese diagnóstica é:","options":{"A":"Neuroblastoma.","B":"Febre reumática.","C":"Artrite idiopática Juvenil.","D":"Leucemia linfoide aguda."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-260665","number":"260665","sourceNumber":"260665","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No ciclo de vida do toxoplasma gondii podemos afirmar:","options":{"A":"Os oocistos são eliminados nas fezes dos gatos. Uma grande quantidade é eliminada, mas,\nnormalmente, só durante 1?2 semanas. Os oocistos demoram de 1 a 5 dias para esporular e se\ntornarem infectantes.","B":"Terra, água, plantas, ou a areia do gato tornam-se infectados com oocistos. Alguns animais na\nnatureza, como pássaros, roedores, animais selvagens e animais criados para consumo de seres\nhumanos não se infectam após ingerirem materiais infectados.","C":"Os seres humanos podem se infectar pela ingestão de alimentos ou água contaminada por\nfezes de gatos ou outros materiais\ncontaminados por fezes (p. ex., terra), sendo preservados da\ncontaminação pelo contato com a areia do gato pois depende da cadeia intermediária.","D":"Com frequência, a hemotransfusão e o transplante de órgãos infectam os seres humanos\ndecorrente da carga de trofozoitos e\noocistos presentes no concentrado, uma vez que, ainda nos\ndias atuais, existe descontrole entre os doadores sadios.","E":"Os gatos não se infectam após consumirem hospedeiros intermediários contendo cistos\nteciduais devido a existência de fatores de\ndefesa produzidos por essa cadeia, e fatores intrínsecos\nainda não explicados pela ciência."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-257345","number":"257345","sourceNumber":"257345","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 69 anos, realizou hemograma que revelou anormalidade, confirmada após\nrepetição do exame. Está assintomático. É portador de diabetes mellitus, artrite reumatoide e\nobesidade grau 3. Faz uso de metformina e prednisona 20mg. É tabagista e fuma 2 maços de\ncigarros ao dia, desde os 20 anos. Exames de laboratório: Hemoglobina: 14,3g/dL; Leucócitos:\n15.630/mm3 ; Neutrófilos Segmentados: 10.200/mm3 ; Neutrófilos Bastonetes: 980/mm3 ;\nLinfócitos: 3.340/mm3 ; Eosinófilos: 340/mm3 ; Monócitos: 670/mm3 ; Basófilos: 30/mm3 ;\nPlaquetas: 268.000/mm3 ; Hemoglobina Glicada: 9,3%; Proteína C reativa: 5mg/L. Assinale a\nalternativa que NÃO apresenta uma causa provável para a anormalidade hematológica\napresentada por esse paciente:","options":{"A":"Diabetes mellitus.","B":"Obesidade.","C":"Prednisona.","D":"Tabagismo."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-266368","number":"266368","sourceNumber":"266368","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa correta sobre o linfoma de Hodgkin.","options":{"A":"O subtipo de celularidade mista é o mais comum.","B":"A apresentação infradiafragmática exclusiva implica em pior prognóstico.","C":"A ressonância nuclear magnética é considerada o exame padrão ouro para o diagnóstico inicial.","D":"Idade inferior a 45 anos e níveis de hemoglobina inferiores a 10 g/dL são fatores de pior\nprognóstico."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-234413","number":"234413","sourceNumber":"234413","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem de 43 anos, promotor de justiça, residente em Vitória/ES, vai ao pronto\natendimento com o relato de febre há 3 horas. É portador de câncer do reto, sem metástases, e\nrecebeu dose de quimioterapia há 8 dias. Não apresenta outras queixas. Nega infecções e\ninternações prévias, e não possui comorbidades. Ao exame físico, está alerta e orientado; as\nmucosas estão coradas e hidratadas. Os dados vitais são PA: 128 X 78mmHg, FC: 65bpm, FR:\n13ipm, SpO? 98%. Os exames cardiovascular, respiratório, do abdômen, da cavidade oral e da\nregião perianal não apresentam anormalidades. Foi administrada dose de piperacilina-tazobactam\npela via intravenosa enquanto se aguardavam os resultados dos exames. Exames de laboratório\n(solicitados na urgência): hemoglobina 8,9g/dL; leucócitos 1.870/mm³; neutrófilos segmentados\n280/mm³; plaquetas 95.000/mm³; proteína C reativa 46mg/L; creatinina 0,5mg/dL; ureia 15mg/dL;\nbilirrubina total 0,5mg/dL; exame de urina: sem anormalidades. Radiografia do tórax: sem\nanormalidades. Considerando o caso clínico apresentado, assinale a conduta MAIS ADEQUADA\npara esse paciente:","options":{"A":"Alta hospitalar com a prescrição de amoxicilina-clavulanato e ciprofloxacino pela via oral.","B":"Desospitalização com prescrição de meropenem pela via intravenosa para tratamento no\ndomicílio.","C":"Internação hospitalar e manutenção da prescrição de piperacilina-tazobactam pela via\nintravenosa.","D":"Internação hospitalar e substituição do antibiótico por cefepime pela via intravenosa."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-227310","number":"227310","sourceNumber":"227310","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As leucemias têm como principal característica o acúmulo de células jovens anormais,\ndenominadas de blastos, que substituem as células sanguíneas normais na medula óssea. Nas\nleucemias é CORRETO afirmar:","options":{"A":"A Leucemia Linfoide Aguda (LLA) é uma doença grave e a taxa de sobrevida atual da LLA na\ninfância é inferior a 30%.","B":"Nas LLA a idade entre 01 a 09 anos é um fator de bom prognóstico.","C":"Nas leucemias a dor óssea é rara. Quando ocorre, é mais comum nos membros superiores e é\ncontrolada com analgésicos habituais.","D":"As leucemias são raras na infância e a presença de febre significa infecção bacteriana,\nrelacionada à neutropenia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-246800","number":"246800","sourceNumber":"246800","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 5 anos, feminino, com história de dor em membros inferiores de início há\n15 dias, acompanhada de astenia, palidez,\nfebre e equimoses. Hemograma com pancitopenia. Ao\nexame físico, evidenciou-se uma hepatoesplenomegalia. O diagnóstico mais provável é:","options":{"A":"Hemofilia","B":"Febre reumática","C":"Púrpura de Henoch-Schonlein","D":"Lúpus eritematoso sistêmico","E":"Leucemia aguda"},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-196763","number":"196763","sourceNumber":"196763","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação às complicações tardias das esplenectomias totais, está correto:","options":{"A":"Pode existir uma trombocitose persistente, mas sem implicações clínicas.","B":"O principal agente da sepse pós-esplenectomia é o Streptococcus pneumoniae.","C":"A sepse é geral geralmente benigna e a mortalidade muito baixa.","D":"A imunização apenas no pós-operatório é ineficaz."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-199556","number":"199556","sourceNumber":"199556","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As linfonodomegalias (aumento dos línfonodos) localizadas ou disseminadas são\ncaracterísticas de uma enorme gama de patologias em pediatria. Nas linfonodomegalias é\nCORRETO afirmar:","options":{"A":"Linfonodomegalia localizada, com febre por mais de 7 dias descarta linfomas, lúpus eritematoso\nsistêmico e tuberculose.","B":"O ácido úrico é encontrado em quantidade elevada nas células neoplásicas e pode estar\naumentado nas linfonodomegalias por linfomas e/ou leucemias.","C":"É mais evidente e frequente no período neonatal, pois o tecido linfático está aumentado de\nvolume para proteger o recém-nascido da\nexposição a antígenos que acontece durante a infância.","D":"Os linfonodos retroauriculares e supraclaviculares são considerados reacionais."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-174371","number":"174371","sourceNumber":"174371","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma das formas de transmissão ao homem da Doença de Chagas é através da picada\nde...","options":{"A":"anofelinos, quando infectadas.","B":"amblyomma cajennense.","C":"flebotomíneos infectadas.","D":"culex pipiens infectados.","E":"triatomíneos infectados."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-188003","number":"188003","sourceNumber":"188003","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 59 anos, hipertenso de longa data, portador de insuficiência cardíaca e doença\nrenal crônica dialítica há 3 anos (3 sessões semanais de hemodiálise às segundas, quartas e\nsextas), anúrico. Faz uso de losartan 100 mg/dia, carvedilol 6,25 mg 2x/dia e digoxina 0,25 mg/dia.\nNo último sábado, participou de um almoço familiar, deixando a dieta de lado. Domingo à tarde,\napós uma soneca, acordou com fraqueza intensa nas pernas, o que o impediu de andar. Foi levado\nao pronto socorro por sua esposa, onde foi realizado rapidamente um eletrocardiograma que\napresentou ondas T apiculadas, QRS largo e ausência de onda P. O exame de sangue mostrou\nPotássio sérico 9,0 mEq/L (valor de referência: 3,5 a 5,0 mEq/L). Qual é a primeira medida a ser\nfeita no caso acima?","options":{"A":"Propranolol.","B":"Gluconato de cálcio.","C":"Furosemida.","D":"Resina de troca.","E":"Hemodiálise."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-172752","number":"172752","sourceNumber":"172752","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar com história de linfadenomegalia simétrica, palidez cutâneo-mucosa, febre,\nhepatoesplenomegalia, dor óssea e manifestações hemorrágicas nos membros. Qual o diagnóstico\nmais provável?","options":{"A":"Mononucleose infecciosa.","B":"Leucemia aguda.","C":"Linfoma de Hodgkin.","D":"Imunodeficiência primária."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-148574","number":"148574","sourceNumber":"148574","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com história de febre há 12 dias, associada a mialgia leve e artralgia. Durante\no exame físico, foram encontrados linfonodos\ncervicais palpáveis em cadeias cervical anterior e\nposterior, dolorosos à palpação, de consistência elástica e não aderidos aos planos profundos.\n\nDevem estar presentes as seguintes etiologias no diagnóstico diferencial:","options":{"A":"Tuberculose ganglionar, histoplasmose disseminada, toxoplasmose, infecção por Epstein-Barr.","B":"Infecção aguda pelo HIV, tuberculose ganglionar, dengue, infecção por citomegalovírus.","C":"Sífilis, infecção por citomegalovírus, leptospirose, rubéola.","D":"Infecção aguda pelo HIV, doença de Chagas, infecção por Epstein-Barr e aspergilose invasiva.","E":"Aspergilose invasiva, sífilis, infecção por citomegalovírus, infecção aguda pelo HIV."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-106397","number":"106397","sourceNumber":"106397","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 70 anos apresenta quadro de desidratação. Sua creatinina na\nadmissão era de 3,5 mg/dl e, após hidratação vigorosa, caiu para 2,1 mg/dl, dois dias após a\nadmissão. Ele está melhor, mas relata dor intensa na região dorsal. O clínico responsável pelo\npaciente prescreveu ibuprofeno para a analgesia. Por qual mecanismo este medicamento pode\ncomprometer a função renal deste paciente?","options":{"A":"Vasoconstrição da arteríola renal aferente.","B":"Vasodilatação arteriolar renal aferente.","C":"Vasoconstrição arteriolar renal eferente.","D":"Toxicidade tubular proximal.","E":"Obstrução ureteral."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-106408","number":"106408","sourceNumber":"106408","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual a principal causa de morte em pacientes com doença renal crônica?","options":{"A":"Doença cardiovascular.","B":"Hiperpotassemia.","C":"Infecção.","D":"Neoplasia maligna.","E":"Uremia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-77622","number":"77622","sourceNumber":"77622","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"João, 49 anos, tabagista, obeso, tem doença renal crônica, em tratamento conservador,\ncom clearance de creatinina de 29 ml/min; em uso\nde captopril 50 mg a cada 12 horas;\napresentando os seguintes exames: pH = 7,28; pO2 = 100 mmHg; pCO2 = 30 mmHg; HCO3 = 18,0\nmEq/L; BE = - 4; saturação O2 = 99%. Hemoglobina = 7,5 g/dl; hematócrito = 25,0%; saturação de\ntransferrina = 22%; ferritina = 250 (valor de referência de 200 para paciente renal crônico).\n\nCreatinina = 3,5 mg/dl; ureia = 102 mg/dl; potássio = 4,8 mEq/L; sódio = 138 mEq/L. Cálcio total =\n8,9 mg/dl; fósforo = 3,5 mg/dl; Paratormônio (PTH) = 350 (valor de referência de 70-100 pg/ml). Em\nrelação ao exposto acima, assinale a alternativa CORRETA.","options":{"A":"O paciente necessita receber suplementação de ferro inicialmente para correção da anemia, pois\na anemia ferropriva é a principal causa de\nanemia na doença renal crônica.","B":"A acidose metabólica é um fator de progressão para doença renal crônica estágio V, logo, deve\nser corrigida com bicarbonato de sódio via\noral.","C":"Está desenvolvendo uma doença óssea adinâmica e não tem indicação de calcitriol.","D":"Deve-se trocar o captopril por outra classe de anti-hipertensivo, devido ao risco de\nhipercalemia.","E":"A obesidade e o tabagismo não contribuem para a evolução da doença renal crônica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-59016","number":"59016","sourceNumber":"59016","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A determinação da taxa de filtração glomerular e da albuminúria são importantes, pois:","options":{"A":"Permitem prognosticar os pacientes com maior probabilidade de perda da função renal ao longo\ndos anos.","B":"Permitem prognosticar quais pacientes terão mais chances de apresentarem doenças\ncardiovasculares.","C":"Permitem definir e classificar a doença renal crônica.","D":"Todas as alternativas anteriores estão corretas.","E":"Nenhuma das alternativas anteriores está correta."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-43302","number":"43302","sourceNumber":"43302","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 45 anos, sexo masculino, com quadro de dor lombar à direita iniciada há 3\ndias, tipo cólica, intermitente, com irradiação para fossa ilíaca direita e associada a vômitos.\nRelata\ntambém oligúria. História prévia de nefrectomia esquerda devido neoplasia renal. No pronto-socorro\nexames mostraram: creatinina 4,6; hemograma normal e exame de urina com hematúria. Acerca do\ncaso, marque a alternativa CORRETA:","options":{"A":"I. renal pós-renal; Litíase renal; US renal; Fração excretada de sódio \"menor que\" 1.","B":"I. renal pós-renal; Litíase renal; US renal; Fração excretada de sódio \"maior que\" 1.","C":"I. renal pré-renal; Desidratação pelos vômitos.","D":"I. renal instrínseca; Glomerulonefrite difusa aguda.","E":"I. renal pós-renal; Tumor renal; Pesquisa de células neoplásicas na urina."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-23165","number":"23165","sourceNumber":"23165","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente do sexo feminino de 50 anos, 50 kg e com creatinina sérica de 2 mg/dL é\nclassificada em que estágio da doença renal crônica?","options":{"A":"I.","B":"II.","C":"III.","D":"IV.","E":"V."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-23169","number":"23169","sourceNumber":"23169","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São considerados fatores de progressão da Doença Renal Crônica, exceto:","options":{"A":"hipertensão não controlada.","B":"proteinúria de 24h maior que 1g.","C":"dislipidemia.","D":"uso de inibidor da Enzima Conversora da Angiotensiva (ECA).","E":"obesidade."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-23148","number":"23148","sourceNumber":"23148","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 60 anos, 70 kg, diabético há 15 anos, relata nucalgia há 02 meses e procurou\natendimento em Unidade Básica de Saúde. Ao exame físico apresentava: palidez cutânea\nacentuada, edema de membros inferiores, amputação de quarto e quinto pododáctilos à esquerda,\nauscultas cardíaca e pulmonar normais e pressão arterial de 200/100 mmHg. Os exames\nmostravam: hemoglobina de 8 g/L, hematócrito de 24%, creatinina de 2 mg/dl, ureia de 120 mg/dl,\npotássio de 6 mEq/L, glicemia de jejum de 240 mg/dl, fósforo de 6 mg/dl, ferritina de 98 ng/ml,\níndice de saturação de transferrina de 17% e bicarbonato sérico de 16 mgEq/L. A urina de 24 horas\napresenta volume de 2.000 ml e proteinúria de 1,8 g. A ultrassonografia mostra rins de tamanho\nnormal. Este paciente:","options":{"A":"deve ser controlado clinicamente sem diálise; iniciar dieta com restrição de potássio, fósforo e\nproteína; controle da hipertensão e do diabetes; iniciar uso de agentes estimuladores da\neritropoiese e de ferro endovenoso.","B":"deve iniciar tratamento conservador para Doença Renal Crônica e ser submetido à biópsia renal\napós compensação clínica.","C":"apresenta Doença Renal Crônica e deve ser submetido à confecção de fístula arteriovenosa.","D":"apresenta Doença Renal Crônica e deve iniciar terapia renal substitutiva imediatamente devido à\nhipercalemia.","E":"apresenta Insuficiência Renal Aguda e deve iniciar terapia renal substitutiva imediatamente,\ndevido à hipercalemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-9395","number":"9395","sourceNumber":"9395","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Sr J.A.N.S., 68 anos, tem insuficiência cardíaca grau III, insuficiência renal crônica\nem tratamento conservador, e apresenta os\nseguintes exames: Hemácias 879.000/mm³,\nHemoglobina 8,9 g/dL, Hematócrito 32%, VCM 82,4 fl, HCM 23 pg, CHCM 28%, RDW 12,9%,\n\nPlaquetas 149.000/mm³, Leucócitos 4.200/mm³, B 2%, S 59%, E 2%, M 12% e L 25%. Ureia 69,\nCreatinina 2,3. PCR > 5,0 (normal até 0,5). Em relação a esse paciente, está CORRETO:","options":{"A":"A anemia em questão não interfere no prognóstico do Sr J.A.N.S. e deverá ser tratada se\nsintomática.","B":"A eritropoietina deverá ser iniciada assim que o paciente começar a ser dializado.","C":"O Sr J.A.N.S. deverá iniciar o uso de concentrado de hemácias, pois a melhora dos níveis de\nhemoglobina é determinante de prognóstico.","D":"O uso de eritropoietina está indicado, pois, nas anemias de doenças crônicas, a melhora dos\nníveis de hemoglobina tem impacto prognóstico positivo.","E":"O tratamento da anemia deverá ser multidisciplinar, uma vez que a correção da ICC e da IRC\nrestaura os níveis de hemoglobina."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-363939","number":"363939","sourceNumber":"363939","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Nos pacientes com infecção por Doença de Chagas, quando evoluem para a fase\ncrônica, qual a forma de apresentação mais comum?","options":{"A":"Forma cardíaca.","B":"Forma digestiva (esofagopatia ou colopatia).","C":"Forma mista (cardíaca e digestiva).","D":"Forma indeterminada (sem evidência de acometimento cardíaco ou digestivo)."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-355601","number":"355601","sourceNumber":"355601","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar, três anos, é atendido no ambulatório de pediatria geral com queixas de\nfebre e dor nas pernas. A febre tem sido\nintermitente, tendo chegado a 38,6°C nos últimos cinco\ndias e a dor nas pernas o tem acordado à noite. As vacinas estão atualizadas e o paciente não tem\ncomorbidades. Mãe relata que recentemente surgiram algumas manchas arroxeadas nos braços e\npernas, porém, relaciona a trauma associado a atividades. Refere infecção viral prévia há\naproximadamente três semanas, com resolução espontânea. Sinais vitais: Tax. 38,2°C, FC 120\nbatimentos/minuto, FR 24 irpm, PA 100 x 60 mmHg e saturação de oxigênio de 15 100% em ar\nambiente. Adenomegalia cervical inexpressiva. Ausculta cardíaca e pulmonar sem alterações.\n\nAbdome sem hepatoesplenomegalia. Presença de equimoses discretamente dolorosas em áreas\nexpostas e não expostas. Exame neurológico\nsem alterações. Exames laboratoriais: 1.500\nleucócitos/mm3 (5% de eosinófilos, 5% neutrófilos, 85% linfócitos, 5% monócitos); hemoglobina 8,5\ng/dL, hematócrito 24%, reticulócitos 0,4%, plaquetas 75.000/mm³ . O diagnóstico mais provável\npara esse paciente é de:","options":{"A":"anemia aplástica.","B":"leucemia linfocítica aguda","C":"leucemia linfocítica crônica","D":"mononucleose infecciosa","E":"imunossupressão pós-viral"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-334769","number":"334769","sourceNumber":"334769","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 32 anos de idade realizou quimioterapia de consolidação para leucemia\nlinfoblástica aguda (LLA) com altas doses de\nmetotrexato e citarabina há 7 dias. Procurou pronto\natendimento do hospital escola relatando febre aferida de 38,4°C, negava qualquer sinal ou sintoma\ninfeccioso. O hemograma solicitado na urgência revelou 300 neutrófilos/mm³. Neste caso, qual é a\nconduta a ser utilizada?","options":{"A":"colher hemoculturas e exames de bioquímica e orientar o paciente a retornar em 12 horas para\nreavaliação já que está sem foco infeccioso identificável.","B":"colher hemoculturas e exames de bioquímica e iniciar amoxicilina por via oral e reavaliar em o\npaciente em 24 horas.","C":"internar o paciente e após coleta de hemoculturas e exames gerais, e iniciar antibioticoterapia\nparenteral de amplo espectro com droga que tenha\nação antipseudomonas.","D":"internar paciente e após coleta de hemoculturas e iniciar ceftriaxona caso haja evidencia de\nbactéria resistente escalonar antibioticoterapia posteriormente."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-321554","number":"321554","sourceNumber":"321554","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Leia o caso clínico. Paciente submetido a quimioterapia com fludarabina e\nciclofosfamida, seguido de terapia com receptor\ndo antígeno quimérico de células T (CAR-T cell)\npor leucemia linfoide aguda. No sexto dia, após a infusão das células, paciente apresenta\ntemperatura de 38.9ºC, hipotensão, com necessidade de altas doses de drogas vasoativas,\naumento pronunciado de proteína C reativa e procalcitonina normal. O diagnóstico apropriado para\no paciente é de","options":{"A":"choque séptico.","B":"síndrome de liberação de citocinas.","C":"toxicidade a quimioterápicos.","D":"síndrome de neurotoxicidade associada a células efetoras imunes."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-342620","number":"342620","sourceNumber":"342620","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação aos aspectos relacionados à toxoplasmose, assinale a alternativa correta:","options":{"A":"os cistos teciduais contêm bradizoítas, os quais são altamente sensíveis ao tratamento com\nsulfadiazina e pirimetamina","B":"a forma mais comum de contágio é a ingestão dos esporozoítos em carnes mal passadas","C":"o acometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocompetentes","D":"a forma encefálica (neurotoxoplasmose) se dá mais comumente na primoinfecção, sendo raros\nos casos por reativação"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-346434","number":"346434","sourceNumber":"346434","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 47 anos, com câncer de estômago, em tratamento quimioterápico, chega ao\npronto socorro com queixa de febre alta (39,2ºC) e tosse com expectoração clara. Apresenta sinais\nvitais estáveis e a radiografia de tórax é normal. Assinale a alternativa correta quanto à conduta\nimediata a ser tomada:","options":{"A":"Solicitar uma tomografia de tórax em virtude da tosse. Caso venha normal, orientar o paciente e\nprescrever sintomáticos para casa;","B":"Iniciar antibioticoterapia endovenosa empírica independente do hemograma, haja visto que a\npaciente está em tratamento com quimioterapia;","C":"Solicitar hemograma e, se leucócitos abaixo de 1000 cels/mm3, coletar as culturas e iniciar\nantibioticoterapia empírica endovenosa imediatamente;","D":"Após um exame físico minucioso, caso nenhum foco infeccioso seja identificado, prescrever\nsintomáticos e orientar o paciente. Exames\nsubsidiários neste caso não são necessários porque o\npaciente está estável, sendo a clínica soberana."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-342647","number":"342647","sourceNumber":"342647","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual é a causa mais frequente de linfadenomegalia na infância?","options":{"A":"hiperplasia policlonal reacional","B":"tuberculose","C":"linfoma de Hodgkin","D":"doença da arranhadura do gato"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-314105","number":"314105","sourceNumber":"314105","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino de 38 anos procura médico para avaliação de massa em\ncavidade oral em região de palato associado a sintomas B, com febre e perda de peso. Em\ninvestigação, foi observado ser paciente com sorologia positiva para HIV. Após realizar a biópsia da\nlesão, o resultado esperado é linfoma:","options":{"A":"Plasmablástico.","B":"Imunoblástico.","C":"Linfoblástico.","D":"De Burkitt."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-316315","number":"316315","sourceNumber":"316315","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre neutropenia febril, assinale a alternativa ERRADA:","options":{"A":"As principais portas de entrada para infecções nos pacientes neutropênicos são pele, trato\nrespiratório superior e trato gastrointestinal.","B":"A primeira medida após o diagnóstico de neutropenia febril é o início de esquema empírico de\nantibiótico.","C":"A instituição de terapia empírica deve ser realizada com ceftriaxone ou ciprofloxacino.","D":"A presença de mucosite predispõe à reativação de herpes simples e ela se manifesta na forma\nde úlceras na mucosa, como na primoinfecção."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-316316","number":"316316","sourceNumber":"316316","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 82 anos de idade apresenta, em exames de rotina, o seguinte hemograma:\nHb 11,8 g/dl; Ht 34,4%; VCM 82 fl; HCM 33 pg;\nRDW 12 %; global de leucócitos 22.380; bastões\n\n0%; segmentados 24%; eosinófilos 1%; basófilos 0,2%; linfócitos típicos 71,2%; monócitos 3,6%;\nplaquetas 290.000/mm. Qual a principal hipótese diagnóstica?","options":{"A":"Leucemia linfoblástica aguda.","B":"Leucemia linfocítica crônica.","C":"Leucemia mieloide aguda.","D":"Leucemia mieloide crônica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-311912","number":"311912","sourceNumber":"311912","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na investigação de um paciente com neutropenia, é correto dizer que:","options":{"A":"na mielodisplasia, a celularidade da medula óssea estará normal ou aumentada e a morfologia\ndas células normal.","B":"na anemia megaloblástica muitas vezes dispensa a análise da medula óssea quando se observa\nmacrócitos ovais e VCM alto no sangue periférico.","C":"no hiperesplenismo, apesar da morfologia celular normal, a população celular na medula óssea\nestará suprimida por sequestro esplênico.","D":"na leucemia aguda, a medula óssea se encontra hipocelular, com células de morfologia anormal\n(leucoblastos e mieloblastos)."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-316330","number":"316330","sourceNumber":"316330","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A doença de Chagas é uma das principais infecções parasitárias do mundo. Ocorre\npela transmissão do protozoário Trypanosoma cruzi por intermédio do inseto do gênero\nTriatominae. Dentre as formas da doença, temos a cardíaca, assim, qual a alteração de\neletrocardiografia que, FREQUENTEMENTE, é observada nos pacientes?","options":{"A":"Sobrecarga ventricular esquerda associada a bloqueio de ramo esquerdo.","B":"Bloqueio de ramo esquerdo associado a bloqueio divisional posteroinferior.","C":"Sobrecarga ventricular direita associada a padrão S1Q3T3.","D":"Bloqueio de ramo direito associado a bloqueio divisional anterossuperior."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-300937","number":"300937","sourceNumber":"300937","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa CORRETA levando-se em consideração o diagnóstico de\nneutropenia febril:","options":{"A":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento.","B":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","C":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","D":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-300953","number":"300953","sourceNumber":"300953","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa CORRETA que corresponde ao sintoma de apresentação mais\nfrequente da doença do enxerto X hospedeiro:","options":{"A":"Icterícia.","B":"Hematoquezia.","C":"Dor abdominal.","D":"Erupção cutânea maculopapular."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-308297","number":"308297","sourceNumber":"308297","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação às doenças neoplásicas na infância, qual a mais prevalente?","options":{"A":"Leucemia.","B":"Tumor de Wilms.","C":"Linfoma.","D":"Neuroblastoma."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-311979","number":"311979","sourceNumber":"311979","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"\"O Instituto Nacional do Câncer (INCA) estima a ocorrência anual de aproximadamente\n420 mil casos novos de câncer para o Brasil\nno biênio 2016-2017 (excluindo-se os tumores de pele\nnão melanoma). O câncer infanto-juvenil representa de 1 a 3% dos casos, estimando-se, assim, a\nocorrência de 12.600 novos casos de câncer na faixa etária de 0 a 19 anos para o ano de 2017.\"\nDisponível em: https://www.inca.gov.br/estimativa/introdução. Acesso em:13 de jan.2022. Embora o\ncâncer na criança e no adolescente seja raro, representa a principal causa de óbito por doença\nnesta faixa etária. Quais sinais ou sintomas abaixo estão mais relacionados a sinais de alerta para\ncâncer?","options":{"A":"Linfonodo retroauricular 1cm de diâmetro, indolor, sem febre associada, sem vermelhidão.","B":"Dor em membros inferiores difusa, não capacitante, uma vez por semana, vespertina, com\nhemograma normal.","C":"Dor abdominal periumbilical, duas vezes por semana, pós-alimentar, sem massas palpáveis.","D":"Cefaleia vespertina três vezes ao mês, sem vômitos, leve intensidade, sem progressão."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-277404","number":"277404","sourceNumber":"277404","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa que não apresenta um aspecto prognóstico relevante nas\nleucemias linfocíticas agudas (LLAs):","options":{"A":"idade avançada","B":"número de cromossomos no cariótipo","C":"febre","D":"leucometria inicial"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-277410","number":"277410","sourceNumber":"277410","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação aos aspectos relacionados à toxoplasmose, assinale a alternativa correta:","options":{"A":"os cistos teciduais contêm bradizoítas, os quais são altamente sensíveis ao tratamento com\nsulfadiazina e pirimetamina","B":"a forma mais comum de contágio é a ingestão dos esporozoítas em carnes mal passadas","C":"o comprometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocomprometidos","D":"a forma encefálica (neurotoxoplasmose) se dá mais comumente na primoinfecção, sendo raros\nos casos por reativação."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-281272","number":"281272","sourceNumber":"281272","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São causas de síndrome hemofagocítica secundária (adquirida) todas as abaixo,\nexceto:","options":{"A":"Infecções virais.","B":"Doenças autoimunes.","C":"Neoplasias.","D":"Intoxicações."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-281985","number":"281985","sourceNumber":"281985","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 51 anos, mulher, com diagnóstico de câncer de mama, encontra-se em\nquimioterapia adjuvante. Procurou o pronto-socorro 10 dias após sua quimioterapia, relatando febre\nde 39ºC há 3 dias associada à tosse seca. Nega outras queixas associadas. Nega tabagismo e\nnega etilismo. Ao exame encontrava-se em bom estado geral; descorada +/4+; PA 120 x 80 mmHg;\nlúcida e orientada em tempo e espaço; hidratada; febril ao toque e eupneica em ar ambiente. Rx de\ntórax PA normal. Exame de urina 1 normal. Hemograma com Hb 10 g/dl; leucócitos 1.000 / µL\n(neutrófilos 400/ µL) e plaquetas de 100.000/mm3. Qual alternativa melhor descreve o caso acima\nde neutropenia febril e qual a melhor conduta?","options":{"A":"Escala MASCC ? 21; considerar tratamento com antibiótico oral em casa com Ciprofloxacino e\nClindamicina + Clavulanato.","B":"Escala MASCC < 21 e tratamento com antibiótico endovenoso em regime de internação com\nPiperacilina e Tazobactam.","C":"Escala MASCC ? 21; considerar tratamento em regime de internação com Cefepime.","D":"Escala MASCC ? 21; considerar tratamento com antibiótico oral em casa com Ciprofloxacino e\nAmoxicilina + Clavulanato."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-257727","number":"257727","sourceNumber":"257727","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 43 anos se apresenta ao pronto-socorro com história de desconforto\nabdominal progressivo e ganho de peso há três\nsemanas. Ela relata não possuir doenças\npregressas e não faz uso de medicamentos. No exame físico, nota-se uma face pletórica. O\nabdômen está tenso, sensível e moderadamente distendido. Os achados laboratoriais demonstram\nhemoglobina de 18,7 g/dL, contagem de leucócitos de 9000/µL, contagem de plaquetas de\n401.000/ µL, nível de alanina aminotransferase (ALT) de 84 U/L, aspartato aminotransferase (AST)\nde 107 U/L e nível de bilirrubina total de 0,9 mg/dL. O teste sérico de gravidez é negativo. A\nultrassonografia abdominal com doppler demonstra trombose da veia hepática. Qual dos seguintes\ntestes de diagnóstico tem mais probabilidade de estabelecer a causa da apresentação clínica da\npaciente?","options":{"A":"Pesquisa da mutação JAK2V617F.","B":"Pesquisa de trombofilias hereditárias.","C":"Tomografia computadorizada (TC) helicoidal do abdômen.","D":"Citometria de fluxo para expressão de CD55 e CD59."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-258177","number":"258177","sourceNumber":"258177","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Blinatumomab é um anticorpo monoclonal biespecífico, utilizado no tratamento de\nleucemias linfóides agudas como tratamento de segunda linha. O anticorpo de liga aos sítios de\nligação:","options":{"A":"CD20 e CD5.","B":"CD19 e CD3.","C":"CD19 e CD5.","D":"CD20 e CD3."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274469","number":"274469","sourceNumber":"274469","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 23 anos, sexo feminino, vem ao pronto atendimento com história de dor em\ncotovelo direito há uma semana, acompanhado de um episódio de febre. Nega antecedentes\npatológicos ou uso de medicações ou substancias ilícitas. Refere gostar muito de animais e que,\ninclusive, participa de uma ONG que promove ações de cuidado com animais abandonados. Possui\nhábitos saudáveis de vida. Ao exame físico você percebe nodulações móveis e com discreta\nflogose dolorosa em cotovelo direito sem evidência de artrite. De acordo com os dados iniciais da\nsíndrome descrita, estamos diante de um quadro infeccioso mais provavelmente causado por um\nagente:","options":{"A":"Viral DNA.","B":"Viral RNA.","C":"Bacteriano gram positivo.","D":"Bacteriano gram negativo."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274769","number":"274769","sourceNumber":"274769","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente sexo masculino, 48 anos, dá entrada na unidade hospitalar, conduzido por\nfamiliares, com história de astenia há 5 dias. Ao avaliar paciente no pronto atendimento, o mesmo\nrefere que apresenta febre vespertina há aproximadamente 25 dias, de 38,3°C. Refere não ter\noutros sintomas associados, exceto uma leve odinofagia. Refere ainda que, durante os momentos\nfebris, sente muita dor no corpo, mas fora das crises se sente bem. Paciente não apresenta dados\nrelevantes de antecedentes patológicos. Ao examiná-lo, você percebe um gânglio cervical à direita,\naumentado, levemente doloroso e pouco móvel. Restante do exame físico sem alterações. Sobre o\nraciocínio clínico diante do caso, é imperativo aplicar as evidências diante dos dados descritos. A\nconstrução de hipóteses clínicas segue algumas técnicas sempre com objetivo de buscar a maior\nprobabilidade pré-teste possível da verdade diagnóstica. Diante da apresentação clínica do caso\nanterior e seu contexto descrito, a melhor técnica para construção de hipóteses diagnósticas é:","options":{"A":"construção hipotético dedutiva.","B":"reconhecimento de padrões.","C":"hipótese probabilística.","D":"abordagem sindrômica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274470","number":"274470","sourceNumber":"274470","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 23 anos, sexo feminino, vem ao pronto atendimento com história de dor em\ncotovelo direito há uma semana, acompanhado de um episódio de febre. Nega antecedentes\npatológicos ou uso de medicações ou substancias ilícitas. Refere gostar muito de animais e que,\ninclusive, participa de uma ONG que promove ações de cuidado com animais abandonados. Possui\nhábitos saudáveis de vida. Ao exame físico você percebe nodulações móveis e com discreta\nflogose dolorosa em cotovelo direito sem evidência de artrite. O Agente infeccioso mais provável\npara o contexto descrito seria:","options":{"A":"Adenovírus.","B":"Coronavírus.","C":"B. Henselae.","D":"B. Quintana."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274770","number":"274770","sourceNumber":"274770","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente sexo masculino, 48 anos, dá entrada na unidade hospitalar, conduzido por\nfamiliares, com história de astenia há 5 dias. Ao avaliar paciente no pronto atendimento, o mesmo\nrefere que apresenta febre vespertina há aproximadamente 25 dias, de 38,3°C. Refere não ter\noutros sintomas associados, exceto uma leve odinofagia. Refere ainda que, durante os momentos\nfebris, sente muita dor no corpo, mas fora das crises se sente bem. Paciente não apresenta dados\nrelevantes de antecedentes patológicos. Ao examiná-lo, você percebe um gânglio cervical à direita,\naumentado, levemente doloroso e pouco móvel. Restante do exame físico sem alterações.\n\nAnalisando o contexto clínico descrito, suas respectivas informações e forma de apresentação, a\nhipótese clínica pode melhor ser trabalhada na perspectiva de uma manifestação:","options":{"A":"consumptiva em potencial.","B":"viral.","C":"febril de origem indeterminada.","D":"miastênica."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-281279","number":"281279","sourceNumber":"281279","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa incorreta em relação às opções terapêuticas para síndrome\nhemofagocítica secundária.","options":{"A":"Protocolo HLH-2004 (8 semanas de quimioterapia).","B":"Imunoglobulina intravenosa.","C":"Diálise peritoneal.","D":"Corticoide."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274472","number":"274472","sourceNumber":"274472","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 23 anos, sexo feminino, vem ao pronto atendimento com história de dor em\ncotovelo direito há uma semana, acompanhado de um episódio de febre. Nega antecedentes\npatológicos ou uso de medicações ou substancias ilícitas. Refere gostar muito de animais e que,\ninclusive, participa de uma ONG que promove ações de cuidado com animais abandonados. Possui\nhábitos saudáveis de vida. Ao exame físico você percebe nodulações móveis e com discreta\nflogose dolorosa em cotovelo direito sem evidência de artrite. Referente ao tratamento e\nconsiderando o contexto clinico da história, a melhor escolha seria:","options":{"A":"Iniciar Bactrim via oral e acompanhar.","B":"Iniciar antiviral oral e acompanhar.","C":"Não iniciar terapêutica específica e acompanhar.","D":"Iniciar esquema RIP via oral e acompanhar, monitorando transaminases."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274816","number":"274816","sourceNumber":"274816","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Linfadenopatia é um achado frequente na atenção primária à saúde, podendo\nrepresentar desde um aumento reacional por\nprocesso infeccioso, até evidência de neoplasia. Com\nrelação às linfadenopatias, marque a alternativa correta.","options":{"A":"Linfonodos normais são papáveis, têm em geral 20 mm de diâmetro, consistência elástica, são\nindolores à palpação e móveis.","B":"A ocorrência de linfadenopatia supraclavicular deve alertar para a possibilidade de patologias\ntorácicas ou abdominais graves.","C":"Existindo a indicação de biopsia do linfonodo, a Punção Aspirativa com Agulha Fina (PAAF) é o\nprocedimento de escolha.","D":"Pacientes com linfadenopatia generalizada devem ser acompanhados de forma expectante por\n3 a 4 semanas, antes de se iniciar\ninvestigação com exames, já que dentro deste período de\nespera a maioria das linfadenopatias se resolvem espontaneamente."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-254210","number":"254210","sourceNumber":"254210","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 31 anos, admitido no PA por quadro de febre, astenia e sangramento\n(gengivorragia). Exames laboratoriais revelaram\npancitopenia, alteração de TAP e fibrinogênio.\nEquipe assistente colheu mielograma que revelou presença de 55% de blastos na medula, às\ncustas de promielócitos. Considerando a hipótese diagnóstica provável após os exames, qual a\nopção terapêutica indicada que mudou o prognóstico dos pacientes diagnosticados com essa\ndoença?","options":{"A":"Gentuzumabe.","B":"Rituximabe.","C":"Ácido transretinoico.","D":"Adriamicina."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-234331","number":"234331","sourceNumber":"234331","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 65 anos, previamente hígido, refere cefaleias leves há seis meses, que\nvêm se intensificando. Em avaliação com\nclínico geral, notado baço percutível, mas não palpável.\nHemograma mostra hemoglobina de 16,8 g/dl, Ht: 50%, GB: 12.900/ul, com bastões: 06%,\nsegmentados: 68%, eosinófilos: 03%, basófilos: 00%, linfócitos: 20%, monócitos: 03%, plasmócitos:\n\n01%, plaquetas: 500.000/ul. Apresenta DHL: 250 (nl pelo método: 150 - 270), eritropoetina: 1,2\nUI/L. Biópsia de medula óssea mostra\nhipercelularidade evidente, com megacariócitos formando\nagregados, com variação de tamanho e fibras reticulínicas esparsas. Pesquisada mutação JAK2\nexon14: negativa, CALR: negativa, MPL: negativa. Pesquisa de mutação JAK2 exon12: positiva.\nSegundo os critérios diagnósticos das neoplasias hematológicas da Organização Mundial da\nSaúde, de 2016, o diagnóstico é:","options":{"A":"Mielofibrose primária pré-fibrótica.","B":"Policitemia vera.","C":"Trombocitemia essencial.","D":"Mielofibrose primária fibrótica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-234332","number":"234332","sourceNumber":"234332","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 40 anos, com leucemia mieloide crônica, sem outras comorbidades, com\nausência de resposta molecular maior aos 24 meses, sendo considerada falha ao tratamento com\nimatinibe. Trocado seu tratamento para nilotinibe, 400 mg, duas vezes ao dia, e, após oito meses,\napresenta resposta citogenética completa e resposta molecular completa. Em avaliação periódica\napós três anos de tratamento com nilotinibe, relata dor e frialdade em pé direito. Após avaliação\nclínica e de imagem, detectada doença vascular oclusiva. Nesse caso, qual é a conduta?","options":{"A":"Redução na dose do Nilotinibe para 300 mg, duas vezes ao dia.","B":"Suspensão definitiva do Nilotinibe.","C":"Anticoagulação oral.","D":"Observação e reavaliação em um mês."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-234403","number":"234403","sourceNumber":"234403","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O acometimento primário do sistema nervoso central por linfoma é, mais\nprovavelmente, do tipo:","options":{"A":"Células B.","B":"Hodgkin.","C":"Kaposi.","D":"Células T."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-214916","number":"214916","sourceNumber":"214916","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação aos aspectos relacionados à toxoplasmose, assinale a alternativa correta:","options":{"A":"os cistos teciduais contêm bradizoítas, os quais são altamente sensíveis ao tratamento com\nsulfadiazina e pirimetamina","B":"a forma mais comum de contágio é a ingestão dos esporozoítas em carnes mal passadas","C":"comprometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocomprometidos","D":"a forma encefálica (neurotoxoplasmose) se dá mais comumente na primoinfecção, sendo raros\nos casos por reativação."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-202721","number":"202721","sourceNumber":"202721","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 68 anos foi ao cirugião geral para avaliação de\nhérnia inguinal. O médico fez a avaliação e solicitou exames pré-operatórios que demonstraram um\nhemograma com hemoglobina de 13,9 g/dl, plaquetas de 208.000, leucócitos totais de 32800 com\n88% de linfócitos. O hematologista fez um esfregaço de sangue periférico que demonstrava\npredomínio de linfócitos pequenos e alguns raros prolinfócitos, além de manchas de Gumprecht. O\ndiagnóstico do paciente é:","options":{"A":"leucemia linfoide aguda.","B":"mononucleose aguda.","C":"reação leucemoide.","D":"leucemia linfoide crônica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-201737","number":"201737","sourceNumber":"201737","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O linfoma de zona marginal esplênico está associado à infecção com o:","options":{"A":"Helicobacter pylori.","B":"Chlamydophila psittaci.","C":"Vírus da hepatite C.","D":"Campylobacter jejuni."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-214190","number":"214190","sourceNumber":"214190","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem com 35 anos informa que tem observado o aparecimento de vários linfonodos\nindolores, aumentado de tamanho, na região cervical nos últimos 30 dias, febril (>38 °C), suores\nnoturnos, perda de mais de 10% do peso sem causa aparente, fadiga e prurido. Teve diagnóstico\nde Linfoma de Hodgkin esses sintomas são classificados como","options":{"A":"Sintomas A.","B":"Sintomas B.","C":"Sintomas C.","D":"Sintomas D."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-214109","number":"214109","sourceNumber":"214109","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A toxoplasmose é uma doença causada por um protozoário, o Toxoplasmose Gondii.\nEstão a ela relacionados as seguintes doenças, com exeção:","options":{"A":"Pterígio.","B":"Taxoplasmose ocular adquirida e congênita.","C":"Coriorretinite.","D":"Uveíte anterior."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-187531","number":"187531","sourceNumber":"187531","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com a identificação de gânglio indolor, endurecido e aderido a plano profundo na\nregião supraclavicular esquerda, tem-se o diagnóstico mais provável","options":{"A":"gânglio reacional inespecífico.","B":"lúpus eritematoso sistêmico.","C":"neoplasia.","D":"tuberculose."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-173510","number":"173510","sourceNumber":"173510","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O megacólon chagásico tem como complicação mais frequente","options":{"A":"o fecaloma.","B":"o câncer colorretal.","C":"a colite isquêmica.","D":"o volvo de sigmoide."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-173559","number":"173559","sourceNumber":"173559","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com leucemia mieloide crônica em fase crônica, em uso imatinibe, 400 mg, há\n18 meses. Seu exame de RT-PCR para BCR-ABL\nmostra, na escala internacional, uma\ndeterminação quantitativa de 0,1%. Segundo os critérios do Consórcio Internacional LeukemiaNet,\nsua resposta ao tratamento é:","options":{"A":"Resposta molecular completa.","B":"Resposta molecular maior.","C":"Resposta molecular menor.","D":"Resposta molecular incompleta."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-174106","number":"174106","sourceNumber":"174106","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino, de 32 anos, refere que há três meses iniciou quadro de\nastenia e emagrecimento. Há um mês, febre noturna, icterícia e aumento do volume da região axilar\nesquerda. Ao exame físico, os achados positivos são: ictérico++, hipocorado++,\nhepatoesplenomegalia, massa na região axilar direita de cerca de 6 cm, associada a linfonodos\ninguinais bilaterais. Nega histórico pregresso de doença pessoal ou drogadição. Achados\nlaboratoriais iniciais incluem: Hb = 8,7 g/dl; leucócitos = 3790/mm³, plaquetas = 48.000/mm3; biT =\n\n9.5mg/dl; biD = 8,9 mg/dl; TGO = 192 UI/I; TGP = 1110 UI/I; FA = 2015 UI/I; GGT = 1480 UI/I;\n\nalbumina = 2.2 g/dl; LDH = 936 UI/I. Teste rápido para HIV: positivo. O diagnóstico mais provável\npara o paciente é:","options":{"A":"linfoma de Hodgkin.","B":"doença de Erdheim Chester.","C":"linfoma não Hodgkin.","D":"doença de Kikuchi Fujimoto."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-182449","number":"182449","sourceNumber":"182449","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação aos aspectos relacionados à toxoplasmose, assinale a alternativa correta:","options":{"A":"os cistos teciduais contêm bradizoítas, os quais são altamente sensíveis ao tratamento com\nsulfadiazina e pirimetamina","B":"a forma mais comum de contágio é a ingestão dos esporozoítos em carnes mal passadas","C":"o acometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocompetentes","D":"a forma encefálica (neurotoxoplasmose) se dá mais comumente na primoinfecção, sendo raros\nos casos por reativação"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-187586","number":"187586","sourceNumber":"187586","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Cirurgião geral é chamado para avaliar criança internada de urgência duas semanas\napós a última sessão de quimioterapia,\napresentando febre, dor abdominal intensa, diarreia e\nhematoquezia. Ao exame, hipocorada, taquicárdia e achado de dor à palpação em fossa ilíaca\ndireita com descompressão brusca duvidosa. A conduta e diagnóstico mais prováveis são:","options":{"A":"Rx de abdome agudo, hemograma, EAS e cirurgia por provável apendicite.","B":"tomografia de abdome, hemograma, EAS e cirurgia por provável apendicite.","C":"tomografia, hemograma, EAS e antibioticoterapia e repouso intestinal por provável tiflite.","D":"tomografia de abdome, hemograma, EAS e cirurgia por provável tiflite."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156996","number":"156996","sourceNumber":"156996","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual das alternativas NÃO se relaciona com pior prognóstico na cardiopatia chagásica?","options":{"A":"Alterações eletrocardiográficas.","B":"Tromboembolismo.","C":"Reativação da infecção.","D":"Sinal de Romaña."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-157059","number":"157059","sourceNumber":"157059","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a infecção por toxoplasmose, podemos dizer que:","options":{"A":"O acometimento ocular é caracterizado por coriorretinite e pode acometer pacientes\nimunocompetentes.","B":"Os cistos teciduais contêm bradizoítos, os quais são altamente sensíveis ao tratamento com\nsulfadiazina.","C":"A forma mais comuns de transmissão é a ingestão de esporozoítas em carnes mal passadas.","D":"Se caracteriza por febre obscura associada a linfadenite cervical dolorosa, confluente e com\ntendência a fistulização."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-150190","number":"150190","sourceNumber":"150190","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Serviço de Coloproctologia da Faculdade de Medicina da Universidade Federal de\nGoiás emprega desde 1966, a cirurgia de Duhamel-Haddad no tratamento de pacientes portardores\nde megacolo chagásico. O segmento intestinal obrigatoriamente ressecado nesta técnica é o:","options":{"A":"Reto médio.","B":"Colo sigmoide.","C":"Colo descendente.","D":"Colo transverso."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-160528","number":"160528","sourceNumber":"160528","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 36 anos é atendido com quadro de anemia há 6 meses, evoluindo, nos\núltimos dias, com emagrecimento, febre,\nepistaxe e hemorragia gengival. O hemograma apresenta\nleucocitose importante e o mielograma revela a presença de células imaturas granulocíticas. O\ndiagnóstico mais provável é:","options":{"A":"Leucemia Linfoide Aguda.","B":"Linfoma Hodgkin.","C":"Linfoma não Hodgkin.","D":"Leucemia Mieloide Aguda."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-150229","number":"150229","sourceNumber":"150229","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual é a intercorrência mais frequente nos pacientes com leucemia promielocítica\naguda?","options":{"A":"Coagulação intravascular disseminada.","B":"Síndrome ATRA.","C":"Infiltração do sistema nervoso central.","D":"Neutropenia febril."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156513","number":"156513","sourceNumber":"156513","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na doença de Willebrand o Fator X da coagulação esta deficiente","B":"A Policitema Vera é também conhecida como síndrome mieloproliferativa ou Doença de\nVasquez.","C":"A Púrpura de Henoch-Schonlein é também conhecida como síndrome do cromossomo 13.","D":"O tratamento do hiperesplenismo é sempre cirúrgico"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156534","number":"156534","sourceNumber":"156534","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São agente bacterianos predominantes nos pacientes pediátricos Oncológicos:","options":{"A":"Pneumocystis formely, Cryptosporidium;","B":"Bordetela pertusis, Ureaplasma urealítico","C":"Micoplasma, Epstein-Barr","D":"Staphylococcus species, Enterobactérias"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-160536","number":"160536","sourceNumber":"160536","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Augusto, 7 anos, portador de síndrome de Down, é levado à Unidade de Pronto\nAtendimento (UPA) com quadro de astenia,\nmialgia e febre intermitente de 38ºC há três dias. No\nexame físico apresenta o seguinte quadro: hipocorado ++/4+, febril (38,2ºC), acianótico, ausculta\nrespiratória com MV fisiológico, sem RA, FR: 26 irpm, ACV: BNF, 2T, presença de sopro sistólico\n\n++/4+, FC: 110 bpm. No abdome, presença de fígado a 3 cm RCD, ponta de baço palpável RCE.\nEncontrados também gânglios inguinais, auxiliares e cervicais palpáveis bilateralmente. Foi\nsolicitado hemograma de urgência com o seguinte resultado: Ht 28/ Hb 7,5/ 80.000 leucócitos/ 4000\nneutrófilos/ 82.000 linfócitos, sendo 80% de blastos, 100.000 plaquetas. Qual exame complementar\ndeve ser solicitado no próximo passo, para elucidação do diagnóstico neste caso?","options":{"A":"Ultrassonografia abdominal.","B":"Mielograma.","C":"Provas inflamatórias.","D":"Sorologias."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-129885","number":"129885","sourceNumber":"129885","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, de 18 anos, do sexo masculino, é admitido no pronto-socorro com queixa de\nfebre aferida há duas horas de 39°C. Nega dispneia, disúria, diarreia, otalgia ou qualquer outro\nsintoma infeccioso. Ao exame físico, apresenta-se levemente taquicárdico, sem hipotensão arterial,\ntaquipneia ou qualquer outra alteração na avaliação do aparelho cardiovascular e respiratório ou no\nexame abdominal. Revela ao médico estar em tratamento quimioterápico, fase de indução, para\nleucemia mieloide aguda diagnosticada há 20 dias. O hemograma solicitado na urgência revela:\nhemoglobina = 7,5 mg/dl; leucócitos totais = 500/mm³; neutrófilos = 100/mm³; linfócitos = 400/mm³;\nplaquetas = 25.000/mm³. Qual conduta deve ser estabelecida?","options":{"A":"Liberar o paciente e solicitar seu retorno em caso de aparecimento de qualquer sintoma\ninfeccioso.","B":"Iniciar antibiótico oral (levofloxacino ou amoxicilina + clavulanato + ciprofloxacino), colher\nculturas, solicitar radiografia de tórax e reavaliar em 48 horas.","C":"Encaminhar para avaliação ambulatorial do especialista.","D":"Iniciar imediatamente antibiótico endovenoso (cefepima, piperacilina + tazobactam ou\nmeropenem), colher hemoculturas e realizar radiografia de tórax."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-127715","number":"127715","sourceNumber":"127715","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"De acordo com as diretrizes KDIGO 2012 para doença renal crônica e anemia na DRC:","options":{"A":"O estágio de DRC G3a/A2 é aquele que apresenta depuração de creatinina entre 30-44 ml/min e\nalbuminúria > 300 mg/g.","B":"A correção da acidose metabólica com bicarbonato de sódio oral deve ser iniciada quando o\nbicarbonato sérico <16 mmol/L.","C":"A avaliação inicial de anemia na DRC inclui a realização de hemograma, contagem de\nreticulócitos, ferritina, saturação de\ntransferrina, dosagem sérica de vitamina B12 e ácido fólico.","D":"A transfusão de concentrado de hemácias na DRC está indicada na presença de hemoglobina <\n8,0 g/dL, independente da presença de sintomas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-129915","number":"129915","sourceNumber":"129915","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente com doença renal policística autossômica dominante apresentou ao seu\nnefrologista um exame de clearance de creatinina de 28 ml/min. Esse paciente é classificado como\nrenal crônico no estágio:","options":{"A":"2.","B":"3b.","C":"4.","D":"5."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-110236","number":"110236","sourceNumber":"110236","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As leucemias na infância e na adolescência são classificadas em LLA (Leucemia\nLinfoide Aguda), LMA (Leucemia Mieloide Aguda) e\nLMC (Leucemia Mieloide Crônica). Sobre este\ntipo de câncer, na infância, tem-se que:","options":{"A":"O diagnóstico diferencial entre as formas LLA e LMA pode ser feito pela análise do hemograma,\nque revela leucocitose na primeira e leucopenia\nna segunda.","B":"Dor óssea, linfonodomegalia e hepatoesplenomegalia são muito comuns na LLA, a forma mais\ncomum na infância.","C":"A forma mais prevalente na infância é a LMA, que tem um pico de incidência na fase etária\npré-escolar e escolar.","D":"Paciente com aumento plaquetário e ausência de esplenomegalia são características da LMC, a\nforma mais prevalente na infância."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-106725","number":"106725","sourceNumber":"106725","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 67 anos de idade, portador de rins policísticos, apresenta taxa de\nfiltração glomerular de 21 ml/mim/1.73 m². Em qual estágio da Doença Renal Crônica (DRC) e qual\no grau de DRC ele se encontra respectivamente?","options":{"A":"Estágio 3 e insuficiência renal moderada ou laboratorial.","B":"Estágio 3 e insuficiência renal grave ou clínica.","C":"Estágio 4 e insuficiência renal grave ou clínica.","D":"Estágio 4 e insuficiência renal moderada ou laboratorial."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-101220","number":"101220","sourceNumber":"101220","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com o objetivo de controlar a hiperfosfatemia nos pacientes pediátricos em\nhemodiálise, a intervenção correta na terapia\nrenal substitutiva com nível de evidência científica é:","options":{"A":"Diminuir a temperatura do sangue e/ou o alvo de bicarbonato sérico.","B":"Aumentar a frequência das sessões e/ou prolongar o tempo de diálise.","C":"Fazer bolus de glicose e/ou retirar mais líquido no início da sessão.","D":"Utilizar soluções com baixa concentração de cálcio e/ou diminuir o fluxo de sangue."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-79544","number":"79544","sourceNumber":"79544","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em que situação clínica um aumento de creatinina sérica seria explicado apenas por\numa redução na taxa de filtração glomerular?","options":{"A":"Cimetidina a um paciente com úlcera péptica","B":"Diabetes com bexiga neurogênica","C":"Convulsões de paciente com estado epiléptico","D":"Contração severa de volume extracelular em paciente com diarreia","E":"Trimetoprima a um paciente com infecção urinária"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-83677","number":"83677","sourceNumber":"83677","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São procedimentos necessários para o estadiamento de linfoma de Hodgkin:","options":{"A":"Biópsia de medula óssea e imunofenotipagem de sangue periférico.","B":"Biópsia de gânglio linfático e cariótipo banda G.","C":"Hemograma e mielograma.","D":"Anamnese e exame físico detalhados.","E":"Tomografia computadorizada (tórax e abdome total) e eletroforese de imunoglobulinas séricas."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-84420","number":"84420","sourceNumber":"84420","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Deve-se desconfiar de insuficiência renal, quando há suspeita, em distúrbios\nhidroeletrolíticos, de:","options":{"A":"Hipermagnesemia, hipernatremia e hiperpotassemia.","B":"Hiperpotassemia, hipomagnesemia e hipercalemia.","C":"Hipernatremia, hipocalcemia e hiperpotassemia.","D":"Hiperpotassemia, hipermagnesemia e hiponatremia.","E":"Hiperfosfatemia, hipopotassemia e hipocloridria."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-83666","number":"83666","sourceNumber":"83666","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino, 60 anos, em programa de hemodiálise por nefropatia\nhipertensiva, iniciou quadro de dores ósseas,\nmialgia, fraqueza muscular e prurido difuso. Em\ninvestigação radiológica, foram detectadas deformidades ósseas e calcificações de partes moles.\nQual alternativa mostra resultados laboratoriais de dosagens séricas mais compatíveis com o\nquadro acima?","options":{"A":"Cálcio elevado, fósforo diminuído e calcitriol elevado.","B":"Cálcio diminuído, fósforo elevado e calcitriol diminuído.","C":"Cálcio diminuído, fósforo elevado e calcitriol elevado.","D":"Cálcio elevado, fósforo elevado e calcitriol elevado.","E":"Cálcio elevado, fósforo diminuído e calcitriol diminuído."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78072","number":"78072","sourceNumber":"78072","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual dos critérios abaixo é um critério menor para o diagnóstico (OMS 2008) de\npolicitemia vera?","options":{"A":"Vitamina B12 baixa.","B":"Eritropoetina baixa.","C":"Reação leucoeritroblástica.","D":"Cromossomo Philadelphia positivo."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78061","number":"78061","sourceNumber":"78061","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 70 anos, portador de hipertensão arterial sistêmica há 20 anos, com taxa\nde filtração glomerular de 25 ml/min/1,73 m² de\nsuperfície corpórea e albuminúria de 800 mg/g de\ncreatinina. Qual a sua classificação quanto à doença renal crônica?","options":{"A":"G3a A2","B":"G3b A3","C":"G4 A3","D":"G4 A2"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78080","number":"78080","sourceNumber":"78080","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino, de 68 anos, portador de diabetes mellitus tipo 2 e\nhipertensão arterial, em uso de losartana e repaglinida, apresenta creatinina sérica 1,7 mg/dl\n(filtração glomerular estimada de 42 ml/min). Será submetido a cateterismo cardíaco para\ninvestigação de doença coronariana. Quanto às recomendações de profilaxia para lesão renal\naguda, sugeridas pela KDIGO Clinical Practice Guideline for Acute Kidney Injury, 2012, deve-se\nutilizar solução salina isotônica endovenosa associada a:","options":{"A":"N-acetilcisteína via oral.","B":"Contraste iodado com alta osmolaridade.","C":"Teofilina endovenosa.","D":"Suspensão da repaglinida."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78091","number":"78091","sourceNumber":"78091","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A lesão renal aguda vem aumentando a prevalência na infância, principalmente devido\nà evolução da medicina, expondo as crianças a\ntratamentos e drogas que, se por um lado salvam\nvidas, por outro, podem lesar os rins. Assim, é importante estimar a depuração de creatinina nos\npacientes pediátricos internados em unidades de terapia intensiva. Para isso, ultiliza-se a fórmula\ndesenvolvida por Schwartz: Quando a creatinina é dosada pela metodologia \"Jaffé\" (mais comum\nem nosso meio), o valor da constante \"K\" a ser ultilizado para pacientes após um ano de idade é:\n(VER IMAGEM)","options":{"A":"0,55","B":"0,45","C":"0,413","D":"0,33"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-18/78091.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-62744","number":"62744","sourceNumber":"62744","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em pacientes portadores de doença renal crônica nos estágios 3 e 4, o tratamento da\nanemia com agentes estimuladores da eritropoiese (eritropoetina) deve ser iniciado após a\nexclusão de causas extrarrenais de anemia e quando os valores de hemoglobina forem menores\nque:","options":{"A":"9 g/dl.","B":"10 g/dl.","C":"11 g/dl.","D":"12 g/dl."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-63220","number":"63220","sourceNumber":"63220","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Manuela encontra-se no 5º pós-operatório de transplante renal com aumento dos níveis\nde creatinina e não apresentando débito\nurinário. Estudo ultrassonográfico evidencia pequena\nquantidade de líquido localizada anteriormente ao rim transplantado. O doppler colorido obtido na\nporção média do rim transplantado mostra fluxo arterial com diástole reversa. Não há evidência de\nfluxo na veia renal. A principal hipótese diagnóstica é:","options":{"A":"Estenose da artéria renal.","B":"Hematoma subscapular.","C":"Necrose tubilar aguda severa.","D":"Rejeição aguda do transplante.","E":"Trombose de veia renal."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-62699","number":"62699","sourceNumber":"62699","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 55 anos, 70 kg, apresentou diarreia aquosa 10 vezes ao dia, durante dois\ndias. Chegou para a consulta com mucosas\nsecas, pele com turgor diminuído, sedento, sem\ndiurese há 24 horas. Pressão arterial: 100/60 mmHg , deitado, e 90/50 mmHg, sentado. Os exames\nmostraram no sangue: ureia = 120 mg/dl, creatinina = 1,5 mg/dl, sódio = 130 mEq/l, potássio = 5,0\nmEq/l, Sódio urinário = 10 mEq/l. Qual é o diagnóstico, nesse caso?","options":{"A":"Lesão renal aguda pré-renal.","B":"Lesão renal aguda pós-renal.","C":"Nefrite intersticial aguda.","D":"Necrose tubular aguda."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-61807","number":"61807","sourceNumber":"61807","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a anemia da insuficiência renal crônica, é CORRETO afirmar:","options":{"A":"A anemia geralmente se instala de forma aguda devido à hematúria macroscópica provocada\npela insuficiência renal crônica.","B":"É ocasionada principalmente pela presença de anticorpos circulantes antieritropoetina.","C":"Em 95% dos casos é uma anemia microcítica e hipocrômica.","D":"A insuficiência renal geralmente ocasiona anemia aplástica com pancitopenia.","E":"Sua principal causa é a diminuição da produção de eritropoetina."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-47306","number":"47306","sourceNumber":"47306","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Insuficiência renal aguda, anemia hemolítica microangiopática e trombocitopenia na\npré-adolescência sugerem:","options":{"A":"doença de Von Willebrand.","B":"púrpura trombocitopênica.","C":"distúrbio mieloproliferativo.","D":"síndrome hemolítico-urêmica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-47782","number":"47782","sourceNumber":"47782","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As leucemias agudas são patologias graves, que acometem todas as faixas etárias e\nque exigem encaminhamento para centros\nespecializados em seu tratamento. Nas leucemias\nagudas:","options":{"A":"O diagnóstico é descartado em um paciente com 21% de blastos na medula óssea, mas sem\nblastos no sangue periférico.","B":"O subtipo mieloide é mais comum em crianças e o subtipo linfoide é mais comum em adultos.","C":"A presença de manifestações leves pode ocorrer por semanas a meses, antes que o paciente\nreceba o diagnóstico.","D":"A incidência na população é similar em indivíduos que já tenham sido submetidos ou não à\nquimioterapia."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-47817","number":"47817","sourceNumber":"47817","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente do sexo masculino, de 58 anos, 70 kg, portador de diabetes mellitus tipo 2\nhá cinco anos. Faz uso de metformina e\ninsulina. Foi internado na enfermaria da clínica médica\ncom pneumonia comunitária, quando foi iniciado o antibiótico ceftriaxone. Evoluiu nas últimas 12\nhoras com quadro de sepse grave e foi transferido para Unidade de Terapia Intensiva (UTI). Após\n12 horas da admissão, o paciente apresentava volume urinário de 350 ml, creatinina sérica de 2,1\nmg/dl ( creatinina na admissão de 1,0 mg/dl) ureia de 102 mg/dl (admissão: 42 mg/dl). O plantonista\nda UTI fez a classificação de RIFLE para insuficiência renal aguda (IRA) e solicitou a avaliação do\nserviço de nefrologia. Nesse caso, qual é a classificação da IRA?","options":{"A":"R (risco);","B":"I (injúria);","C":"F (falência);","D":"L (lesão)."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-51008","number":"51008","sourceNumber":"51008","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Débora, 11 anos, uma criança previamente saudável, desenvolve infecção\ngatrointestinal com cólicas e diarreia\naquosa. Após alguns dias, ela passa a apresentar sangue vivo\nnas fezes e é internada por desidratação. No hospital, nota-se diminuição do débito urinário.\n\nExames laboratoriais revelam aumento de ureia sanguínea, anemia, trombocitopneia e presença de\nesquizócitos. Qual gênero de bactéria é o mais provável causador da infecção sofrida por Débora?","options":{"A":"Campylobacter.","B":"Clostridium.","C":"Salmonella.","D":"Shigella.","E":"Vibrio."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-47630","number":"47630","sourceNumber":"47630","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma paciente do sexo feminino, de 52 anos, portadora de diabetes tipo 2 há 15 anos,\ncom retinopatia diabética, é encaminhada ao\nnefrologista devido à filtração glomerular estimada de\n18 ml/min. A classificação de doença renal crônica e o plano de ação a ser instituído para essa\npaciente são, respectivamente:","options":{"A":"Estágio 2: tratar as complicações e reduzir a progressão.","B":"Estágio 3: reduzir o fator de risco cardiovascular.","C":"Estágio 4: preparar para terapia renal substitutiva.","D":"Estágio 5: iniciar terapia renal substitutiva."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-48831","number":"48831","sourceNumber":"48831","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa que indica a melhor conduta na prevenção da nefropatia por\ncontraste.","options":{"A":"Infusão de 2 µcg/kg/min de dopamina.","B":"Infusão de furosemida 5 mg/h.","C":"Administração de n-acetilcisteína.","D":"Hemodiálise profilática.","E":"Administração endovenosa de soluções salinas como SF ou Bicarbonato de sódio."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-34012","number":"34012","sourceNumber":"34012","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Dentre os métodos para medida da taxa de filtração glomerular na doença renal\ncrônica:","options":{"A":"A creatinina sérica é o exame de escolha por não sofrer interferência da dieta.","B":"A medida da filtração glomerular por meio de equações, utilizando a creatinina sérica, é o mais\nrecomendado.","C":"A urografia excretora confere vantagens em relação aos outros exames, por associar exame de\nimagem e função.","D":"O clearance de creatinina é considerado o exame ?padrão-ouro?."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-35683","number":"35683","sourceNumber":"35683","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O sinal mais precoce da doença renal crônica é:","options":{"A":"Prurido.","B":"Hipertensão Arterial.","C":"Precardite.","D":"Anemia.","E":"Noctúria."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-9312","number":"9312","sourceNumber":"9312","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na síndrome urêmica, por aumento da produção de citocinas (TFN-a, interleucina-6) e\ndiminuição de interleucina-10, ocorre:","options":{"A":"aumento de sensibilidade à eritropoetina.","B":"diminuição da resistência à insulina.","C":"aumento do catabolismo muscular.","D":"diminuição do estresse oxidativo."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274016","number":"274016","sourceNumber":"274016","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar do sexo masculino, deu entrada em pronto-atendimento com história de\nfebre há 10 dias, de caráter intermitente,\ncom artralgias em membros inferiores, adinamia e com\naparecimento de equimoses em membros e parede abdominal. Ao exame físico, apresenta palidez\ne hepatoesplenomegalia. Fez hemograma, que evidenciou pancitopenia. O diagnóstico MAIS\nPROVÁVEL é:","options":{"A":"Leucemia aguda.","B":"Calazar.","C":"Mononucleose infecciosa.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274019","number":"274019","sourceNumber":"274019","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A Linfo-histiocitose ou síndrome hemofagocítica é uma desordem inflamatória com\nfagocitose de elementos sanguíneos, onde o macrófago, promove uma cascata inflamatória de\nforma desregulada, provocado secundariamente a uma série de agentes etiológicos. Selecione a\nopção correta, sobre o agente infeccioso mais comum da síndrome hemofagocítica secundária.","options":{"A":"Vírus da dengue.","B":"Leishmania sp.","C":"Citomegalovírus.","D":"Vírus Epstein Barr."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216423","number":"216423","sourceNumber":"216423","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à síndrome hemofagocítica, é correto afirmar, EXCETO:","options":{"A":"A presença de hemofagocitose no aspirado ou biópsia de medula óssea é a condição obrigatória\npara concluir o diagnóstico.","B":"São critérios diagnósticos: febre, esplenomegalia, citopenias afetando duas ou mais séries,\nhipertrigliceridemia, hipofibrinogenemia, entre outros.","C":"São etiologias comuns na forma secundária da doença: infecção por vírus Epstein-Barr, calazar,\nneoplasias hematológicas e colagenoses.","D":"Nível sérico de ferritina superior a 10.000 ng/mL tem alta especificidade para o diagnóstico,\nalém\nde ser importante marcador de atividade da doença, resposta terapêutica e prognóstico."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216203","number":"216203","sourceNumber":"216203","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Esplenomegalia e pancitopenia, associadas a um aspirado de medula óssea \"seco\"\nsuscitam como PRINCIPAL hipótese:","options":{"A":"Mielodisplasia.","B":"Leucemia de células pilosas.","C":"Anemia hemolítica extravascular.","D":"Anemia aplásica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-131915","number":"131915","sourceNumber":"131915","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente feminino, 62 anos, internada há 5 dias para tratamento de pneumonia\ncomunitária. Coletando exames diários, apresentava\ncreatinina sérica estável de 0,6 mg/dL nos\nprimeiros 4 dias de internação. Hoje, porém, apresentou creatinina de 0,9 mg/dL. Não vinha sendo\naferida diurese até então. Segundo os critérios RIFLE/AKIN para lesão renal aguda, neste\nmomento a paciente seria classificada como:","options":{"A":"Risk.","B":"Injury.","C":"Failure.","D":"O aumento da creatinina foi relevante, porém não é possível classificar a paciente devido à\nausência de aferição da diurese.","E":"O aumento da creatinina foi irrelevante, pois continua menor que 1,0 mg/dL, não se encaixando\nem nenhum dos estágios do RIFLE/AKIN."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-131874","number":"131874","sourceNumber":"131874","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menina de 5 anos de idade apresentando febre baixa intermitente, dor em membros\ninferiores, palidez, dor articular, epistaxe leve e dificuldade para deambular há 4 semanas. Ao\nexame físico, evidenciam-se equimoses em membros, petéquias disseminadas, mucosas\nhipocoradas, linfadenomegalia cervical e inguinal e hepatoesplenomegalia. Qual exame é\nimportante como investigação inicial?","options":{"A":"Coagulograma.","B":"Coombs direto e indireto.","C":"Pesquisa de anticorpo antiplaquetário.","D":"Hemograma.","E":"Fator reumatoide."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-84941","number":"84941","sourceNumber":"84941","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente chega ao pronto-socorro com aumento das escórias nitrogenadas. Dentre as\ninformações seguintes, qual a menos relevante para a suspeita de cronicidade da doença renal?","options":{"A":"Aterosclerose difusa.","B":"Na 129 mEq/L.","C":"Hb 10 g/dl.","D":"PTH 90 pg/ml.","E":"Poucos sintomas com Ur 180 mg/dl."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-47497","number":"47497","sourceNumber":"47497","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 49 anos de idade, com antecedente de hipertensão arterial sistêmica, em uso\nde clortalidona (25 mg/dia), procura assistência\nmédica em virtude de náusea, vômitos, diarreia e\ndiminuição do volume urinário há 1 semana. Exame físico: pulso: 92 bpm, PA: 110 x 70 mmHg.\n\nExames complementares: ureia: 240 mg/dl, creatinina: 3,3 mg/dl, sódio: 146 mEq/L, potássio: 3,9\nmEq/L, pH: 7,31 e bicarbonato: 19 mmol/L. Nesse momento, é CORRETO:","options":{"A":"Indicar hemodiálise.","B":"Indicar diálise peritoneal.","C":"Estimular a diurese com furosemida.","D":"Prescrever hidratação com soro fisiológico.","E":"Prescrever bicarbonato de sódio com potássio."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-263720","number":"263720","sourceNumber":"263720","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Adolescente de 15 anos de idade apresenta adenomegalia cervical unilateral há 6\nmeses e com crescimento progressivo; nos\núltimos 2 meses cursa com febre diária, perda de peso\ne sudorese. Qual diagnóstico mais provável?","options":{"A":"Linfoma de Burkitt.","B":"Neuroblastoma.","C":"Carcinoma de tireoide.","D":"Linfoma de Hodgkin.","E":"Carcinoma de glândulas salivares."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-278969","number":"278969","sourceNumber":"278969","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual é a causa mais frequente de linfadenomegalia na infância?","options":{"A":"Linfoma de Hodgkin","B":"Tuberculose","C":"Hiperplasia reacional","D":"Doença da arranhadura do gato","E":"Toxoplasmose adquirida"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-244709","number":"244709","sourceNumber":"244709","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A síndrome da lise tumoral que pode ocorrer no tratamento de algumas doenças\nonco-hematológicas com grande significado em pediatria, tem como alterações metabólicas\nclássicas:","options":{"A":"Hiperuricemia ? hipocalemia ? hipercalcemia.","B":"Hipocalcemia ? hipofosfatemia ? hiperuricemia.","C":"Hipercalcemia ? hipercalemia ? hipofosfatemia.","D":"Hiperuricemia ? hipercalemia ? hiperfosfatemia.","E":"Hiperuricemia ? hipocalemia ? hipercalcemia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-252447","number":"252447","sourceNumber":"252447","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança de três anos, sexo masculino, internada em um hospital municipal,\ndiagnosticada recentemente com Leucemia Linfoide Aguda,\naguardando transferência para\nHospital especializado em Oncologia Pediátrica, evoluindo com desconforto respiratório, queda\nrepentina dos leucócitos de 100.000 mm³ para 13.000 mm³. O médico que estava de plantão\ndesconfiou da hipótese diagnóstica de síndrome de lise tumoral. Quais exames laboratoriais\ndeveria solicitar para diagnosticar a provável Síndrome de Lise Tumoral?","options":{"A":"Solicitar estudo genético para avaliar presença de cromossomo Filadélfia","B":"Solicitar novo mielograma com imunofenotipagem.","C":"Potássio sérico, cálcio sérico, fósforo sérico e ácido úrico.","D":"Solicitar Petscan","E":"Solicitar triglicérides, ferritina, dhl e fibrinogênio"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-203314","number":"203314","sourceNumber":"203314","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Analise, nos itens abaixo, o que se considera indicação de Esplenectomia e, em\nseguida, escolha a opção correta: I. Hiperesplenismo por doença autoimune; II. Traumatismo de\nbaço grau II; III. Lesão incidental;","options":{"A":"Somente I está correto","B":"Somente II está correto","C":"Todos estão corretos","D":"Somente II e III estão corretos","E":"Somente I e III estão corretos"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-203205","number":"203205","sourceNumber":"203205","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As doenças linfoproliferativas pró-transplante (PTLD ? do inglês Post-Transplant\nLymphoproliferative Disorders) podem representar uma\ncomplicação grave da imunossupressão. O\npatógeno que está intimamente ligado à indução da patologia em destaque é:","options":{"A":"Herpes vírus humano tipo 6.","B":"Vírus Epstein-Barr.","C":"CMV.","D":"Vírus varicela-zóster.","E":"HIV."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-175057","number":"175057","sourceNumber":"175057","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente feminina, 22 anos, procura o ambulatório de clínica médica de um hospital de\nreferência queixando-se de febre vespertina, perda ponderal não quantificada, sudorese noturna e\naumento do volume cervical há 6 meses. Ao exame notava-se adenomegalias cervicais e\nsupraclaviculares à direita, indolores e endurecidas. Sem evidência de visceromegalias.\n\nApresentava hemograma normal e alargamento de mediastino na radiografia de tórax. Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Linfoma não Hodgkin.","B":"Linfoma de Hodgkin","C":"Leucemia linfoide crônica","D":"Leucemia mieloide aguda","E":"Leucemia mieloide aguda"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-177511","number":"177511","sourceNumber":"177511","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Ao avaliar um paciente de 52 anos pancitopênico com eritroblastos na periferia, dentre\nas possibilidades diagnósticas apresentadas\nabaixo, devemos pensar preferencialmente em:","options":{"A":"Mielodisplasia","B":"Deficiência de vitamina B12","C":"Anemia aplásica","D":"Esferocitose hereditária","E":"Ocupação medular por doença maligna"},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-154401","number":"154401","sourceNumber":"154401","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar de 10 anos com diagnóstico de leucemia linfoblástica aguda apresenta\nsufusões hemorrágicas e hepatoesplenomegalia. Os\nexames laboratoriais apresentam hemograma\n\n= 110.000 leucócitos/ mm³ e predomínio de blastos; Hemoglobina = 7g/dl; Plaquetas = 20.000/mm³.\nApós iniciada a quimioterapia, as alterações\nesperadas para este paciente são:","options":{"A":"Hipercalemia, hipofosfatemia, hiperuricemia.","B":"Hipercalemia, hiperfosfatemia, hiperuricemia.","C":"Hipernatremia, hipercalemia, hiperfosfatemia.","D":"Hipernatremia, hipercalcemia, hiperuricema.","E":"Hipocalemia, hipocalcemia, hiperuricemia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-132774","number":"132774","sourceNumber":"132774","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 46 anos, internado para investigação de ascite. Após paracentese\ndiagnóstica e exames de sangue, é obtido um gradiente de albumina soro-ascite de 1,9 g/dL. O\ndiagnóstico menos provável deste paciente é:","options":{"A":"Síndrome nefrótica.","B":"Síndrome de Budd-Chiari.","C":"Hepatite alcoólica.","D":"Pericardite constritiva.","E":"Cirrose."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-140003","number":"140003","sourceNumber":"140003","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A redução da perfusão renal é responsável por 40-80% dos casos de insuficiência renal\naguda e, se for tratada adequadamente, pode ser revertida facilmente. Acerca dessa condição,\ntemos as seguintes afirmações: I. As etiologias da azotemia pré-renal incluem qualquer causa de\nredução de volume sanguíneo circulante (hemorragia gastrintestinal, queimaduras, diarreia,\ndiuréticos, peritonite, choque cardiogênico, sepse). II. O bloqueio da produção de prostaglandinas\npelos AINEs pode causar vasoconstrição arteriolar eferente e diminuindo a taxa de filtração\nglomerular. III. Os pacientes tratados com AINEs e/ou com inibidores da ECA/BRA são mais\nsuscetíveis à insuficiência renal aguda mediada hemodinamicamente, quando ocorre redução do\nvolume sanguíneo por qualquer motivo. IV. Os pacientes com estenose bilateral das artérias renais\n(ou estenose de um rim único) dependem da vasoconstrição arteriolar eferente para manter a\npressão de filtração glomerular e são particularmente suscetíveis a um declínio acelerado da TFG,\nquando utilizam inibidores da ECA ou BRA. V. Em geral, o sedimento da urina dos pacientes com\nazotemia pré-renal é normal ou, ocasionalmente, apresenta cilindros hialinos e granulosos,\nenquanto o sedimento da NTA mostra-se habitualmente repleto de restos celulares e cilindros\ngranulosos escuros (marrom fosco). Estão corretas apenas:","options":{"A":"I, III, IV, V","B":"I, II, III","C":"III, IV","D":"II, III, V","E":"I, II, III, IV, V"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-107957","number":"107957","sourceNumber":"107957","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação à Insuficiência Renal Crônica (IRC), qual das seguintes afirmativas é\nverdadeira?","options":{"A":"A anemia se estabelece em pacientes com IRC a partir do estágio 4.","B":"O potássio é o primeiro íon a se elevar, devendo ser imediatamente tratado devido ao risco de\narritmias potencialmente fatais.","C":"A anemia por deficiência absoluta de eritropoietinia é sua principal causa.","D":"A uropatia obstrutiva é a terceira causa mais comum de IRC a nível mundial.","E":"Ultrassonografia de rins pode ser normal mesmo em estágios avançados da doença, como no\nportadores de Diabetes Mellitus tipo 2."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-89597","number":"89597","sourceNumber":"89597","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sistema RIFLE, para avaliar o desenvolvimento de Insuficiência renal no paciente\ngravemente enfermo avalia três níveis\ncrescente de gravidade fundamentados na concentração da\ncreatinina sérica e redução do débito urinário. Qual das opções abaixo corresponde o nível de\ngravidade com alteração no valor da concentração da creatinina sérica e débito urinário:","options":{"A":"Risco o paciente apresenta aumento 1,0 X a creatinina com débito urinário menor que 0,5\nml/kg/h por 4 horas.","B":"Risco o paciente apresenta aumento 1,5 X a creatinina com débito urinário menor que 0,5\nml/kg/h por 6 horas.","C":"Injúria o paciente apresenta aumento de 2,5 X o valor da creatinina e débito urinário menor que\n0,5 ml/kg/h por 8 horas.","D":"Injúria o paciente apresenta aumento de 2,0 X o valor da creatinina e débito urinário menor que\n0,5 ml/kg/h por 6 horas.","E":"Falência o paciente apresenta aumento de 3,5 X o valor da creatinina e débito urinário menor\nque 0,5 ml/kg/h por 12 horas."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-89227","number":"89227","sourceNumber":"89227","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação à rabdomiólise, é incorreto afirmar:","options":{"A":"É uma importante causa de insuficiência renal aguda","B":"O uso de etanol consiste na causa mais comum dentre as drogas e toxinas que causam\nrabdomiólise","C":"A combinação de estatinas e fibrato implica aumento de risco de rabdomiólise","D":"A determinação sérica de mioglobina é melhor que a de CPK na avaliação da rabdomiólise","E":"Durante o tratamento o volume de fluidos necessário pode chegar a 10-14 L/dia ou mais"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-87500","number":"87500","sourceNumber":"87500","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Dos achados laboratoriais abaixo, qual falaria mais a favor de insuficiência renal\nparenquimatosa, em detrimento de insuficiência pré-renal?","options":{"A":"Cilindros urinários epiteliais.","B":"Sódio urinário abaixo de 20 mEq/L.","C":"Osmolalidade urinária maior que 500 mOsm/kg.","D":"Fração excretória de sódio de 0,8%.","E":"Cistatina C sérica elevada."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-89300","number":"89300","sourceNumber":"89300","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As causas mais comuns de Insuficiência Renal Aguda em crianças são, exceto:","options":{"A":"Pielonefrite aguda","B":"SHU (Síndrome Hemolítico-Urêmica)","C":"Necrose Tubular Aguda","D":"Sepse","E":"Glomerunonefrite"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-362843","number":"362843","sourceNumber":"362843","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pais relatam que, há aproximadamente 20 dias, seu filho de cinco anos iniciou quadro\nde adinamia, fadiga, dores em membros\ninferiores e nas articulações dos joelhos, febre intermitente\ne equimoses pelo corpo, após traumas leves. Exame físico: palidez cutâneo mucosa ++/4+,\nlinfonodomegalias em região cervical bilateralmente, baço palpável a 6,5cm do rebordo costal\nesquerdo, fígado palpável a 3,5cm do rebordo costal direito, equimoses difusas em membros\ninferiores e dorso. Há cerca de uma semana, foi iniciado pelo médico assistente corticoide via oral\npara criança, com melhora das dores em membros inferiores. Exames laboratoriais: hematimetria:\n2.800.000/ mm3, hematócrito: 22,5%; hemoglobina: 7,4g/dL, VCM: 78,3fL, CHCM: 32,8g/dL; HCM:\n25,7pg; leucócitos: 8.000/mm3 (linfócitos 88%, segmentados 12%), contagem de plaquetas\n25.000/mm3. Qual a principal hipótese diagnóstica?","options":{"A":"Leishmaniose visceral","B":"Artrite reumatoide","C":"Leucemia linfoide aguda","D":"Mononucleose infecciosa"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-327331","number":"327331","sourceNumber":"327331","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 31 anos, procurou atendimento médico pois notou nódulo em axila esquerda\nque vem aumentando de tamanho, associado à\nfadiga, perda de peso e febre não aferida. Foi\nsubmetido à biópsia, em que foram visualizadas células gigantes, multinucleadas, com nucléolos\nevidentes, compatíveis com células de Reed- Sternberg. Diante do quadro clínico e do resultado da\nbiópsia, qual a hipótese diagnóstica?","options":{"A":"Tuberculose ganglionar","B":"Linfoma de Hodgkin","C":"Linfoma não Hodgkin","D":"Micose fungoide"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-348442","number":"348442","sourceNumber":"348442","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar de 10 anos, sexo masculino, com história de febrícula e sudorese noturna há\nmais de um mês, é levado à consulta no posto de saúde. Relata aparecimento de ínguas nas\nregiões cervical, axilar, inguinal e supraclavicular, de dor abdominal difusa leve, astenia e perda\nponderal de 2kg em 1 mês. Nega casos de tuberculose na família. Vacinas em dia. Nega doenças\nou comorbidades. Há 3 meses, fez uso de Nitazoxanida. O exame inicial evidenciou paciente em\nbom estado geral, hipocorado ++/4+, hidratado, anictérico, acianótico, febril (38ºC), eupneico,\nconsciente e orientado. Pressão arterial de 100×60mmHg e frequência cardíaca de 80bpm. Exame\ncardíaco e pulmonar apresentavam-se normais. Ao exame de abdome apresentou esplenomegalia\npalpável a 3cm do rebordo costal esquerdo; hepatomegalia palpável a 5cm do rebordo costal\ndireito. Linfadenopatias palpáveis e visíveis nas cadeias ganglionares cervicais, supraclaviculares,\naxilares e inguinais. Exames laboratoriais: Hemograma: Ht 30%, Hb 9,5g/dL, Leucócitos\n15.600/mm³ (Neutrófilos 13%, Linfócitos 81%, Eosinófilos 3%, macrófagos 3%), Plaquetas\n175.000/mm³. Teste tuberculínico: < 5mm. Baciloscopias de escarro induzido negativas. Cultura\nainda sem resultado. VHS: 85 mm/1ª hora. Sorologias negativas para toxoplasmose, rubéola, HIV,\ncitomegalovirose, mononucleose infecciosa e sífilis. Radiografia de tórax: massa volumosa no\nmediastino médio de contornos irregulares com calcificações. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Cisto broncogênico","B":"Tuberculose ganglionar","C":"Neuroblastoma","D":"Linfoma"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-330890","number":"330890","sourceNumber":"330890","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A criança possui mais tecido linfoide que o adulto e apresenta resposta mais\nexacerbada aos antígenos externos, o que contribui para a incidência aumentada de\nlinfadenomegalias na infância. Sobre as linfadenomegalias, é correto afirmar:","options":{"A":"O linfoma não Hodgkin cursa com linfadenomegalia localizada, volumosa e assimétrica em\nrelação ao lado contra lateral.","B":"Os linfonodos dolorosos se devem à vasodilatação de liberação de bradicininas e são exclusivos\nde quadros infecciosos.","C":"Aumento dos linfonodos occipitais em crianças menores são sinais de alerta para doenças\nlinfoproliferativas, como os linfomas.","D":"A adenopatia reacional é a causa mais comum de aumento do tamanho dos linfonodos e surge\ndevido ao aumento das células intrínsecas do tecido linfoide."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-308312","number":"308312","sourceNumber":"308312","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 64 anos, previamente hígido, vem ao ambulatório relatando astenia há 1\nano, perda de peso (10 kg em 6 meses) e dor em hipocôndrio esquerdo. Ao exame físico,\napresenta esplenomegalia. Hemograma apresenta série vermelha com anemia e presença de\nhemácias em lágrimas: série branca com leucocitose, desvio até mielócitos e plaquetopenia.\n\nObserve o hemograma a seguir. Qual é a conduta a ser seguida?","options":{"A":"Iniciar antibioticoterapia.","B":"Investigar lúpus eritematoso sistêmico.","C":"Solicitar eletroforese de proteínas.","D":"Biópsia de medula óssea."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-313407","number":"313407","sourceNumber":"313407","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher, 65 anos, com diagnóstico de leucemiae passado de infecção fúngica, tendo a\núltima quimioterapia há 15 dias em ambiente hospitalaronde permanece desde então devido\nplaquetopeniacom necessidade de transfusões, inicia quadro febril com picos de até 39ºC. Ao\nexame físico não é possível estabelecer foco infeccioso. PA de 120x80 mmHg. Ausência de sinais\nde desidratação. Hemograma revela neutrófilos de 100. PCR elevada. A melhor conduta\nantimicrobiana nesse momento é:","options":{"A":"Cefepime endovenoso;","B":"Fluconazol endovenoso;","C":"Ertapenem endovenoso;","D":"Ciprofloxacino + amoxicilina/clavulanato."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-267280","number":"267280","sourceNumber":"267280","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A doença de Chagas é uma doença tropical, causada pelo parasita Trypanossoma\ncruzi, que acomete o coração e o sistema\ndigestivo. Sua transmissão para seres humanos e outros\nmamíferos ocorre pelo inseto vetor conhecido como \"barbeiro\". Considerando o envolvimento\ncardíaco na doença de Chagas, assinale a afirmativa INCORRETA.","options":{"A":"As principais complicações cardíacas da doença de Chagas são arritmias cardíacas, disfunção\nventricular e eventos tromboembólicos.","B":"O Trypanossoma cruzi pode acometer o sistema de condução especializado do coração, o\nmiocárdio contrátil e o sistema nervoso intramural.","C":"A disfunção ventricular na cardiomiopatia chagásica crônica acomete predominantemente o\nventrículo esquerdo.","D":"Os achados eletrocardiográficos mais comuns na cardiomiopatia chagásica crônica são bloqueio\nde ramo direito e bloqueio divisional\nântero-superior esquerdo."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-258921","number":"258921","sourceNumber":"258921","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 69 anos, sexo masculino, aposentado, vem ao Pronto Atendimento para\nconsulta, apresentando-se com dispneia e fadiga há\noito semanas com piora gradativa e agravo da\nsituação nas últimas 48 horas. Tem antecedentes de HAS bem controlada com metoprolol e\nnifedipina, além de artrite reumatoide com envolvimento de ambas as mãos, já em fase de\nremissão. Ao exame, apresenta PA de 130 x 80 mmHg, FC: 99 BPM e FR de 21 IRPM Sat O2 =\n95%. Está hipocorado 3+/4+, com petéquias e hematomas nos membros superiores e inferiores.\n\nRCR com sopro sistólico em região paraesternal de 3+/6+. Não apresenta visceromegalias.\nRealizou exames, sendo evidenciado hematócrito\nde 21% com volume corpuscular médio (VCM) de\n106 fL, contagem de leucócitos de 2.400 células/mm3 com 60% de neutrófilos, e contagem de\nplaquetas de 38.000/mm³. Em relação ao caso clínico, a principal hipótese diagnóstica é:","options":{"A":"Estenose Mitral.","B":"Síndrome Mielodisplásica.","C":"Púrpura Trombocitopênica Essencial.","D":"Púrpura Trombocitopênica Trombótica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-283983","number":"283983","sourceNumber":"283983","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher, 65 anos, com diagnóstico de leucemia e passado de infecção fúngica, tendo a\núltima quimioterapia há 15 dias em ambiente hospitalar onde permanece desde então devido\nplaquetopenia com necessidade de transfusões, inicia quadro febril com picos de até 39oC. Ao\nexame físico não é possível estabelecer foco infeccioso. PA de 120x80mmHg. Ausência de sinais\nde desidratação. Hemograma revela neutrófilos de 100. PCR elevada. A melhor conduta\nantimicrobiana nesse momento é:","options":{"A":"cefepime endovenoso","B":"fluconazol endovenoso","C":"ertapenem endovenoso","D":"ciprofloxacino + amoxacilina/clavulanato"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-247680","number":"247680","sourceNumber":"247680","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo feminino, 50 anos, em tratamento quimioterápico para câncer de\nmama, procura pronto atendimento por tosse\nseca há 2 dias, e febre de 39ºC iniciada hoje. Nega\nsintomas urinários ou gastrointestinais, bem como comorbidades. Sinais vitais normais (exceto por\ntemperatura atual de 38,7ºC). Exame segmentar respiratório, cardíaco, abdominal e da pele não\nrevelam anormalidades. Hemograma colhido na urgência mostra Hb = 9,5 leucócitos = 1.900\n(segmentados 25%, bastões 2%) e plaquetas = 90.000. Função hepática e renal normais. Rx tórax\nnormal. Diante desse quadro, a conduta mais adequada é:","options":{"A":"Internação em UTI, colher hemocultura e urocultura, e iniciar antibioticoterapia cobrindo germes\ngram-positivos e gram-negativos, aeróbios e anaeróbios.","B":"Colher hemocultura e urocultura, dar medicamentos sintomáticos e fazer curva térmica nas\npróximas 24 horas.","C":"Hospitalização, coleta de hemocultura e urocultura, e antibioticoterapia com cefalosporina de 3ª\ngeração e macrolídeo por 7 a 14 dias.","D":"Por se tratar de quadro de baixo risco, pode ser tratado com amoxicilina+clavulanato e\nciprofloxacino oral por internação breve ou mesmo ambulatorialmente."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-214578","number":"214578","sourceNumber":"214578","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem, 56 anos, obeso, com hipertensão e diabetes mal controlados. Apresenta-se\ncom febre há 5 dias e celulite extensa em\nmembro inferior direito relacionada à úlcera plantar\ninfectada. Hemograma de admissão: glóbulos vermelhos = 3.800.00/mm³; hemoglobina = 11,5 g/dl;\nhematócrito = 34,8%; VCM = 87 fl; HCM = 32 pg/mm³; glóbulos brancos = 43.000/mm³ (mielócitos =\n4%; metamielócitos = 7%; bastões = 13%; neutrófilos = 55%; basófilos = 0%; eosinófilos = 4%;\n\nlinfócitos = 8%; monócitos = 9%); RDW = 16%; reticulócitos = 1,3%; plaquetas = 520.000. A\nhipótese diagnóstica e a conduta são:","options":{"A":"Leucemia mieloide aguda; mielograma e hibridação fluorescente in situ (FISH).","B":"Reação leucemoide e plaquetose reacional; iniciar antibioticoterapia.","C":"Leucemia mieloide aguda e quadro reacional sobreposto; mielograma e antibioticoterapia.","D":"Leucemia mieloide crônica; mielograma e pesquisa de cromossomo Philadelphia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221350","number":"221350","sourceNumber":"221350","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No Brasil, devido à efetividade do controle dos serviços de hemoterapia e,\nconsequentemente, maior qualidade do sangue\npara transfusão, tem-se alcançado significativo\nimpacto no controle da transmissão transfusional do T. cruzi. Marque o item ERRADO.","options":{"A":"Representa via sem importância de propagação da doença nos centros urbanos.","B":"É considerada a principal forma de transmissão em países não endêmicos como Canadá,\nEspanha, Estados Unidos e outros.","C":"É considerada a principal forma de transmissão em países latino-americanos que estejam em\nprocesso de controle da transmissão vetorial.","D":"Vertical ? ocorre, principalmente, pela via transplacentária e pode ocorrer em qualquer fase da\ndoença (aguda ou crônica)."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221357","number":"221357","sourceNumber":"221357","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A maioria dos indivíduos com infecção por T. cruzi alberga o parasito no sangue, nos\ntecidos e órgãos, durante toda a vida. Na fase aguda inicial, podemos aceitar todos os itens abaixo,\napenas um está incorreto, indique o INCORRETO.","options":{"A":"Predomina o parasito em número elevado circulante na corrente sanguínea.","B":"A manifestação mais característica é a febre constante, inicialmente elevada (38,5 a 39°C),\npodendo apresentar picos vespertinos ocasionais.","C":"As manifestações de síndrome febril podem persistir por até 12 meses.","D":"Esta fase aguda inicial, mesmo não tratada nem diagnosticada, pode evoluir com\ndesaparecimento espontâneo da febre e da maior parte das outras manifestações clínicas,\nevoluindo para a fase crônica."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221362","number":"221362","sourceNumber":"221362","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma das formas habituais de transmissão de T. cruzi para o homem, o vetor\n(triatomíneo), ao se alimentar em mamíferos\ninfectados com elevadas taxas de T. cruzi, pode se\ninfectar e, ao se alimentar novamente, infecta outro mamífero, inclusive o homem. Somente um\nitem se apresenta INCORRETO. Indique-o.","options":{"A":"Sinais de porta de entrada, característicos da transmissão vetorial, como o sinal de Romaña\n(edema bipalpebral unilateral por reação\ninflamatória à penetração do parasito, na conjuntiva e\nadjacências).","B":"Deve-se ressaltar que a picada de um triatomíneo pode causar reações alérgicas locais ou\nsistêmicas, sem que isso signifique, necessariamente, infecção por T. cruzi.","C":"No caso da doença de Chagas aguda (DCA) por transmissão oral, os surtos estudados parecem\nindicar diferenças na evolução clínica por esta forma de transmissão.","D":"Chagoma de inoculação (lesões furunculoides, supurativas, em membros, tronco e face, por\nreação inflamatória à penetração do parasito, que se mostram descamativas após duas ou três\nsemanas) são menos frequentes."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221364","number":"221364","sourceNumber":"221364","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No caso da doença de Chagas aguda (DCA) devido à transmissão oral, os estudos\nindicam diferenças na evolução clínica por esta\nforma de transmissão. Têm sido relatados:\nexantema cutâneo, hemorragia digestiva (hematêmese, hematoquezia ou melena), icterícia,\naumento das aminotransferases, além de quadros mais frequentes e mais graves de insuficiência\ncardíaca. Está ERRADO, apenas um item. Indique-o.","options":{"A":"Fenômenos de enterite, abdome agudo e sangramento fecal.","B":"Ressalta-se que a morbimortalidade é mais baixa na transmissão oral que a observada nos\ncasos agudos por transmissão vetorial.","C":"Choque, hepatite focal podem ocorrer e têm significação prognóstica variada, devendo ser\nrotineiramente pesquisados e monitorados.","D":"Quadros clínicos graves pode cursar com meningoencefalite, especialmente em lactente ou em\ncasos de reativação (pessoas com\ncomprometimento imunológico)."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221387","number":"221387","sourceNumber":"221387","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Métodos parasitológicos diretos na fase aguda, sendo o exame parasitológico o mais\nindicado nesta fase. Somente sendo INCORRETO que","options":{"A":"é definido pela presença de parasitos circulantes.","B":"é definido pela presença de parasitos demonstráveis no exame direto do sangue periférico.","C":"a situação ideal é a realização da coleta com paciente febril e dentro de 30 dias do início de\nsintomas.","D":"incluem: pesquisa a fresco de tripanossomatídeos ? execução rápida e simples, sendo menos\nsensível que o esfregaço corado."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-208608","number":"208608","sourceNumber":"208608","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual das seguintes alternativas relativas à toxoplasmose ocular é FALSA:","options":{"A":"menos de 10% dos indivíduos com idade inferior a 5 anos demonstram anticorpos contra\ntoxoplasmose","B":"oocistos de toxoplasma espalhados pelos gatos nas suas fezes podem permanecer infectantes\npor mais de 1 ano","C":"a infecção materna no início da gravidez resulta em alto risco de infecção para o feto","D":"retinocoroidite geralmente envolve a periferia da retina e raras vezes envolve mácula","E":"nenhuma das alternativas é falsa"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221418","number":"221418","sourceNumber":"221418","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Considerando a morbidade e a mortalidade potencial, o diagnóstico e o manejo\napropriado da reativação da doença de Chagas no contexto de transplante de órgãos é\nextremamente importante. Está CORRETO que:","options":{"A":"A doença de Chagas constitui a primeira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento.","B":"A doença de Chagas constitui a terceira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento.","C":"A doença de Chagas constitui a terceira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 95% dos pacientes submetidos ao procedimento.","D":"A doença de Chagas constitui raramente causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-177275","number":"177275","sourceNumber":"177275","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Menino, 5 anos, é levado ao pronto-socorro devido eritema e edema do olho direito. O\nexame físico revela conjuntivite\ngranulomatosa no olho direito e um linfonodo pré auricular doloroso\nà palpação. Ademais, há outros linfonodos palpáveis na região submandibular ipsilateral. Mãe nega\nfebre, sintomas respiratórios, náusea e vômitos ou diarreia, e revela que a família ganhou um gato\nnovinho há 4 meses. O provável agente etiológico do quadro clínico é:","options":{"A":"staphylococcus aureus","B":"adenovírus tipo 7","C":"bartonella henselae","D":"toxoplasma gondii","E":"citomegalovírus"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-181082","number":"181082","sourceNumber":"181082","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A neutropenia significa diminuição dos neutrófilos e está presenta quando sua\nquantidade cai abaixo de 1500 celulas/µL. Tal situação é encontrada em alguns pacientes\noncológicos. O risco de infecções graves ocorre quando seus níveis caem abaixo de 500\ncélulas/µL. Qual o sitio de infecção mais comum:","options":{"A":"Genitália;","B":"Pele;","C":"Períneo;","D":"Mucosa."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-181610","number":"181610","sourceNumber":"181610","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 42 anos, previamente hígido, com diagnóstico de câncer de mama em\ntratamento quimioterápico pós-operatório. Fez 3\nciclos de quimioterapia sem intercorrências. Há 14\ndias fez o 4º ciclo, também sem toxicidades até o momento. Há 24 horas iniciou febre associada a\ncalafrios. Nega sintomas respiratórios, digestivos ou urinários. Ao exame: TAx = 38,5°C; PA = 125 x\n85 mmHg; FC = 89 bpm; FR = 16 irpm. Ausculta cardiopulmonar sem anormalidades. Radiografia\nde tórax e EAS normais. Hemograma mostra 1.200 leucócitos, 400 neutrófilos, sem desvio.\n\nHemoglobina = 9,0 g/dl e plaquetas normais. Função hepática e renal normais. A abordagem mais\napropriada para o caso é:","options":{"A":"Internação hospitalar, coleta de culturas e administração de sintomáticos, aguardando resultados\ndas culturas para instituição de terapêutica\nguiada por antibiograma.","B":"Oferecer tratamento ambulatorial com amoxicilina + clavulanato associado à quinolona, com\norientações para retornar se piorar ou febre não ceder em 48 horas, se paciente bem orientado.","C":"Internação em Unidade de Terapia Intensiva (leito de isolamento) e instituição imediata de\nantibioticoterapia de amplo espectro cobrindo Gram-positivos e negativos.","D":"Iniciar protocolo de sepse com terapia de reposição hídrica agressiva, hemotransfusão para\ncorrigir anemia e antibioticoterapia de amplo espectro."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-181541","number":"181541","sourceNumber":"181541","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação ao agente etiológico da toxoplasmose, analise as afirmativas abaixo. I -\nApresenta três formas durante o seu ciclo de vida: oocistos, taquizoítos e bradizoítos; II - É um\nprotozoário extracelular que acomete preferencialmente o sistema nervoso central; III - O parasita\nse multiplica no intestino dos felinos e os oocistos resultantes são eliminados nas fezes; IV - A\ncontaminação humana pode ocorrer pela ingestão de carnes cruas ou frutas, verduras e legumes\nmal lavados. Está CORRETO o que se afirma em:","options":{"A":"I, III e IV, apenas.","B":"II e IV, apenas.","C":"I, II e III, apenas.","D":"III e IV, apenas."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-85000","number":"85000","sourceNumber":"85000","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à Doença Renal Crônica (DRC), marque V para as afirmativas Verdadeiras\ne F para as Falsas. ( ) As etiologias mais\nfrequentes de DRC são: nefropatia diabética e\nnefroesclerose hipertensiva; ( ) A insuficiência coronariana é fator de alto risco para o\ndesenvolvimento de DRC; ( ) No sentido de hiperfiltrar, os néfrons remanescentes dilatam as\narteríolas aferente e eferente; ( ) No hiperparatireoidismo secundário à DRC, o PTH está\naumentado, o cálcio normal ou diminuído e o fósforo diminuído; ( ) O prurido do paciente com DRC\né multifatorial, e um dos fatores é a ação direta do PTH na pele. Assinale a sequência CORRETA:","options":{"A":"F, F, V, F, V.","B":"V, V, F, F, V.","C":"F, F, F, V, F.","D":"V, V, V, V, F."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-75398","number":"75398","sourceNumber":"75398","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à doença de Chagas, assinale a afirmativa INCORRETA.","options":{"A":"A reativação da doença, com manifestações da fase aguda, pode ocorrer em pacientes\nimunocomprometidos (uso de drogas imunossupressoras, neoplasias hematológicas) ou em\ncoinfecção pelo HIV.","B":"A transmissão do agente etiológico, Tripanossoma cruzi, pode ocorrer via oral, vetorial,\ntransfusional, transplacentária, por aleitamento materno e transplante de órgãos.","C":"Pessoas infectadas pelo Tripanossoma cruzi armazenam o parasito nos tecidos e/ou sangue por\ntoda a vida, sendo consideradas potencialmente infectantes, mesmo quando assintomáticas.","D":"A reação à picada do triatomídeo, caracterizada por edema local, reconhecida clinicamente\ncomo ?chagoma de inoculação?, na pele exposta, ou\n?sinal de Romanã?, na região periorbitária,\nconfirma o diagnóstico de infecção pelo\n\nTripanossoma cruzi."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-360605","number":"360605","sourceNumber":"360605","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Os pacientes com cardiomiopatia crônica da doença de Chagas - CCDC:","options":{"A":"Demonstram resposta inflamatória mais branda do que aqueles com forma indeterminada da\ndoença de Chagas FIDC, que parecem ter\nresposta imunológica mais bem regulada.","B":"Apresentam resposta inflamatória mais intensa do que aqueles com forma indeterminada da\ndoença de Chagas FIDC, que claramente\napresentam resposta imunológica menos regulada.","C":"Apresentam resposta imune mais intensa do que aqueles com forma indeterminada da doença\nde Chagas FIDC, que assim parecem ter resposta\nimunológica mais intensa e desregulada.","D":"Apresentam resposta inflamatória mais intensa do que aqueles com forma indeterminada da\ndoença de Chagas FIDC, que parecem ter\nresposta imunológica mais bem regulada."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-301600","number":"301600","sourceNumber":"301600","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança com dor musculoesquelética pode apresentar alterações radiológicas que\nsugerem leucemia. Das alternativas apresentadas, qual a que apresenta um achado radiológicos\nsugestivo de leucemia nessas crianças?","options":{"A":"Fraturas de estresse.","B":"Rarefação metafisária.","C":"Osteoporose.","D":"Erosões ósseas."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-274977","number":"274977","sourceNumber":"274977","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança, 8 anos, sexo masculino, em tratamento com quimioterapia devido à leucemia,\nprocura o pronto atendimento com quadro de febre intensa (39?40ºC). Ao exame: REG, descorado\n1+/4+, hidratado, acianótico, anictérico, sem sinais de irritação meníngea. Oroscopia e otoscopia\nnormais. AP: murmúrio vesicular presente, sem ruídos adventícios. ACV: RCR 2T sem sopro.\n\nAbdome: flácido, indolor, sem massas ou visceromegalias, RHA +. Pulsos +, perfusão 2 segundos.\nColhidos exames e culturas (hemocultura e urocultura), optou-se por internação e início de\nantibioticoterapia. Nesse caso, qual seria o antibiótico para iniciar?","options":{"A":"Ceftriaxona.","B":"Cefalexina.","C":"Amoxicilina.","D":"Sulfametoxazol + trimetoprima.","E":"Piperacilina + tazobactama."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-239675","number":"239675","sourceNumber":"239675","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A apresentação clínica Fase aguda da doença de Chagas por transmissão vetorial está\nde acordo com o item:","options":{"A":"O quadro clínico da doença aguda, nos casos de transmissão vetorial, não é polimórfico, indo\ndesde a descrição clássica (sinal de porta de entrada da infecção, febre, edema subcutâneo,\naumento do volume de linfonodos, hepatomegalia, esplenomegalia, além de evidências de\nmiocardite e de meningoencefalite) até situações oligossintomáticas e inaparentes.","B":"O quadro clínico da doença aguda, nos casos de transmissão vetorial, é polimórfico, indo desde\na descrição clássica (sinal de porta de entrada\nda infecção, febre, edema subcutâneo, aumento do\nvolume de linfonodos, hepatomegalia, esplenomegalia, nunca com evidências de miocardite e de\nmeningoencefalite) até situações oligossintomáticas e inaparentes.","C":"O quadro clínico da doença aguda, nos casos de transmissão vetorial, é polimórfico, indo desde\na descrição clássica (sinal de porta de entrada\nda infecção, febre, edema subcutâneo, aumento do\nvolume de linfonodos, hepatomegalia, esplenomegalia, além de evidências de miocardite e de\nmeningoencefalite) até situações oligossintomáticas e inaparentes.","D":"O quadro clínico da doença aguda, nos casos de transmissão vetorial, é polimórfico, indo desde\na descrição clássica (sinal de porta de entrada\nda infecção, febre, edema subcutâneo, aumento do\nvolume de linfonodos, hepatomegalia, esplenomegalia, além de evidências de miocardite e de\nmeningoencefalite), não sendo possível situações oligossintomáticas e inaparentes."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-239687","number":"239687","sourceNumber":"239687","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Os linfomas (Doença de Hodgkin e Linfomas não Hodgkin) constituem um grupo de\ndoenças neoplásicas malignas que se originam de\ncélulas do sistema imunológico. Somente está\nerrado o item:","options":{"A":"Linfoma Difuso de Grandes Células B (LDGC B) é o mais comum, correspondendo a cerca de\n40% dos novos casos diagnosticados e a cerca\nde 30% de todos os casos de LNH.","B":"Linfoma de Burkitt, o LDGC B é dos mais incidentes em indivíduos HIV positivos.","C":"Os Linfomas não Hodgkin (LNH) agressivos compreendem um grupo biológica e clinicamente\nhomogêneo de hemopatias malignas.","D":"O LDGC B pode-se manifestar nos linfonodos ou sítios extra-nodais, como osso, pele, tireoide,\ntrato gastrointestinal (TGI), sistema nervoso central\n(SNC) e testículo."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216863","number":"216863","sourceNumber":"216863","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As leucemias são as neoplasias mais comuns da infância, correspondendo a\naproximadamente 28% de todos os tipos de câncer na faixa etária pediátrica. Em relação às\nleucemias na infância, assinale a afirmativa CORRETA.","options":{"A":"As leucemias mieloides agudas são as mais comuns, correspondendo de 75 a 80% dos casos,\nseguidas pelas leucemias linfoides agudas, entre 15 a 20%.","B":"Estão entre os fatores prognósticos favoráveis da leucemia linfoide aguda: idade entre 1 a 9\nanos e leucometria abaixo de 50.000/mm³.","C":"Ao suspeitar ou diagnosticar uma leucemia, deve-se prontamente iniciar o corticoide sistêmico\nantes de encaminhar ao oncologista, como\nmaneira de melhorar o prognóstico.","D":"O transplante de medula óssea é o tratamento mais indicado para um paciente com leucemia\nlinfoide aguda."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221223","number":"221223","sourceNumber":"221223","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No Brasil, devido à efetividade do controle dos serviços de hemoterapia e,\nconsequentemente, maior qualidade do sangue\npara transfusão, tem-se alcançado significativo\nimpacto no controle da transmissão transfusional do T. cruzi. Marque o item ERRADO.","options":{"A":"Representa via sem importância de propagação da doença nos centros urbanos.","B":"É considerada a principal forma de transmissão em países não endêmicos como Canadá,\nEspanha, Estados Unidos e outros.","C":"É considerada a principal forma de transmissão em países latino-americanos que estejam em\nprocesso de controle da transmissão vetorial.","D":"Vertical ? ocorre, principalmente, pela via transplacentária e pode ocorrer em qualquer fase da\ndoença (aguda ou crônica)."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221226","number":"221226","sourceNumber":"221226","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A maioria dos indivíduos com infecção por T. cruzi alberga o parasito no sangue, nos\ntecidos e órgãos, durante toda a vida. Na fase aguda inicial, podemos aceitar todos os itens abaixo,\napenas um está incorreto, indique o INCORRETO.","options":{"A":"Predomina o parasito em número elevado circulante na corrente sanguínea.","B":"A manifestação mais característica é a febre constante, inicialmente elevada (38,5 a 39°C),\npodendo apresentar picos vespertinos ocasionais.","C":"As manifestações de síndrome febril podem persistir por até 12 meses.","D":"Esta fase aguda inicial, mesmo não tratada nem diagnosticada, pode evoluir com\ndesaparecimento espontâneo da febre e da maior parte das outras manifestações clínicas,\nevoluindo para a fase crônica."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221230","number":"221230","sourceNumber":"221230","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma das formas habituais de transmissão de T. cruzi para o homem, o vetor\n(triatomíneo), ao se alimentar em mamíferos\ninfectados com elevadas taxas de T. cruzi, pode se\ninfectar e, ao se alimentar novamente, infecta outro mamífero, inclusive o homem. Somente um\nitem se apresenta INCORRETO. Indique-o.","options":{"A":"Sinais de porta de entrada, característicos da transmissão vetorial, como o sinal de Romaña\n(edema bipalpebral unilateral por reação\ninflamatória à penetração do parasito, na conjuntiva e\nadjacências).","B":"Deve-se ressaltar que a picada de um triatomíneo pode causar reações alérgicas locais ou\nsistêmicas, sem que isso signifique, necessariamente, infecção por T. cruzi.","C":"No caso da doença de Chagas aguda (DCA) por transmissão oral, os surtos estudados parecem\nindicar diferenças na evolução clínica por esta forma de transmissão.","D":"Chagoma de inoculação (lesões furunculoides, supurativas, em membros, tronco e face, por\nreação inflamatória à penetração do parasito, que se mostram descamativas após duas ou três\nsemanas) são menos frequentes."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221238","number":"221238","sourceNumber":"221238","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No caso da doença de Chagas aguda (DCA) devido à transmissão oral, os estudos\nindicam diferenças na evolução clínica por esta\nforma de transmissão. Têm sido relatados:\nexantema cutâneo, hemorragia digestiva (hematêmese, hematoquezia ou melena), icterícia,\naumento das aminotransferases, além de quadros mais frequentes e mais graves de insuficiência\ncardíaca. Está ERRADO, apenas um item. Indique-o.","options":{"A":"Fenômenos de enterite, abdome agudo e sangramento fecal.","B":"Ressalta-se que a morbimortalidade é mais baixa na transmissão oral que a observada nos\ncasos agudos por transmissão vetorial.","C":"Choque, hepatite focal podem ocorrer e têm significação prognóstica variada, devendo ser\nrotineiramente pesquisados e monitorados.","D":"Quadros clínicos graves pode cursar com meningoencefalite, especialmente em lactente ou em\ncasos de reativação (pessoas com\ncomprometimento imunológico)."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221250","number":"221250","sourceNumber":"221250","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Forma cardíaca é a forma que ocorre em cerca de 30% dos casos crônicos e é\nconsiderada responsável pela maior frequência de óbitos na doença de Chagas crônica (DCC).\nEstá CORRETO, apenas, que","options":{"A":"não ocorrem evidências de acometimento cardíaco que, frequentemente, evolui para quadros de\nmiocardiopatia dilatada e insuficiência cardíaca congestiva (ICC).","B":"ocorrem evidências de acometimento cardíaco que, frequentemente, evolui para quadros de\nmiocardiopatia dilatada e insuficiência cardíaca congestiva (ICC).","C":"ocorrem evidências de acometimento cardíaco que, frequentemente, evolui para quadros de\nmiocardiopatia restritiva e insuficiência cardíaca congestiva (ICC).","D":"ocorrem evidências de acometimento cardíaco que, frequentemente, evolui para quadros de\nmiocardiopatia dilatada, mas nunca para insuficiência cardíaca congestiva (ICC)."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221254","number":"221254","sourceNumber":"221254","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Métodos parasitológicos diretos na fase aguda, sendo o exame parasitológico o mais\nindicado nesta fase. Somente sendo INCORRETO que","options":{"A":"é definido pela presença de parasitos circulantes.","B":"é definido pela presença de parasitos demonstráveis no exame direto do sangue periférico.","C":"a situação ideal é a realização da coleta com paciente febril e dentro de 30 dias do início de\nsintomas.","D":"incluem: pesquisa a fresco de tripanossomatídeos ? execução rápida e simples, sendo menos\nsensível que o esfregaço corado."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-221296","number":"221296","sourceNumber":"221296","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Considerando a morbidade e a mortalidade potencial, o diagnóstico e o manejo\napropriado da reativação da doença de Chagas no contexto de transplante de órgãos é\nextremamente importante. Está CORRETO que:","options":{"A":"A doença de Chagas constitui a primeira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento.","B":"A doença de Chagas constitui a terceira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento.","C":"A doença de Chagas constitui a terceira causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 95% dos pacientes submetidos ao procedimento.","D":"A doença de Chagas constitui raramente causa de indicação de transplante cardíaco no Brasil,\ncorrespondendo a 35% dos pacientes submetidos ao procedimento."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-177935","number":"177935","sourceNumber":"177935","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A translocação entre os braços longos dos cromossomos 9 e 22 caracteriza qual\nneoplasia hematológica?","options":{"A":"Leucemia linfocítica crônica.","B":"Tricoleucemia.","C":"Leucemia mieloide crônica.","D":"Mielofibrose primária.","E":"Mieloma múltiplo."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-183433","number":"183433","sourceNumber":"183433","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em pacientes com diagnóstico de LMA-M3, é CORRETO afirmar que:","options":{"A":"O início rápido de quimioterapia de indução de remissão melhora o prognóstico.","B":"O uso de ácido transretinoico previne graves eventos hemorrágicos na fase de indução.","C":"O uso de ácido transretinoico previne a síndrome de lise tumoral.","D":"Os eventos hemorrágicos estão relacionados exclusivamente à plaquetopenia.","E":"A hemoglobina deve ser mantida acima de 10 g/dl."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-183479","number":"183479","sourceNumber":"183479","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Quanto à epidemiologia do câncer na criança, assinale a alternativa correta.","options":{"A":"Dentre os tipos de leucemias, o mais prevalente na faixa pediátrica é a leucemia linfoide aguda.","B":"A doença de Hodgkin é mais prevalente que o linfoma não Hodgkin na faixa pediátrica.","C":"O adenocarcinoma renal, também conhecido como Tumor de Wilms, é o tumor renal mais\nfrequente na infância.","D":"O retinoblastoma é mais comum em crianças com mais de 5 anos de idade.","E":"Tumor de sistema nervoso central é raro na infância."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156292","number":"156292","sourceNumber":"156292","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 26 anos, relata queda de estado geral há 7 dias associada à febre aferida de\n(38-39°C). Notou que há 2 meses vem apresentando cansaço aos esforços e também o\naparecimento de \"hematomas na pele\", com episódios de gengivorragia. Ao exame físico\napresenta-se em mal estado geral, prostrada, e sonolenta. Está febril, hipocorada +3/+4, anictérica,\nsem adenopatia cervical, axilar ou inguinal. RCR 2T BNF sem sopros. Murmúrio vesicular presente\ne sem ruídos adventícios com frequência respiratória de 32 incursões por minuto. Abdome é flacido\nsem viceromegalias e membros inferiores apresentando algumas petéquias. Em adição à analise\ndo caso, considere ainda: (conforme imagem no caderno de questões). Para esse caso, assinale a\nalternativa com a conduta correta.","options":{"A":"Para confirmar o diagnóstico, deve se solicitar sorologia para leishmaniose visceral.","B":"Conduzir o caso como sepse, uma vez que o escore q SOFA é de 1.","C":"O aspirado de medula óssea é o exame necessário para confirmar o diagnóstico.","D":"Não está indicada a reposição de concentrado de plaquetas.","E":"Pelo quadro de neutropenia febril, está indicado o uso de cefepime."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-155695","number":"155695","sourceNumber":"155695","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"João Pedro, de 28 anos, portador de leucemia linfoblástica aguda, vai à emergência\nqueixando-se de febre e calafrios há 24\nhoras. Na carteira de identificação do tratamento,\ndemonstra que está fazendo o esquema CVAD ( ciclofosfamida, vincristina, doxorrubicina e\ndexametasona) hiper fracionada e que a última dose foi há oito dias. Nega tosse e dispneia,\ncefaleia, dor abdominal ou diarreia. Nega contato com doentes nem fez viagem recente. Ao exame,\nfebril, com 39,1°C, com frequência cardíaca de 118 bpm, pressão arterial de 120/80 mmHg e\nfrequência respiratória de 25 IRPM, possui aparência de doente; a pele está quente e úmida, mas\nsem exantema. Sem sinais de mucosite, ausculta pulmonar nada digno de nota, exame\ncardiológico: taquicárdico e possui ritmo regular, com sopro sistólico +2/6 na borda esternal\nesquerda, e o abdome inocente. A região perianal está normal e não realizou toque retal. Apresenta\ncateter inserido na veia jugular interna direita sem eritema sobre o trajeto subcutâneo e sem\nsecreção purulenta no local de saída do cateter. É interessante notar que ele relata o aparecimento\nde tremores com calafrios decorridos 30 minutos do congestionamento do cateter. Os exames\nlaboratoriais mostram hemoglobina de 10,8 g/100mL, hematócrito de 33%, leucócitos totais de\n\n1.100 células/mm3, com diferencial de 8% de neutrófilos, 6% de bastonetes, 6% de eosinófilos,\n66% de linfócitos e 14% de monócitos (a\ncontagem absoluta de neutrófilos é de 88/mm3) e 195000\nplaquetas. Função renal e marcadores hepáticos normais. PCR + raio X tórax: normal e evidencia\ncateter de longa permanência implantado na veia subclávia direita. A partir desse caso, responda à\npróxima questão. Assinale a alternativa CORRETA quanto ao diagnóstico provável para este\npaciente e o possível foco da infecção.","options":{"A":"Neutropenia febril, e o foco provável é o trato geniturinário.","B":"Neutropenia febril, e o foco provável é o pulmão com possível pneumonia.","C":"Neutropenia febril, e o foco provável é o cateter.","D":"Endocardite bacteriana, e o foco foi o cateter.","E":"Neutropenia febril, e o foco provável é desconhecido."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-152347","number":"152347","sourceNumber":"152347","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 10 anos de idade, pesando 32 quilos, soropositivo para HIV de\ntransmissão vertical, apresenta diagnóstico de linfoma abdominal não Hodgkin há 1 semana. Fez\nquimioterapia há 4 dias. Hoje está hipoativo, hipotenso, desidratado, em anasarca, descorado e\nreferindo dor lombar à direita de forte intensidade. Tem diurese de 8 ml/hora; ureia de 205;\ncreatinina de 4,8; potássio de 6,1; cálcio de 8,2; ácido úrico urinário de 0,75 mg/dl; e gasometria\ncom acidose metabólica. Acerca desse caso, qual é o diagnóstico MAIS provável?","options":{"A":"Cálculo impactado em ureter distal.","B":"Cálculo coraliforme em pelve renal direita.","C":"Desidratação secundária a vômitos pós-quimioterapia.","D":"Síndrome da lise tumoral aguda."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-137892","number":"137892","sourceNumber":"137892","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar masculino em quimioterapia, em unidade de oncologia pediátrica, evolui com\npiora clínica. Assinale a alternativa que apresenta as alterações que ratificam a suspeita de lise\ntumoral:","options":{"A":"Hiperuricemia, hipercalemia e hiperfosfatemia.","B":"Hiperuricemia, hipercalemia e hipofosfatemia.","C":"Hipouricemia, hipercalemia e hiperfosfatemia.","D":"Hipouricemia, hipocalemia e hiperfosfatemia.","E":"Hiperuricemia, hipocalemia e hipofosfatemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-130037","number":"130037","sourceNumber":"130037","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Das alterações nos exames laboratoriais abaixo qual NÃO está presente nas crianças\ncom Síndrome Nefrótica por lesões mínimas?","options":{"A":"Hipercolesterolemia.","B":"Hipoalbuminemia.","C":"Creatinina elevada.","D":"Hipocalcemia."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-132252","number":"132252","sourceNumber":"132252","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale qual das asserções abaixo é FALSA em relação a Lesão Renal Aguda (LRA):","options":{"A":"Na LRA obstrutiva (pós-renal), a resolução da obstrução leva sempre à recuperação da função\nrenal.","B":"Na LRA pré-renal, existe uma diminuição da filtração glomerular (FG) associada a: hipovolemia,\nvolemia efetiva (vasodilatação na sepse,\nInsuficiência Cardíaca, síndrome hepatorenal), ou\nalterações da hemodinâmica intra renal (antiinflamatórios não hormonais, bloqueadores de\n\nrenina-angiotensina, inibidores da enzima conversora de angiotensina).","C":"A causa mais comum de LRA parenquimatosa é a Necrose Tubular Aguda (NTA), causada pro\nisquemia renal e/ou nefrotoxicidade.","D":"A NTA pode causar diminuição permanente da função renal a longo prazo (Doença Renal\nCrônica)."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-111772","number":"111772","sourceNumber":"111772","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"É causa de insuficiência renal aguda pré-renal:","options":{"A":"Hiperplasia prostática.","B":"Neoplasia de colo uterino.","C":"Insuficiência cardíaca.","D":"Neoplasia de bexiga.","E":"Obstrução vascular renal bilateral."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-106830","number":"106830","sourceNumber":"106830","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a Insuficiência Renal Aguda (IRA) e suas causas em crianças, assinale a\nalternativa CORRETA:","options":{"A":"As causas pré-renais de IRA em crianças são as menos comuns.","B":"As causas pós-renais têm pico de incidência aos 5 anos de idade.","C":"A IRA pré-renal é rapidamente reversível, se melhorada a perfusão renal.","D":"O lúpus e a púrpura de Henoch-Schönlein são causas pós-renais de IRA.","E":"A IRA não oligúrica é incomum, raramente diagnosticada em crianças."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-83525","number":"83525","sourceNumber":"83525","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"J.S.X., 73 anos, HAS prévia, deu entrada na emergência do hospital com quadro de\nedema de membros inferiores, astenia,\nanorexia nos últimos 3 meses, evoluindo com tontura,\ndispneia, sensação de morte iminente há alguns minutos. Ao exame físico inicial, paciente\nencontra-se pálido ++/4+, desorientado, bradicárdico (FC: 50 bpm), MV diminuído em bases,\ntaquidispneia (FR: 35 irpm), abdome inocente e membros inferiores com edema ++/4+. Solicitados\nexames iniciais: Hb: 6,2; Ht 19; VCM: 89,2; HCM: 29,1; CHCM: 32,63; leucócitos: 6.100 (sem\n\ndesvio); plaquetas: 139.000; creatinina: 8,2 mg/dl; ureia: 264 mg/dl; sódio: 138 mEq/L; potássio:\n8,5\nmEq/L; glicemia: 82 mg/dl; HCO3: 11,2; ECG: (VER IMAGEM) A anemia do paciente está\nassociada a:","options":{"A":"Deficiência de ferro.","B":"Deficiência de vitamina B12.","C":"Doença crônica.","D":"Hemólise.","E":"Hemodiluição."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-83530","number":"83530","sourceNumber":"83530","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"JSX, 73 ANOS, HAS prévia, deu entrada na emergência do Hospital com quadro de\nedema de membros inferiores, astenia,\nanorexia nos últimos 3 meses, evoluindo com tontura,\ndispneia, sensação de morte iminente há alguns minutos. Ao exame físico inicial, paciente\nencontra-se pálido ++/4+, desorientado, bradicárdico (FC: 50 bpm), MV diminuído em bases,\ntaquidispneia (FR:35 irpm), abdômen inocente e membros inferiores com edema ++/4+. Solicitados\nexames iniciais: Hb: 6,2; Ht 19; VCM: 89,2; HCM: 29,1; CHCM: 32,63, Leucócitos: 6100 (sem\n\ndesvio), Plaqueta 139.000; creatinina 8,2 mg/dl; Ureia: 264 mg/dl; Sódio: 138 mEq/L; Potássio: 8,5\nmEq/L; Glicemia: 82 mg/dl HCO3: 11,2; ECG: (VER IMAGEM) Qual dos exames abaixo que, se\nsolicitado posteriormente deverá estar alterado:","options":{"A":"Gama GT aumentada.","B":"CK/CK-MB aumentada.","C":"Bilirrubinas totais e indiretas aumentadas.","D":"Dosagem de C3/C4 elevada.","E":"PTH aumentado."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-18/83530.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-60192","number":"60192","sourceNumber":"60192","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"\"Clearance\" renal de uma substância é:","options":{"A":"A quantidade dessa substância que é removida do plasma, a cada minuto, através dos rins.","B":"A massa dessa substância que é excretada através da urina nas 24 horas.","C":"A velocidade com que uma substância é eliminada na urina, a cada minuto.","D":"A porcentagem de plasma que se livra de uma substância, a cada minuto, através dos rins.","E":"O volume de plasma que se vê livre da massa de uma substância eliminada a cada minuto,\natravés da urina."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-64945","number":"64945","sourceNumber":"64945","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Senhor de 70 anos apresenta lombociatalgia de repetição limitante e faz uso de\nanti-inflamatório não hormonal de 4 a 5 vezes por semana. Há dois meses, foi diagnosticada\n\nHipertensão Arterial Sistêmica essencial, sendo prescrito enalapril (40 mg/dia), em uso regular. Há\ntrês dias, queixa-se de fraqueza progressiva, oligúria, e hoje, edema. Já no hospital, nega febre ou\nuso de outras medicações associadas. Ao exame físico, apresenta-se sonolento com Glasgow de\n13, sem sinais localizatórios, pulso em 90 bpm e PA de 155 x 110 mmHg. Notou-se discreto\n\"flapping\" de extremidades. A ausculta pulmonar revelou discretos estertores finos inspiratórios em\nambos hemitórax e edema de membros inferiores (2+/4+). Sem outras alterações no exame físico.\nAssinale a alternativa que apresenta quatro exames obrigatórios a serem solicitados de urgência.","options":{"A":"Potássio, urina tipo I, ultrassonografia renal e radiografia de tórax.","B":"Hemograma, creatinina, urina I e ultrassonografia renal.","C":"Creatinina, potássio, urina I e radiografia tórax.","D":"Potássio, ureia, creatinina e eletrocardiograma.","E":"Eletrocardiograma, radiografia de tórax, creatinina e ultrassonografia renal."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-45886","number":"45886","sourceNumber":"45886","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 40 anos, 72 kg, diabético, apresentando creatinina sérica: 3,0, está\nem avaliação cardiológica e necessita realizar um cineangiocoronariografia, devendo receber\ncontraste iodado. Nesta situação, pode-se afirmar:","options":{"A":"Não há risco de nefrotoxicidade, pois o paciente apresenta clearance estimado de creatinina\nmaior que 30 ml/min","B":"Hidratação com solução fisiológica 0,9% deverá ser prescrita e iniciada antes do exame para\nprevenção da nefrotoxicidade","C":"Este paciente deverá receber uma solução de hidratação hipotônica associada com dopamina, a\nfim de evitar nefrotoxicidade do contraste","D":"O exame está contraindicado neste paciente devido ao alto risco de nefrotoxicidade irreversível\npelo contraste","E":"Hidratação com solução hipertônica 3% constitui-se na melhor conduta na prevenção da\nnefrotoxicidade do contraste"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-45491","number":"45491","sourceNumber":"45491","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Vera tem 4 anos e comparece com o pai à consulta ambulatorial com história de febre\nbaixa intermitente há 2 semanas, anorexia, cansaço, dor em membros inferiores e articulações,\nsangramento nasal, cefaleia e vômitos. Ao exame, você verifica mucosas pálidas, sem alterações\nectoscópicas em membros inferiores ou articulações. O procedimento mais indicado para o\ndiagnóstico conclusivo de Vera é realizar:","options":{"A":"Provas de função reumática.","B":"Exame da medula óssea.","C":"Tomografia de crânio.","D":"Punção lombar.","E":"Cintilografia óssea."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-31827","number":"31827","sourceNumber":"31827","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher, 23 anos de idade, queixando-se de tosse seca há 2 meses, realizou TC de\ntórax evidenciando vários linfonodos em região\nmediastinal. Submetida à biópsia, essa revelou a\npresença de células de Reed-Sternberg. Baseado nesses dados, o provável diagnóstico e subtipo\nhistológico são, respectivamente:","options":{"A":"Linfoma não Hodgkin e linfocítico de pequenas células.","B":"Doença de Hodgkin e celularidade mista.","C":"Doença de Hodgkin e esclerose nodular.","D":"Linfoma não Hodgkin e tipo grandes células (Burkitt).","E":"Doença de Hodgkin e predominância linfocitária."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-34540","number":"34540","sourceNumber":"34540","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A etiologia da Lesão Renal Aguda (LRA) é diversa e pode ser devido a várias injúrias\nfisiológicas. Assinale a alternativa INCORRETA com relação às diferentes causas da insuficiência\nrenal aguda:","options":{"A":"A azotemia pré-renal é a causa mais comum de LRA e é responsável por cerca de 60 a 70% dos\ncasos adquiridos na comunidade e 40% dos\nadquiridos no hospital.","B":"A LRA intrínseca é classificada de acordo com o sítio histológico primário de lesão: túbulos,\ninterstício, vasculatura ou glomérulos.","C":"A lesão celular dos túbulos renais, comumente chamada de necrose tubular aguda, ocorre com\nmaior frequência quando há aumento do fluxo sanguíneo renal, embora os túbulos renais também\npossam ser danificados por toxinas renais específicas.","D":"A LRA secundária à lesão no interstício renal é chamada de nefrite intersticial aguda, sendo os\nmedicamentos comumente implicados: penicilinas, cefalosporinas e sulfonamidas.","E":"Em pacientes com lesão renal aguda pós-renal, a obstrução intraluminal pode ser vista em\npacientes com necrose papilar e coágulos de sangue, enquanto a obstrução extraluminal está\nassociada à fibrose retroperitoneal e aos linfomas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-25706","number":"25706","sourceNumber":"25706","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, sexo feminino, 60 anos, pesando 60 kg e com creatinina sérica de 5 mg/dl e\nureia sérica de 100 mg/dl. Calcule o clearance de creatinina pela equação de Cockroft-Gault:","options":{"A":"11.33","B":"13.33","C":"14.33","D":"15.33","E":"16.33"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-359401","number":"359401","sourceNumber":"359401","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 35 anos é levado ao Pronto-Socorro por causa de fraqueza generalizada,\ndificuldade para deambular, náuseas e vômitos. Possui seminoma testicular com acometimento\nlinfonodal secundário acentuado. Recebeu a primeira quimioterapia quatro dias antes. Ao exame\nfísico, apresenta as mucosas desidratadas e coradas. Está alerta e orientado. Apresentou\ncontratura do antebraço e da mão durante a aferição da pressão arterial nesse membro. Exames\nde laboratório: creatinina 1,8mg/dL; ureia 64mg/dL; sódio 136mEq/L; potássio 6,2mEq/L; fósforo\n5,3mg/dL; ácido úrico 12,4mg/dL; cálcio iônico 0,72mmol/L. Assinale a alternativa que apresenta\numa conduta inicial INADEQUADA:","options":{"A":"Correção da hipercalemia - beta-2 agonista e furosemida IV.","B":"Correção da hipocalcemia - gluconato de cálcio IV.","C":"Hidratação venosa vigorosa com solução de cloreto de sódio 0,9%.","D":"Prescrição de rasburicase ou alopurinol."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-263057","number":"263057","sourceNumber":"263057","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paulo, cinco anos de idade, com primo diagnóstico de leucemia linfoide aguda, iniciou\nfebre (39,2ºC) associada a queixa de dor\nabdominal, cerca de 15 dias após fase de indução de\nquimioterapia. Ao exame físico, apresenta-se em bom estado geral, hidratado, hipocorado leve,\npulsos cheios. FC:92bpm, PA: 98x70mmHg, FR:22irpm, sem esforço, sons pulmonares fisiológicos,\nsem lesões de pele. Exames laboratoriais: Hb: 8g/dL; Htc:24%; Plaquetas: 70.000/mm³; Leucócitos\nglobal: 280/mm³ (segmentados: 80/mm³; eosinófilos: 50/mm³; monócitos:50/mm³;\nlinfócitos:100/mm³); Proteína C Reativa:200mg/L; Hemocultura em andamento. De acordo com este\ncaso clínico, assinale a alternativa que apresenta a antibioticoterapia de escolha para o tratamento\nempírico:","options":{"A":"Ampicilina e amicacina","B":"Cefepime","C":"Cefepime e vancomicina","D":"Ciprofloxacino"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-233790","number":"233790","sourceNumber":"233790","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança de sete anos de idade foi admitida na UPA com relato de quadro de prostração,\nhiporexia, cansaço e dor em membros inferiores de início há duas semanas. Ao exame físico:\ncriança afebril, hipocorada e hidratada. Oroscopia e otoscopia sem alterações; FR = 28 irpm, sem\nsinais de esforço respiratório, SatO? = 96% em ar ambiente; FC = 110 bpm, pulsos periféricos\ncheios, perfusão imediata; abdome indolor sem visceromegalias. Resultado do hemograma:\nhemácias = 2,43 milhões/mm³ (VR: 4,0?5,2 milhões/mm³); hemoglobina: 8,5 g/dl (VR: 11,5?15,5\ng/dl); hematócrito = 25% (VR: 35?45%); global de leucócitos = 124.180/mm³ (VR:\n4.500?13.500/mm³); diferencial = 2% neutrófilos; 10% linfócitos; 88% blastos. Plaquetas =\n32.000/mm³ (VR: 150.000 a 450.000/mm³). Assinale a conduta imediata MAIS ADEQUADA:","options":{"A":"Iniciar ceftriaxona e oxacilina.","B":"Iniciar hiperidratação venosa.","C":"Realizar transfusão de hemácias.","D":"Realizar transfusão de plaquetas."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-174697","number":"174697","sourceNumber":"174697","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No que diz respeito ao linfoma de Hodgkin, assinale a alternativa ERRADA:","options":{"A":"A afecção, cuja incidência atinge o pico por volta dos 30 anos, inicia-se mais frequentemente\nnos linfonodos cervicais, progredindo por\ncontiguidade.","B":"Do ponto de vista histopatológico, o linfoma de Hodgkin clássico, tipo celularidade mista,\ncaracteriza-se por aspecto celular heterogêneo e, particularmente, pela ausência de eosinófilos.","C":"Em jovens com linfoma de Hodgkin clássico, tipo esclerose nodular, é frequente o acometimento\ndo mediastino.","D":"Nas células de Hodgkin e nas células de Reed-Sternberg, é frequente a expressão\nimuno-histoquímica de uma proteína do vírus Epstein-Barr."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-149881","number":"149881","sourceNumber":"149881","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de cinco anos de idade há sete dias apresenta quadro de linfadenomegalia\ngeneralizada, hepatomegalia e febre baixa. Qual dos\nachados clínicos abaixo NÃO é considerado\nsinais de alertas para doença maligna?","options":{"A":"Emagrecimento e palidez cutâneo-mucosa.","B":"Linfadenomegalia com sinais inflamatórios.","C":"Linfonodos aderentes aos planos profundo ou superficial.","D":"Linfonodos com consistência aumentada."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-127521","number":"127521","sourceNumber":"127521","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 65 anos, hipertenso, é admitido em caráter de urgência em pronto-socorro\ncom síndrome de veia cava superior associada ao\nlinfoma do tipo grandes células. Foi iniciado\ntratamento com corticosteroides seguido de quimioterapia. Além da elevação do ácido úrico sérico,\nqual conjunto de alterações abaixo pode advir do tratamento do tumor, até sete dias após seu\ninício?","options":{"A":"Hipercalemia, hiperfosfatemia, hipocalcemia.","B":"Hipocalemia, hiperfosfatemia, hipocalcemia.","C":"Hipercalemia, hipofosfatemia, hipercalcemia.","D":"Hipocalemia, hipofosfatemia, hipercalcemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-101861","number":"101861","sourceNumber":"101861","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 47 anos apresenta-se para exame admissional, sem passado mórbido de\nimportância. Ao exame físico, seu baço foi palpado a cerca de 4 cm abaixo do rebordo costal\nesquerdo, sem outras alterações. Trouxe consigo um hemograma recente com alterações muito\nsugestivas de leucemia mieloide crônica. Assinale a alternativa com as alterações no hemograma\nMAIS prováveis para esse diagnóstico:","options":{"A":"Leucocitose, eosinopenia, linfopenia, presença de eritroblastos e de plaquetas gigantes.","B":"Leucocitose, trombocitose, basofilia e presença de todos os tipos celulares da linhagem\nneutrofílica, sem atipias.","C":"Leucopenia, anemia, trombocitopenia e presença de neutrófilos hipersegmentados.","D":"Leucopenia, linfopenia, anemia e presença de mieloblastos."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78430","number":"78430","sourceNumber":"78430","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 54 anos apresenta-se com desconforto abdominal de início há dois meses.\nAo exame físico, os níveis pressóricos\narteriais estão elevados (PA = 160 x 100 mmHg) e palpa-se\nmassa em flanco direito. Traz consigo ultrassonografia abdominal que evidencia cinco cistos\nvolumosos no rim direito e quatro cistos menores no rim esquerdo. Em relação às outras\nmanifestações clínicas dessa afecção, podemos afirmar, EXCETO:","options":{"A":"Hematúria macroscópica está relacionada à ruptura de cisto ou à presença de cálculos de\noxalato de cálcio ou ácido úrico no trato urinário.","B":"Pielonefrites podem cursar com hemoculturas positivas e uroculturas negativas, já que os cistos\npodem não se comunicar diretamente com o sistema coletor.","C":"Poliúria e noctúria, geralmente, são sintomas precoces e resultam da redução da capacidade de\nconcentração urinária.","D":"Valvulopatias podem estar presentes e acometem, mais comumente, o lado direito do coração."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-60307","number":"60307","sourceNumber":"60307","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança do sexo masculino, 7 anos de idade, diagnóstico de leucemia linfoide aguda,\nrecebeu quimioterapia há 10 dias. É atendida na\nunidade de pronto atendimento com queixa de\nfebre (38,5°C) há 3 horas que cedeu ao uso de dipirona. O exame físico não evidenciou\nanormalidades. O hemograma mostrou leucometria de 1.200 céls/mm³ (10% neutrófilos e 85% de\nlinfócitos). Assinale a alternativa que indica CORRETAMENTE a conduta inicial nesse quadro:","options":{"A":"Antibioticoterapia oral com cobertura para Gram-positivos, em ambiente domiciliar.","B":"Internação e antibioticoterapia de amplo espectro com cobertura para Gram-negativos.","C":"Observação domiciliar da curva térmica, uma vez que a criança não apresenta qualquer\nalteração ao exame físico.","D":"Observação hospitalar da curva térmica, uma vez que a criança não apresenta qualquer\nalteração ao exame físico."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-71489","number":"71489","sourceNumber":"71489","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 24 anos é encaminhada ao nefrologista por causa de proteinúria 1+ e\nhematúria 1+ na urinálise tipo 1, com fita reagente. Seu exame físico é irrelevante, exceto por\npressão arterial de 138/88 mmHg. A relação proteína/creatinina em amostra de urina matinal é de\n0,6. As seguintes alternativas estão corretas, EXCETO:","options":{"A":"Proteinúria 1+ detectada por fita reagente indica risco de doença renal progressiva.","B":"Proteinúria detectada na relação proteína/creatinina em urina colhida aleatoriamente indica\ndoença renal progressiva.","C":"Presença de hematúria por fita reagente não invalida o uso de amostra aleatória de urina para\nquantificar proteinúria.","D":"Hematúria de origem glomerular é fator de risco para doença renal progressiva, tão significativo\nquanto proteinúria 1+ avaliada por fita reagente."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-60402","number":"60402","sourceNumber":"60402","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Adolescente do sexo masculino, 14 anos, residente em área rural, diabético, é\nencaminhado ao pronto atendimento pela\nmédica que o atendeu no posto de saúde. Ele notou, há\ncerca de 3 dias, que os pés e os olhos estavam ''inchados'' e que a urina estava mais escura e com\nvolume reduzido. Nas últimas horas, passou a apresentar também muito cansaço, náuseas e\nalguns episódios de vômitos. História de amigdalite há aproximadamente 20 dias. Segundo relatório\nmédico, recebeu uma ampola de furosemida por via endovenosa, sem resposta. Ao exame clínico,\nencontra-se um pouco agitado e taquipneico; havia edema generalizado ++/4+; o hálito era\nincaracterístico; as extremidades estavam bem perfundidas e havia crepitações teleinspiratórias no\nterço inferior do tórax bilateralmente; a PA era 130 x 85 mmHg e a FC, 100 bpm. Exames\nlaboratoriais: hemoglobina = 10,9 g/dl; glicemia = 224 mg/dl; creatinina = 6,9 mg/dl; ureia = 118\nmg/dl; pH = 7,25; HCO3- = 12 mEq/L; Na+ = 127 mEq/L; K+ = 7,8 mEq/L. Urina: fita reagente\nmostrando positividade +++/4+ para sangue e ++/4+ para proteína e glicose, sedimentoscopia com\nraros leucócitos e campos repletos de eritrócitos. Fração de excreção de Na+ = 5%. A intervenção\nimediata MAIS apropriada é:","options":{"A":"Diálise para correção da hipervolemia e da hiperpotassemia.","B":"Insulina regular para controle da glicemia e redução da hiperpotassemia.","C":"Micronebulização com agonista beta-1 para redução da hiperpotassemia.","D":"NaHCO3 para correção da acidose metabólica e redução da hiperpotassemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-53317","number":"53317","sourceNumber":"53317","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 45 anos, portador de leucemia linfoide aguda em tratamento\nquimioterápico, procura o pronto atendimento\ncom quadro de febre de 39°C, tremores e prostração.\nHemograma realizado no dia anterior mostrava contagem de leucócitos de 200/mm³, contagem de\nplaquetas de 23.000/mm³ e hemoglobina de 9,1 g/dl. Em relação ao caso clínico apresentado,\ntodas as afirmações são corretas, EXCETO:","options":{"A":"A presença concomitante de plaquetopenia e anemia indica quadro de aplasia irreversível de\nmedula óssea.","B":"Contagem de leucócitos abaixo de 500/mm³ predispõe a infecções bacterianas e fúngicas.","C":"Se a neutropenia desse paciente tiver duração superior a 2 semanas, o risco de infecção fúngica\naumenta significativamente.","D":"Sinais e sintomas de infecção podem, muitas vezes, estar ausentes em neutropênicos graves."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-53334","number":"53334","sourceNumber":"53334","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, cinco anos de idade, com leucemia mieloide aguda, candidato a transplante\nde medula óssea, é admitido no hospital com\nquadro de febre (temperatura axilar: 39ºC). Exame\nfísico: presença de petéquias em tronco e membros superiores. Hipocorado e taquicárdico.\n\nApresentando hipotensão arterial. História prévia de reação transfusional febril. Hemograma:\nhemoglobina = 6 g/dl; plaquetas = 12.000/mm³; leucócitos = 700/mm³ (segmentados = 8%;\nlinfócitos = 80%; monócitos = 2%). Qual das condutas abaixo deve ser evitada neste paciente?","options":{"A":"A adição de vancomicina ao esquema inicial de tratamento deve ser considerada, pois o\npaciente apresenta sinais de instabilidade hemodinâmica.","B":"Administração imediata de antibióticos de largo espectro, mesmo que a avaliação inicial não\nrevele a etiologia do processo infeccioso.","C":"Aguardar o resultado de culturas ou localização de foco infeccioso para iniciar\nantibioticoterapia.","D":"Deve ser utilizado, obrigatoriamente, um esquema de antibióticos com boa cobertura para\nbactérias Gram-negativas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-22841","number":"22841","sourceNumber":"22841","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Aproximadamente 3 dias após esforço inusitado, homem diabético, de 56 anos, buscou\nassistência médica queixando-se de fortes dores musculares no dorso e nos membros inferiores\nque praticamente o impediam de deambular sem ajuda e que não cederam após uso de\n\nanti-inflamatórios não hormonais. Nas últimas horas, passou a apresentar também urina mais\nescura, dispneia, náuseas e alguns episódios de\nvômitos. Ao exame clínico, o paciente mostrava-se\num pouco agitado, taquipneico, tinha os dados vitais dentro dos valores normais, perfundia bem as\nextremidades e apresentava crepitações teleinspiratórias no terço inferior de ambos os hemitórax. A\npalpação dos músculos do dorso e dos membros inferiores era muito dolorosa. Exames\nlaboratoriais: hemoglobina = 11,5 mg/dl, glicemia = 204 mg/dl, creatinina = 16 mg/dl, ureia = 180\nmg/dl, pH = 7,25, HCO3 = 12 mEq/L, Na+ = 128 mEq/L e K+ = 8,3 mEq/L. O plasma estava turvo e\navermelhado, mas, após centrifugação, mostrou-se amarelado pálido. O exame da urina, pela fita\nreagente, evidenciou presença de sangue (+++/4) e glicose (++/4) e a sedimentoscopia mostrou\nraros leucócitos e eritrócitos. A fração de excreção de sódio foi de 5%. A intervenção imediata mais\napropriada é:","options":{"A":"Administração de NaHCO3, por via intravenosa, para correção da acidose metabólica.","B":"Diálise para correção da hipervolemia e da hiperpotassemia.","C":"Administração, por via intravenosa, de solução salina hipertônica para correção da hiponatremia.","D":"Administração rápida de volume e insulina regular contínua para controle da cetoacidose\ndiabética."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-361751","number":"361751","sourceNumber":"361751","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Você atende no pronto-socorro um idoso masculino de 63 anos com queixa de fadiga,\nmal-estar, perda ponderal, hiporexia, febre baixa e desconforto abdominal com saciedade precoce\nhá 6 meses. É previamente hipertenso e diabético, com bom controle das comorbidades.\n\nSolicitados exames laboratoriais, que evidenciam leucometria de 60.000 células/mm3, hemoglobina\n9,2 g/dL, plaquetometria 83.000 células/mm3,\ndemais exames laboratoriais sem alterações\nsignificativas. Exame físico evidencia regular estado geral, descorado 2+/4, desidratado +/4,\nacianótico, anictérico, temperatura 37,8°C. Abdome globoso, levemente doloroso em hemiabdome\nesquerdo, com baço palpável abaixo do rebordo costal esquerdo. Pensando-se em leucemia\nmieloide crônica, assinale a alternativa correta.","options":{"A":"A pesquisa da translocação t(9;22) por análise citongenética, ou por FISH, ou a pesquisa da\nproteína BCR-ABL por PCR é essencial para confirmação diagnóstica.","B":"A doença é causada por uma alteração somática na célula-tronco hematopoiética. Dentre os\nmarcadores de gravidade, destacam-se diagnóstico em faixas etárias mais avançadas e\nhipoviscosidade do sangue.","C":"Sintomas de leucostase, como dispneia, confusão mental e alteração do nível de consciência\nsão frequentes na fase crônica.","D":"Apesar de o principal achado ser esplenomegalia, ela não tem relação com a leucometria.\n\nEnvolvimento extramedular, como linfonodos e pele, são comuns na fase crônica."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-346248","number":"346248","sourceNumber":"346248","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar, três anos e cinco meses, sexo feminino, vem apresentando dores ósseas\ndifusas iniciadas há três meses, que não\nmelhoram com o uso de analgésicos comuns, associados\nà febre baixa intermitente, cefaleia, vômitos frequentes, anorexia, perda ponderal de quatro quilos\ne\nirritação com prejuízo de sono. A partir do resultado do hemograma, foi diagnosticado \"anemia\ndiscreta? tendo sido prescrito sulfato ferroso por seis meses. Há um mês, a mãe notou palidez que\nvem se acentuando. Exame físico: irritabilidade, fáceis de sofrimento, dificuldade para deambular\npela dor, hipocorada +/4+, adenomegalias cervicais, axilares e inguinais móveis, fibroelásticas, não\ncoalescentes, medindo de 0,5 a 1 cm de diâmetro, fígado palpável a 5 cm, do rebordo costal direito,\nbaço a 4 cm do rebordo costal esquerdo, petéquias em membros inferiores e sopro sistólico +/4+\npancardíaco, sem irradiação. A principal hipótese diagnóstica é:","options":{"A":"Neuroblastoma.","B":"Febre reumática.","C":"Leucemia linfoide aguda.","D":"Artrite idiopática juvenil.","E":"A principal hipótese diagnóstica se mantém de anemia ferropriva que já está sendo tratada."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-259392","number":"259392","sourceNumber":"259392","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 25 anos, sabidamente portador de Leucemia linfoblástica Aguda, em atual\nmanejo sistêmico de tratamento com uso de quimioterápicos. Informa última sessão realizada há\ncerca de sete dias. Admitido para avaliação com relato de câimbras em membros inferiores,\nnáuseas, vômitos e diarreia de início recente. Nega febre, manifestações dermatológicas ou outras\nmanifestações sistêmicas. Exames laboratoriais: creatinina: 3,7 mg/dL, ureia 200mg/dL, Sódio:\n155meq/L, Potassio: 6,0meq/L, cloretos: 125meq/L, leucócitos totais: 100.000 cels /mm3 (90%\nblastos 5% neutrófilos, 3% macrófagos) plaquetas: 100.000 mm3 Hb:9,0g/dL Ht:28% fósforo: 7\nmg/L (VR: até 4,8mg/dL) cálcio iônico: 1,0 mg/dL (valor de referência: (até 1,2mg/dL) ácido úrico:\n12\nmg/dL TGO:45 Ui/L TGP:50 Ui/L FA:200 Ui/L GGT: 280 Ui/L HCO3 ( venoso): 18meq/L. Diante da\nmelhor hipótese diagnóstica assinale a conduta clínica inicial mais apropriada:","options":{"A":"Monitoramento contínuo, hidratação venosa, correção dos distúrbios hidroeletrolíticos, uso de\nrasburicase.","B":"Monitoramento contínuo, hidratação venosa e alcalinização urinária.","C":"Monitoramento contínuo e início imediato de terapia renal substitutiva.","D":"Monitoramento contínuo, coleta de culturas e início de protocolo para sepse em\nimunossuprimido."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-278851","number":"278851","sourceNumber":"278851","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Das alternativas apresentadas abaixo, assinale a correta considerando-se o diagnóstico\nde neutropenia febril.","options":{"A":"Tem a mesma conotação para os pacientes em tratamento oncológico e para os pacientes\nportadores de aplasia medular medicamentosa.","B":"Precisa ser tratada o mais precocemente possível para reduzir a morbidade e a mortalidade dos\npacientes em tratamento quimioterápico.","C":"Deve ser considerada também para pacientes febris que estão fora de tratamento\nantineoplásico.","D":"É considerada um diagnóstico de exclusão, motivo pelo qual deve-se buscar exaustivamente a\ncausa da febre antes de instituir o tratamento."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-287633","number":"287633","sourceNumber":"287633","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 7 anos de idade, assintomático, realizou ecografia de abdome de rotina\nque evidenciou formação cística em loja\nesplênica, de aproximadamente 09 centímetros. Para\nelucidação diagnóstica, realizou também ressonância magnética que confirmou a hipótese de cisto\nesplênico marginal, sem comprometimento do hilo esplênico. Tem hemograma normal, e sorologias\nparasitárias negativas. A conduta mais adequada neste caso é:","options":{"A":"Esplenectomia total.","B":"Esplenectomia parcial.","C":"Antibioticoterapia sistêmica.","D":"Seguimento anual com ultrassom."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-262963","number":"262963","sourceNumber":"262963","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A respeito das abordagens cirúrgicas do baço, assinale a alternativa incorreta.","options":{"A":"No paciente com púrpura trombocitopênica idiopática, a esplenectomia está indicada somente\nem caso de falha na terapêutica clínica.","B":"A profilaxia contra sepse pós-esplenectomia com vacinação é mais eficaz se realizada duas\nsemanas antes da abordagem cirúrgica que se\nrealizada no pós-operatório.","C":"Neoplasias malignas do baço devem sempre ser tratadas com esplenectomia total.","D":"Abscessos esplênicos requerem esplenectomia total e antibioticoterapia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-266652","number":"266652","sourceNumber":"266652","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Leucemia é o câncer que tem origem na medula óssea, onde são produzidas as células\ndo sangue. Sobre a leucemia, assinale a\nalternativa INCORRETA:","options":{"A":"A leucemia mieloide crônica representa 75% dos casos na faixa etária pediátrica e com pico\nentre 2 e 5 anos.","B":"A anemia costuma ser mais intensa nos casos de LMA, inclusive já manifestam com insuficiência\ncardíaca ao diagnóstico.","C":"A confirmação do diagnóstico ocorre pelo mielograma, pela presença de mais de 20-30% de\nblastos de morfologia homogênea.","D":"O transplante de medula, com doador HLA compatível, é o tratamento de escolha na leucemia\nmieloide aguda após a indução de remissão inicial."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-239819","number":"239819","sourceNumber":"239819","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 62 anos, sexo masculino, admitido na enfermaria para investigação\ndiagnóstica. Relata perda de peso involuntária de\ncerca de 18 kg nos últimos 5 meses, sensação\nde saciedade precoce, hiporexia, fadiga, astenia e febre. Ao exame abdominal percebe-se\nesplenomegalia (baço Boyd III). Exames laboratoriais: Hb: 10,5 g/dl (VR: 11.3 a 16.3); VCM: 80 fl\n(VR: 77 a 92); HCM: 28 pg (VR: 27 a 32); CHCM: 32 g/dl; RDW: 22; Global de leucócitos:\n\n590.000/mm3 (VR: 1800 a 7500); Segmentados: 34%; Bastonetes: 24%; Metamielócitos: 13%;\n\nMielócitos: 9%; Promielócitos: 5%; Blastos: 3%; Eosinófilos: 4% Basófilos: 5% Linfócitos: 2%\nMonócitos: 1%; Plaquetas: 400.000/ml (VR:\n130.000 a 370.000/ml). Diante do caso acima, assinale\no diagnóstico mais provável:","options":{"A":"Leucemia mielóide crônica.","B":"Trombocitemia essencial.","C":"Abscesso esplênico.","D":"Leucemia linfocítica crônica."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-253932","number":"253932","sourceNumber":"253932","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Marque o câncer mais comum na infância.","options":{"A":"Neuroblastoma","B":"Retinoblastoma","C":"Leucemia","D":"Linfoma"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-238655","number":"238655","sourceNumber":"238655","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Considere o caso clínico a seguir. Paciente, 3 anos de idade, apresenta-se com quadro\nde febre intermitente há um mês, associado a\ndor em membros inferiores. Hemograma revela\nleucopenia com neutropenia importante e também plaquetopenia leve. Sobre esse caso, assinale a\nalternativa CORRETA.","options":{"A":"O paciente deve ser encaminhado ao reumatologista por provável diagnóstico de artrite\nidiopática juvenil.","B":"O corticoide deve ser iniciado imediatamente, independentemente do diagnóstico do paciente.","C":"Um exame indicado para esse paciente é o mielograma para avaliar presença de blastos.","D":"A idade do paciente deixa improvável algum diagnóstico reumatológico ou oncológico."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-238660","number":"238660","sourceNumber":"238660","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Considere um paciente de 3 anos de idade com quadro de febre de 39ºC há sete dias,\npalidez importante, regular estado geral, hepatoesplenomegalia. Realizado hemograma: Hb: 6,9\ng/dL, Ht 21%, leucócitos globais: 800/mm³; segmentados: 40%, linfócitos: 50%, monócitos: 10%,\nplaquetas: 120 000/mm³. A esse respeito, assinale a alternativa correta.","options":{"A":"O início de antibiótico de amplo espectro está indicado nessa situação, mesmo sem o paciente\nter um diagnóstico etiológico definitivo.","B":"O agente etiológico mais provável é viral, a conduta mais correta é hidratação oral domiciliar,\njá\nque o paciente não se apresenta hemoconcentrado.","C":"O uso de antibiótico é obrigatório nessa situação, visto que o paciente tem uma infecção\nbacteriana.","D":"Esse paciente corre risco iminente de sangramento pela plaquetopenia e está indicada\ntransfusão de hemácias e plaquetas."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-244552","number":"244552","sourceNumber":"244552","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O quadro clínico decorrente da fase aguda da doença de Chagas por transmissão oral\ntem o seguinte item descrevendo corretamente:","options":{"A":"A principal diferença clínica entre as descrições de área endêmica do passado e a transmissão\npor via oral é que esta ocorre\npredominantemente na Região Amazônica, tem apresentação clínica\nde elevada morbidade, ressaltando a característica epidemiológica regional, no que se refere à\nocorrência da transmissão, muito mais eficaz que a via vetorial.","B":"A principal diferença clínica entre as descrições de área endêmica do passado e a transmissão\npor via oral é que esta ocorre\npredominantemente na Região Amazônica, tem apresentação clínica\nde baixa morbidade, ressaltando a característica epidemiológica regional, no que se refere à\nocorrência da transmissão, muito mais eficaz que a via vetorial.","C":"A principal diferença clínica entre as descrições de área endêmica do passado e a transmissão\npor via oral é que esta ocorre\npredominantemente na Região Amazônica, tem apresentação clínica\nde elevada morbidade, ressaltando a característica epidemiológica regional, no que se refere à\nocorrência da transmissão, muito menos eficaz que a via vetorial.","D":"A principal diferença clínica entre as descrições de área endêmica do passado e a transmissão\npor via oral é que esta ocorre\npredominantemente na Região Amazônica, tem apresentação clínica\nde elevada morbidade, ressaltando a característica epidemiológica regional, no que se refere à\nocorrência da transmissão, igualmente eficaz como a via vetorial."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-219416","number":"219416","sourceNumber":"219416","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 32 anos iniciou quimioterapia para tratamento de leucemia linfoblástica aguda.\nApós dois dias da primeira dose foi\nadmitido no hospital por mal-estar seguido por convulsão. Qual\no achado bioquímico mais consistente com o diagnóstico?","options":{"A":"Hipercalcemia","B":"Hiperuricemia","C":"Hipocalemia","D":"Hipomagnesemia"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-200483","number":"200483","sourceNumber":"200483","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 5 anos de idade, em tratamento de leucemia, comparece ao Pronto\nAtendimento (PA) com febre, início há 24h. A mãe relata que a criança fez quimioterapia há duas\nsemanas. A criança é triada e levada imediatamente a sala de emergência. O exame físico revela\ntaquicardia, FC= 170 bpm, perfusão capilar de 4\", prostração intensa, extremidades frias, pulsos\nfinos e hipotensão arterial. Em relação ao quadro clínico descrito acima, assinale a afirmativa\nCORRETA:","options":{"A":"Deve prescrever antibióticos e orientar iniciar após coleta de culturas, mesmo que essa coleta\ndemore.","B":"Punção de dois acessos venosos periféricos calibrosos facilitam as intervenções nesse caso.","C":"Deve solicitar hemograma, proteína C reativa, aguardar resultados para definir conduta.","D":"Hipotensão é obrigatório para o diagnóstico desse quadro na criança."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-217190","number":"217190","sourceNumber":"217190","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A respeito do linfoma de Hodgkin, é CORRETO afirmar:","options":{"A":"Ocorre mais frequentemente em crianças abaixo de 15 anos, idosos entre 50 e 60 anos, e\nmulheres.","B":"Apenas uma minoria pode ser curada com o tratamento disponível hoje.","C":"A doença se espalha desordenadamente, acometendo aleatoriamente grupos de linfonodos.","D":"Pessoas com imunossupressão (HIV, uso de imunossupressores para rejeição) têm mais risco\nde desenvolver a doença."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-184575","number":"184575","sourceNumber":"184575","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 32 anos iniciou tratamento quimioterápico para leucemia linfoblástica aguda.\nDois dias após o termino da QT, foi admitida no hospital com queixa de mal estar seguida de\nconvulsão. Qual a alteração bioquímica isolada que NÃO é consistente com o diagnóstico?","options":{"A":"Hipercalcemia.","B":"Hiperuricemia.","C":"Hipercalemia.","D":"Hipermagnesemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-184616","number":"184616","sourceNumber":"184616","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Mulher de 62 anos terminou há 8 dias seu primeiro ciclo de quimioterapia adjuvante\npara câncer de mama. Apresentando febre há 3\nhoras. Queixa-se também astenia, sem nenhum\noutro sintoma localizado. T 38,4 FC:110bpm PA:95/65mmHg. Sangue e urina enviadas para\ncultura. Qual o próximo passo?","options":{"A":"Libera-la para casa e comunicar se houver crescimento nas culturas","B":"Libera-la para casa com antibiótico oral","C":"Observação 24 horas com fluidos EV","D":"Iniciar antibiótico de largo espectro"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-179218","number":"179218","sourceNumber":"179218","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São consequências características da síndrome de Lise Tumoral, EXCETO:","options":{"A":"Hiperuricemia.","B":"Hipercalemia.","C":"Hipercalcemia.","D":"Hiperfosfatemia."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-181350","number":"181350","sourceNumber":"181350","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Analise as afirmativas a seguir sobre leucemias, linfomas e tumores da infância,\nassinalando com V as verdadeiras e com F as\nfalsas. ( ) O diagnóstico diferencial das leucemias\nquando só existe pancitopenia deve ser feito com anemia aplásica e mielofibrose; ( ) Um valioso\nmarcador tumoral nos casos de hepatoblastoma da infância é o antígeno carcinoembrionário (CEA)\nque pode ser utilizado para diagnóstico e monitoramento dos tumores; ( ) Nos casos de linfoma de\nHodgkin, com o uso de regimes terapêuticos atuais, pacientes com fatores prognósticos e doença\nem estágio inicial apresentam uma sobrevida global maior do que 95% em 5 anos; ( ) O tumor de\nWilms em estágio IV caracteriza-se por tumor em ambos os rins. Assinale a sequência CORRETA.","options":{"A":"V F V F","B":"F V F V","C":"V F F V","D":"V V F F"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-179116","number":"179116","sourceNumber":"179116","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, sexo masculino, 40 anos, empresário, procura assistência médica por queixas\nde astenia, adinamia e epistaxe, além de\nequimoses após pequenos traumas nos últimos 3 meses,\nsendo observado quadro febril na última semana. Ao exame físico, observamos mucosas\nhipocoradas (+2/4), fígado palpável (hepatimetria de 15 cm) e um baço palpável (4 cm do rebordo\ncostal esquerdo). Na mucosa oral percebe-se uma discreta hipertrofia na mucosa gengival. Foi\nrealizado um hemograma que revelou: hemoglobina = 8 g/dl, plaquetas = 50.000/mm³ e leucócitos\n\n= 20.000/mm³ com identificação de 10% de blastos em sangue periférico. Prosseguindo a\ninvestigação, realizou-se um mielograma que evidenciou a presença de 30% de blastos. Sobre o\ndiagnóstico do paciente acima é CORRETO afirmar:","options":{"A":"Na citogenética das células neoplásicas, a presença da translocação (8;21) reforça o diagnóstico\nde leucemia linfoide do subtipo L2.","B":"A presença da hiperplasia gengival encontrada no paciente reforça o diagnóstico das leucemias\nde linhagem linfoides agudas.","C":"Na morfologia dos blastos a presença no citoplasma de filamentos eosinofílicos ? os bastonetes\nde Auer ? definem a linhagem mieloide.","D":"Na imunofenotipagem, a positividade para CD 10, 19 e 20 definem a linhagem mieloide."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-184643","number":"184643","sourceNumber":"184643","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia representa um grupo de neoplasias malignas derivadas das células\nhematopoiéticas. Esta doença inicia sempre na\nmedula-óssea, local onde as células sanguíneas\nsão produzidas, e posteriormente invadem o sangue periférico, podendo atingir vários órgãos do\npaciente afetado. A leucemia é a doença maligna mais comum na infância, correspondendo\naproximadamente a 30% dos casos de câncer em crianças. Um tipo de Leucemia representa cerca\nde 85% dos casos de leucemias em crianças, sendo a faixa etária de maior frequência entre 2 e 5\nanos. Trata-se da:","options":{"A":"Leucemia Linfocítica Aguda (LLA).","B":"Leucemia Mielocítica Aguda (LMA).","C":"Leucemia Linfocítica Crônica (LLC).","D":"Leucemia Mielocítica Crônica (LMC)."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-182002","number":"182002","sourceNumber":"182002","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual a causa mais frequente de linfoadenomegalia na infância?","options":{"A":"Hiperplasia policlonal reacional.","B":"Tuberculose.","C":"Linfoma de Hodgkin.","D":"Doença da arranhadura do gato."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-160261","number":"160261","sourceNumber":"160261","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre insuficiência renal aguda (IRA), considere as assertivas a seguir: I: Sulfonamidas\npodem causar IRA tanto por dano tubular\n(necrose tubular aguda) como por reação do tipo alérgico\n(nefrite intersticial aguda); II: Tanto cocaína como inibidores de redutase da coenzima-A podem\ncausar IRA através de nefrotoxicidade tubular pelo pigmento heme através de rabdomiólise; III: A\nmortalidade na IRA pré-renal costuma ser inferior costuma ser inferior a 10%, enquanto que\nnaqueles com IRA intrarrenal a mortalidade pode chegar a 80%; IV: Estudos recentes demonstram\nque, dentre as diversas variáveis clínicas que aumento o risco de IRA, o de maior valor preditivo é\na\npresença prévia de algum grau de insuficiência renal crônica; V: Em pacientes com IRA pré-renal\nque não tenham utilizado diurético, a fração de ejeção se sódio, tipicamente será maior do que 1%.\nDentre as assertivas acima, estão corretas:","options":{"A":"II, III e IV;","B":"I, IV e V;","C":"I, II e III;","D":"III, IV e V;"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-105405","number":"105405","sourceNumber":"105405","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual das opções abaixo relacionadas representa uma situação de\nCONTRAINDICAÇÃO absoluta para o transplante renal?","options":{"A":"Sorologia para citomegalovírus positiva.","B":"Insuficiência coronariana com necessidadade de revascularização miocárdica.","C":"Adenocarcinoma gástrico classificado como T3N0M0 operado há 01 ano.","D":"Sorologia positiva para o Vírus da Imunodeficiência Humana adquirida (HIV +)."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103077","number":"103077","sourceNumber":"103077","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Lactente, 3 anos, é levado à consulta por apresentar febre alta, anorexia e uma massa\nna região submandibular direita, de cerca de\n4 cm, dolorosa, quente e hiperemiada. O quadro teve\ninício há 4 dias (sic). Considerando o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Deve ser realizada uma biópsia excisional ou uma punção por agulha do possível linfonodo\ndescrito.","B":"O hemograma pode mostrar uma leucocitose com neutrofilia, porém não significa\nnecessariamente que deva ser solicitado.","C":"Deve ser realizado o ultrassom da região cervical, em caso de dúvida no diagnóstico,\nconfirmando que se trata de um linfonodo nessa cadeia.","D":"O uso de antibióticos, como, por exemplo, de uma cefalosporina de primeira geração, é uma boa\nconduta, devido à grande possibilidade de ser uma linfadenite inespecífica."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-105742","number":"105742","sourceNumber":"105742","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sebastião, de 49 anos, com longa história de insuficiência renal crônica decorrente de\nnefropatia hipertensiva, é levado ao pronto-socorro por causa de náuseas, letargia e confusão\nmental. O exame físico mostra aumento de pressão venosa jugular, campos pulmonares limpos e\num som rude, sistólico e diastólico, no precórdio. A bioquímica do soro mostra níveis de K+ de 5,7\nmEq/L, HCO3- de 17 mEq/L, ureia de 325 mg/dl e creatinina de 9,9 mg/dl. Assinale a alternativa\nCORRETA quanto ao tratamento a ser instituído nessa emergência:","options":{"A":"Administrar bicarbonato de sódio intravenoso.","B":"Administrar insulina intravenosa e glicose.","C":"Realizar hemodiálise urgente.","D":"Administrar furosemida intravenosa.","E":"Indicar transplante renal."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-120742","number":"120742","sourceNumber":"120742","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente do sexo masculino de 45 anos, com diagnóstico de cirrose hepática\nalcoólica, é internado em anasarca, oligúria\n(diurese de 120 mL/24 hs.), uréia sérica de 200 mg%,\ncreatinina sérica de 1,8 mg% e sódio urinário de 10 mEq/L. Qual o diagnóstico clínico mais\nprovável?","options":{"A":"insuficiência renal aguda por necrose tubular aguda","B":"glomerulonefrite crônica agudizada","C":"pielonefrite crônica agudizada","D":"insuficiência renal aguda pré-renal","E":"nefroesclerose benigna"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-86016","number":"86016","sourceNumber":"86016","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em quais das seguintes situações há aumento da creatinina e da ureia sem redução da\ntaxa de filtração glomerular?","options":{"A":"Idosos, pouca massa muscular e pequena ingesta de carne.","B":"Jovens, sangramento gastrointestinal e grande ingesta de carne.","C":"Idosos, grande massa muscular e grande ingesta de carne.","D":"Jovens, sangramento intestinal e pequena ingesta de carne."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-89145","number":"89145","sourceNumber":"89145","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Os principais fatores de risco para mortalidade de pacientes em diálise são:","options":{"A":"Idade avançada e raça negra.","B":"Idade avançada e elevado número de comorbidades.","C":"Desnutrição e falta de acesso para diálise.","D":"Diabetes e hipoalbuminemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-87979","number":"87979","sourceNumber":"87979","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na insuficiência renal crônica, o hiperparatireoidismo secundário está relacionado à:","options":{"A":"Hipocalcemia, hipofosfatemia, aumento do calcitriol e baixos níveis de PTH.","B":"Hipocalcemia, hiperfosfatemia, aumento do calcitriol e altos níveis de PTH.","C":"Hipocalcemia, hiperfosfatemia, diminuição do calcitriol e altos níveis de PTH.","D":"Hipocalcemia, hipofosfatemia, diminuição do calcitriol e altos níveis de PTH."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-48654","number":"48654","sourceNumber":"48654","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo feminino, 71 anos de idade, em uso contínuo de anti-inflamatórios\npara tratamento de osteoartrose é hospitalizada\napós ter desenvolvido febre, calafrios, mialgias,\nnáuseas, vômitos e diarreia há três dias. Ao exame físico ela está letárgica, orientada e\ndespertável. FC = 106 bpm, PA = 90/70 mmHg. A dosagem da ureia é de 80 mg/dl e a creatinina\nsérica de 1,7 mg/dl, sódio = 145 mEq/L, o cloreto = 109 mEq/L. O volume urinário de 24 horas é de\n340 ml. O exame de urina apresenta densidade de 1030, traços de proteína, traços de cetona.\n\nAssinale a alternativa INCORRETA.","options":{"A":"Podemos afirmar que a paciente apresenta insuficiência renal aguda definida pela redução do\nvolume urinário, elevação da ureia e da creatinina sanguínea.","B":"Antes de considerar uma causa renal parenquimatosa deve-se afastar um mecanismo pré-renal,\ne isto pode ser obtido pela história clínica\nda paciente.","C":"A doença apresentada pela paciente tem o anti-inflamatório como agente causal.","D":"Deve-se iniciar reposição volêmica com solução salina, estimular o fluxo urinário sem indução de\ndiuréticos e descontinuar os anti-inflamatórios.","E":"Pela história clínica da paciente, o mecanismo obstrutivo (pós-renal) de lesão renal não pode ser\nafastado."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-51445","number":"51445","sourceNumber":"51445","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à Insuficiência Renal Aguda no recém-nascido pré-termo :","options":{"A":"Na IRA pré-renal, a osmoralidade urinária é < 350.","B":"Na IRA pré-renal, o Na urinário > 30.","C":"Na lesão renal aguda, o FENA é < 2,5 .","D":"Nenhuma das alternativas acima."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-9760","number":"9760","sourceNumber":"9760","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Marque a alternativa CORRETA:","options":{"A":"níveis séricos elevados de creatinina e ureia não causam, por si, vários sinais e sintomas da\nsíndrome urêmica.","B":"surto de tosse aguda é mais frequentemente causado por infecção respiratória baixa.","C":"a doença de Osler-Rendu-Weber, teleangiectasia hemorrágica hereditária, afeta exclusivamente\no trato digestivo.","D":"hipertensão arterial é importante fator de risco para acidente vascular encefálico hemorrágico,\nnão influenciando o tipo isquêmico."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-9767","number":"9767","sourceNumber":"9767","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Veja se as frases que estão corretas ou incorretas e escolha a alternativa adequada:\n\n- A causa mais comum de insuficiência renal aguda é a pré-renal que ocorre quando há\nhipoperfusão renal;\n\n- Respiração de Cheyne Stokes é comum na insuficiência cardíaca avançada e é usualmente\nassociada a baixo débito cardíaco;\n\n- Albumina sérica é sintetizada exclusivamente pelos hepatócitos;\n\n- Doença cardíaca a principal causa de óbito em pacientes hipertensos;\n\n- Importante perda de peso que é desproporcional ao grau de disfagia é altamente sugestiva de\ncarcinoma de esôfago;\n\n- Acredita-se que a dor na pericardite é originada pela inflamação da pleura parietal adjacente, já\nque a maior parte do pericárdio é insensível à dor ;\n\n- O PSA (antígeno prostático específico) é produzido por epitélio maligno bem como pelo sadio,\nportanto é próstata/específico e não câncer/específico, podendo ter nível sérico elevado na\nprostatite, hipertrofia prostática benigna e no câncer prostático;\n\n- Espasmo esofagiano pode ocorrer na presença ou ausência de refluxo ácido e origina dor\nopressiva indistinguível da angina pectoris.","options":{"A":"uma frase é incorreta e as demais corretas.","B":"duas frases são incorretas e as demais corretas.","C":"todas estão corretas.","D":"três frases são incorretas e as demais corretas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-349111","number":"349111","sourceNumber":"349111","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma menina de 6 anos em tratamento para leucemia linfoide aguda, é levada a uma\nunidade de pronto-atendimento infantil devido a pico febril de 38,5°C, sem outros sintomas\nassociados. Ela utiliza um cateter de longa permanência para a administração de quimioterapia,\nrealizada há uma semana. Seu exame físico não revela alterações. Diante do quadro clínico\napresentado, assinale a opção correta em relação à propedêutica.","options":{"A":"A paciente deve ser tratada com antibióticos de largo espectro, sendo indicada a troca imediata\ndo cateter de longa permanência.","B":"A paciente dispensa a propedêutica complementar, por se tratar de um primeiro pico febril e por\nnão haver alterações no exame físico que indiquem foco infeccioso.","C":"A paciente apresenta alto risco para neutropenia febril e, por isso, deve realizar hemograma,\nhemocultura de sangue periférico e de cateter central e provas inflamatórias.","D":"A paciente deve realizar hemograma completo e, caso o resultado indique neutrófilos < 1\n000/mm³, a investigação deve prosseguir com hemocultura, com provas inflamatórias e com\nhemocultura de cateter central."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-347447","number":"347447","sourceNumber":"347447","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um menino com 13 anos, previamente saudável, foi avaliado no ambulatório de\npneumologia, por causa de uma história de 20 dias de febre (> ou = 38°C), mal-estar, sudorese\nnoturna, profusa e tosse seca, que não foram modificados pelo tratamento prévio com amoxicilina.\nAo exame físico, foram observados no paciente múltiplos linfonodos de consistência endurecida,\nfixos, indolores, em cadeia cervical e supraclavicular esquerda, com diâmetro entre 2 a 5 cm cada\num. Foi realizada radiografia de tórax, que mostrou infiltrados pulmonares bilaterais, arredondados,\ne adenopatia hilar bilateral. Diante do caso descrito, assinale a opção que apresenta,\nrespectivamente, a principal hipótese diagnóstica e a conduta correta para a sua confirmação.","options":{"A":"Mononucleose; solicitar biópsia aspirativa de gânglio e sorologias específicas.","B":"Tuberculose; solicitar hemograma, hemocultura e tomografia computadorizada de alta resolução\nde corpo inteiro.","C":"Pneumonia comunitária; solicitar hemograma, hemocultura e tomografia computadorizada por\nemissão de pósitrons de tórax.","D":"Linfoma de Hodgkin; solicitar biópsia excisional de gânglio e tomografia computadorizada por\nemissão de pósitrons de corpo inteiro."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-319929","number":"319929","sourceNumber":"319929","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 55 anos está, há 2 meses, com quadro de linfadenopatia cervical e axilar de\naumento progressivo, associada a febre recorrente, com temperatura axilar superior a 38°C,\nsudorese noturna e perda de peso de 6 kg desde o início das manifestações. Nega doenças\npreexistentes e uso de medicamentos, mas informa tabagismo há 35 anos, com carga tabágica de\n50 anos/maço. No exame, apresentava linfadenomegalia cervical anterior e posterior\nbilateralmente, axilares bilaterais, com gânglios de 2,5 a 4 cm de diâmetro, consistência endurecida\ne fixos. Sua temperatura axilar no momento é de 38,5°C. Radiografia de tórax mostra massa\nmediastinal de cerca de 8 cm de diâmetro. Já foram solicitados hemograma, proteína C reativa,\ntomografia computadorizada de tórax com contraste. Em relação ao caso clínico apresentado, qual\né o diagnóstico provável e qual exame complementar deve ser solicitado ainda?","options":{"A":"Citomegalovírus; sorologias.","B":"Linfoma; biópsia de gânglio cervical.","C":"Mononucleose infecciosa; sorologias.","D":"Metástase de carcinoma cervical, provavelmente tireoide; biópsia de gânglio cervical."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-355214","number":"355214","sourceNumber":"355214","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Durante visita à enfermaria de clínica médica, discutia-se sobre um paciente com\ncirrose hepática, o qual era portador de\nesplenomegalia e possuía os seguintes achados ao\nhemograma: Hb 8 g/dL, leucócitos 2.500/mm3 e plaquetas 90.000/mm3. No contexto da cirrose\nhepática, os alunos foram arguidos sobre qual seria a justificativa da organomegalia e dos achados\ndo hemograma e responderam, de forma assertiva, que seriam, respectivamente,","options":{"A":"hipertensão portal e hiperesplenismo.","B":"mielofibrose e aplasia medular.","C":"hipertensão portal e deficiência de ferro.","D":"mielofibrose e transformação leucêmica.","E":"hemólise crônica e hemocaterese excessiva."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-369448","number":"369448","sourceNumber":"369448","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente jovem, em tratamento para linfoma não Hodgkin, com presença de massa\ntumoral volumosa em mediastino, apresenta, alguns dias após início de quimioterapia, quadro de\nconfusão mental e desidratação, seguidos de crise convulsiva. Frente à suspeita de síndrome de\nlise tumoral, espera-se a redução sérica do marcador:","options":{"A":"Potássio.","B":"Fósforo.","C":"Cálcio.","D":"Ácido úrico.","E":"Creatinina."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-276656","number":"276656","sourceNumber":"276656","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Durante uma reunião de equipe em uma Unidade Básica de Saúde sobre Doenças de\nChagas, incluindo seus aspectos epidemiológicos e ações possíveis de serem planejadas pela\nequipe de saúde na Atenção Primária, membros da equipe manifestaram as seguintes frases: I. A\npreconização com relação à doença de Chagas determina que esta deve ser tratada na atenção\nespecializada por profissionais de saúde treinados e que possuam tecnologia adequada. II. Os\nmovimentos das pessoas nos territórios e entre territórios diferentes devem ser considerados, seja\ndo passado e do presente, para uma análise mais adequada sobre o risco para a doença de\nChagas. III. A doença de Chagas é reconhecida na maioria dos casos por limitar o desempenho do\ntrabalho profissional e a vida social com grande impacto em aposentadorias concedidas. IV. Em\ncaso de confirmação ou existência de caso atual ou anterior na área adscrita é fundamental realizar\na busca ativa de possíveis casos crônicos em familiares e na rede de contatos sociais. V. Como\ndoença que compõe o grupo das negligenciadas, a doença de Chagas é causa e consequência da\npobreza estrutural de pessoas, famílias e comunidades, perpetuando a vulnerabilidade existente.\n\nVI. A doença de Chagas é considerada uma condição infecciosa aguda, com elevada carga de\ndoença na população e baixa mortalidade\nespecífica no Brasil e em outros países endêmicos. Ao\nolhar atento dos parceiros de equipe, observou-se que há considerações corretas e incorretas entre\nestas, de forma que a equipe precisa reforçar o aprendizado sobre a doença para tomar as\ndecisões mais apropriadas. Entre as frases mencionadas, estão corretas:","options":{"A":"I, II e IV","B":"I, II, III, IV, V e VI","C":"II, IV, V e VI","D":"I, IV e VI","E":"II, IV e V"},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-269752","number":"269752","sourceNumber":"269752","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino de 63 anos deu entrada na unidade de emergência com febre e dor\nem hipocôndrio esquerdo, realizou hemograma que mostrou hemoglobina 11,4 g/dl, leucócitos\n120.000/mm³ com 87% de linfócitos e plaquetas de 106.000/mm³. O diagnóstico mais provável e o\nexame a solicitar para confirmação do mesmo são:","options":{"A":"Mieloma múltiplo, solicitar imunoeletroforese de proteínas.","B":"Leucemia linfoide crônica, solicitar imunofenotipagem de sangue periférico.","C":"Linfoma de Hodgkin, solicitar PET ? CT.","D":"Leucemia mieloide crônica, solicitar PCR para BCR/ABL.","E":"Leucemia linfoide aguda, solicitar biópsia de medula óssea."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-277742","number":"277742","sourceNumber":"277742","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"GSM, 15 anos, após iniciar quimioterapia para tratamento de leucemia linfoide aguda,\nevolui com redução de volume urinário e\nelevação das escórias nitrogenadas, caracterizando injúria\nrenal aguda. A etiologia do acometimento renal e os seus achados característicos são,\nrespectivamente,","options":{"A":"rabdomiólise; hipercalcemia, hipouricemia, hiperfosfatemia e hipercalemia.","B":"síndrome de lise tumoral; hipocalcemia, hiperuricemia, hiperfosfatemia e hipercalemia.","C":"rabdomiólise; hipocalcemia, hiperuricemia, hipofosfatemia e hipocalemia.","D":"síndrome de lise tumoral; hipercalcemia, hipouricemia, hipofosfatemia e hipocalemia.","E":"rabdomiólise; hipocalcemia, hiperuricemia, hiperfosfatemia e hipocalemia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-277776","number":"277776","sourceNumber":"277776","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na região insular do município de Belém, o Instituto Evandro Chagas tem identificado\ninsetos barbeiros contaminados com o Trypanosoma\ncruzi, causador da doença de Chagas. A\nforma de infecção mais documentada na região é","options":{"A":"picada do barbeiro, sendo comum o achado de chagoma de inoculação.","B":"transfusional.","C":"vertical, por via transplacentária.","D":"compartilhamento de agulhas em drogaditos.","E":"alimentar, pelo consumo do açaí sem o processo de branqueamento."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-254730","number":"254730","sourceNumber":"254730","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 66 anos, sexo feminino, hipertensa sem tratamento prévio, deu entrada no\nsetor de urgência, com dispneia intensa,\nfrequência cardíaca de 110 BPM, pressão arterial de\n180/100 mmHg, frequência respiratória de 36 IRPM, saturação de oxigênio em ar ambiente de 82%,\nescala de coma de Glasgow 7 (O2V1M4), temperatura axilar 36,5oC, anasarcada e ausculta\npulmonar com estertores crepitantes difusos bilaterais. Aos exames: pH 7.3, HCO3 15 mmol/L,\npCO2 30 mmHg, pO2 40 mmHg, SatO2 80%, creatinina 4 mg/dl (creatinina de doze meses atrás\nigual a 3,5 mg/dl), potássio 7 mEq/L, hemoglobina 8g/dl, leucócitos 7000, plaquetas 200.000. As\ndoenças de base e a complicação ocorrida são, respectivamente,","options":{"A":"nefroesclerose hipertensiva, doença renal crônica e edema agudo de pulmão.","B":"hipertensão arterial sistêmica, injúria renal aguda e derrame pleural.","C":"acidente vascular encefálico, injúria renal aguda e pneumonia.","D":"hipertensão arterial sistêmica, doença renal crônica e derrame pleural.","E":"nefroesclerose hipertensiva, injúria renal aguda e edema agudo de pulmão."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-230917","number":"230917","sourceNumber":"230917","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à doença de Chagas, pode-se afirmar: I) A doença de Chagas é uma\ndoença que afeta populações negligenciadas,\ncausada por um protozoário, o T. cruzi, característica\ndo continente americano, tendo o Brasil aproximadamente metade dos casos conhecidos nas\nAméricas Central e do Sul; II) Ela se desenvolve em duas fases clínicas, aguda e crônica, sendo\nambas as formas de notificação compulsória em todo o território nacional; III) Nos primeiros casos\nestudados, no início do século XX, foi descrita por Carlos Chagas a forma de transmissão vetorial.\nPorém, hoje, na região Amazônica, predomina a forma de transmissão oral da doença.","options":{"A":"I, II e III estão corretas.","B":"Somente I está correta.","C":"Somente I e III estão corretas.","D":"Somente I e II estão corretas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-240462","number":"240462","sourceNumber":"240462","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A infecção pelo HTLV (Human T-lymphotropic vírus type) frequentemente é menos\nlembrada do que a infecção pelo HIV, embora sua prevalência no estado do Pará esteja entre as\nmaiores do país. O diagnóstico relacionado à infecção pelo HTLV é","options":{"A":"tumor de Wilms.","B":"neuromielite óptica.","C":"leucemia/linfoma de células T do adulto.","D":"sarcoidose.","E":"psoríase."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-227641","number":"227641","sourceNumber":"227641","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre as neoplasias hematológicas, marque a alternativa CORRETA.","options":{"A":"O termo \"leucemia\" designa uma neoplasia hematológica caracterizada pela presença de células\nmalignas exclusivamente na medula óssea.","B":"O termo \"linfoma\" refere-se a uma proliferação localizada de células linfoides formando uma\nmassa tecidual sólida.","C":"Células B maduras expressam em geral marcadores para CD3, CD2 e CD5, sendo que 80%\ndelas expressam CD7.","D":"Células NK em geral expressam CD2, CD3 e CD7.","E":"Neoplasias de NK expressam altos níveis de CD20."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216176","number":"216176","sourceNumber":"216176","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Linfadenopatia é a denominação dada a linfonodos de tamanho, consistência ou\nquantidade anormais. O corpo humano tem aproximadamente 600 linfonodos, podendo ser\npalpáveis em indivíduos hígidos, apenas os encontrados em região submandibular, axilar e\ninguinal. Marque a alternativa de linfoadenopatia causada por doenças imunológicas:","options":{"A":"hepatite, lupus, filariose.","B":"leucemia, doença do soro, doença de Niemann-Pick.","C":"mononucleose, histoplasmose, leishmaniose.","D":"artrite reumatóide, lupus, associada a silicone.","E":"toxoplasmose, hipertireoidismo, cirrose biliar primária."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215860","number":"215860","sourceNumber":"215860","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"No linfoma não Hodgkin os padrões morfológicos de infiltração da medula óssea pode\nser característico de acordo com o fenótipo dessa\nneoplasia. Em relação a esse aspecto, é\nCORRETO afirmar que:","options":{"A":"Linfomas de células do manto e linfoma linfoblástico em geral levam a infiltração difusa da\nmedula óssea.","B":"Infiltração intrasinusoidal em geral é encontrada no quadro evolutivo de linfomas de células do\nmanto.","C":"Linfoma linfoplasmacítico e linfoma de células do manto em geral levam a infiltração medular\nfocal não trabecular.","D":"Infiltração difusa da medula óssea em geral associa-se a quadro clínico de tricoleucemia.","E":"Infiltração medular paratrabecular em geral associa-se a evolução clínica de linfoma MALT."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-215922","number":"215922","sourceNumber":"215922","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na classificação da OMS para as neoplasias linfoides, são exemplos de neoplasias de\ncélulas B periféricas:","options":{"A":"linfoma linfoblástico agudo de células B, linfomas de grandes linfócitos granulares, síndrome de\nSézary.","B":"linfoma de zona marginal, micose fungóide, linfoma de Burkitt.","C":"tricoleucemia, linfoma de Bukitt, linfomas de células do manto.","D":"linfoma linfoplasmacítico, llinfoma de zona marginal esplênica, micose fungóide.","E":"linfoma de Burkitt, micose fungóide, linfoma linfoblástico agudo de células B."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-216185","number":"216185","sourceNumber":"216185","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de cinco anos, iniciou quadro de adinamia, fadiga, dores em MMII e nas\narticulações dos joelhos, febre intermitente e equimoses pelo corpo, após traumas leves, há cerca\nde 30 dias. Ao exame: palidez cutâneo mucosa +++/4+; linfonodomegalias em região cervical\nbilateral, baço palpável a 6,5cm do rebordo costal esquerdo, fígado palpável a 3,5cm do rebordo\ncostal direito, equimoses difusas em MMII e dorso. Há cerca de uma semana, foi iniciado pelo\nmédico assitente corticoide de via oral para a criança, com melhora das dores em MMII.\nLaboratório: hemácias 2.800.000/mm³; hematócrito: 22,5%; hemoglobina 7,4g/dl; VCM 78,3Fl;\nCHCM 32,8g/dL; HCM 25,7 pg; leucócitos 8000/mm³ ( linfócitos 88%, segmentados 12%),\nplaquetas 25.000/mm³. A principal hipótese diagnóstica é:","options":{"A":"aplasia medular","B":"artrite reumatoide","C":"leucemia linfoide aguda","D":"mononucleose infecciosa","E":"dengue hemorrágica"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156656","number":"156656","sourceNumber":"156656","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Hiperuricemia é uma das complicações frequentemente encontradas em:","options":{"A":"Tricoleucemia.","B":"Síndromes mieloproliferativas.","C":"Linfomas.","D":"Mieloma.","E":"Leucemia linfoicítica crônica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-156650","number":"156650","sourceNumber":"156650","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"M.A, 6 anos, com quadro de dor importante em quadris há 15 dias, geralmente noturna,\ncom dificuldade de deambular e febre elevada.\nAo exame físico se encontrava irritado, febril,\nemagrecido e ao examinar os quadris não apresentava limitação ao movimento das articulações\ncoxo-femurais. A impressão diagnóstica e o exame a ser solicitado são:","options":{"A":"Leucemia linfoide aguda; mielograma.","B":"Sinovite transitória de quadril; ultrassonografia de quadril.","C":"Artrite idiopática juvenil; fator reumatoide.","D":"Legg Calvé-Perthes; radiografia de quadris.","E":"Epifisiólise femural."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-159998","number":"159998","sourceNumber":"159998","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente portador de Leucemia linfoide aguda, vem apresentando crise convulsiva pós\nquimioterapia e aumento de creatinina serica, acompanhada de hiperpotassemia, hipocalcemia e\nhiperfosfatemia. Ante o exposto, é correto afirmar que o paciente em questão apresenta:","options":{"A":"Síndrome de cava superior.","B":"Compressão medular.","C":"Síndrome torácica aguda.","D":"Síndrome de lise tumoral.","E":"Hiperleucocitose."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-159995","number":"159995","sourceNumber":"159995","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente portador de Leucemia linfoide aguda, vem apresentando crise convulsiva pós\nquimioterapia e aumento de creatinina serica, acompanhada de hiperpotassemia, hipocalcemia e\nhiperfosfatemia. A melhor conduta para o paciente exposto no caso acima é:","options":{"A":"Exsanguineotransfusão.","B":"Plasmaferese.","C":"Antibioticoterapia.","D":"Bicarbonato de sódio.","E":"Hiper-hidratação."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-134525","number":"134525","sourceNumber":"134525","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Homem de 85 anos diabético e hipertenso dá entrada no hospital com quadro de\nretenção urinária, congesto e urêmico. O nefrologista de sobreaviso indicou hemodiálise de\nurgência e solicitou que você implantasse o cateter temporário para terapia substitutiva renal. O\nsítio de punção ideal para o implante do cateter de Shilley é:","options":{"A":"Veia Subclávia Esquerda","B":"Veia Femoral Comum Direita","C":"Veia Jugular Interna Esquerda","D":"Veia Jugular Interna Direita","E":"Veia Subclávia Direita"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-86504","number":"86504","sourceNumber":"86504","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Considere a situação hipotética para responder a questão. Um homem de 68 anos de\nidade foi admitido para ressecção eletiva de um aneurisma de aorta abdominal infrarrenal. Tinha\ncomo antecedentes patológicos: hipertensão arterial sistêmica, miocardiopatia hipertensiva e\nhiperplasia prostática benigna. Na rotina laboratorial pré-operatória, apresentava ureia sérica de\n20\nmg/dl; creatinina sérica de 1,4 mg/dl e urinálise normal. A cirurgia foi complicada por períodos\nintermitentes de hipotensão, que foram revertidos com administração de sangue e soro fisiológico\n0,9%. No pós-operatório inicial, o paciente evoluiu com redução do débito urinário (0,3 ml/kg/h em\n12h). Solicitados exames para investigação, que mostraram os seguintes resultados: ureia sérica =\n33 mg/dl; creatinina sérica de 2,8 mg/dl; Na+ urinário = 61 mEq/L; osmolaridade urinária = 280\nmOsmol/kg H2O; densidade urinária = 1,010 e excreção fracional de sódio 3,4%. O exame do\nsedimento urinário revelou a presença de vários cilindros granulares pardos, proteinúria discreta,\npoucos leucócitos e ausência de hemácias. Sobre o caso descrito acima, a principal hipótese\ndiagnóstica para a insuficiência renal aguda do paciente é:","options":{"A":"Insuficiência renal pré-renal por hipovolemia.","B":"Insuficiência renal pré-renal por insuficiência cardíaca.","C":"Insuficiência renal pós-renal por uropatia obstrutiva.","D":"Necrose Tubular Aguda (NTA) isquêmica.","E":"Glomerulonefrite rapidamente progressiva."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-88101","number":"88101","sourceNumber":"88101","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"NÃO é indicação de diálise:","options":{"A":"Oliguria.","B":"Pericardite urêmica.","C":"Sintomas urêmicos refratários ao tratamento clínico.","D":"Hipervolemia refratária.","E":"Hipercalemia refratária."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-50136","number":"50136","sourceNumber":"50136","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em um paciente com insuficiência renal crônica, a ocorrência de anemia deve-se\nprincipalmente a:","options":{"A":"Perdas gastrintestinais insensíveis.","B":"Deficiência de ácido fólico.","C":"Deficiência na ativação da vitamina D.","D":"Deficiência na produção de eritropoetina.","E":"Inibição da medula óssea pelos níveis altos de ureia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-326428","number":"326428","sourceNumber":"326428","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 50 anos, sexo masculino, veio para consulta com queixa de febre e\nperda de peso. Os sintomas surgiram há 3\nmeses, a febre é diária e os valores chegam a 39,4° C\ncom sudorese noturna, fadiga intensa e perda de 22kg no período. Nega exposição a pacientes\ncom alguma doença, nega histórico de viagens, única parceira sexual há 25 anos, nega transfusões\nsanguíneas. Ao exame não foi identificado nada relevante. No laboratório revelou leucócitos 15\n700/?L, com 80% de polimorfonucleados, 15% linfócitos, 3% eosinófilos e 2% monócitos e níveis de\ncálcio de 11,2 g/dl (8, 8-10, 4). O esfregaço do sangue periférico é normal e o VHS é de 57 mm/h.\n\nO painel reumatológico é normal, o nível de ferritina é de 550 ng/ml. Função hepática e renal sem\nanormalidades. Eletroforese de proteínas séricas demonstra gamopatia policlonal. Os testes para\nvírus HIV, hepatite B, hepatite C, Epstein-Barr e citomegalovírus foram negativos. O antígeno\nurinário de Histoplasma é negativo. As hemoculturas colhidas na hora da febre em 3 amostras,\nradiografia do tórax e PPD foram todos negativos. A tomografia de tórax, abdômen e pelve revelam\naumento limítrofe de linfonodos no abdômen e retroperitônio de 1,3cm. Qual deve ser e o melhor\npasso seguinte na investigação desse caso?","options":{"A":"Tratamento empírico com corticosteroides em dose imunossupressora.","B":"Tratamento empírico para mycobacterium tuberculosis.","C":"Punção biópsia por agulha dos linfonodos aumentados.","D":"Tomografia por emissão de pósitrons (PET)-TC.","E":"Dosar níveis séricos de enzima conversora de angiotensina."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-326449","number":"326449","sourceNumber":"326449","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 16 anos será submetido à esplenectomia total para tratamento de anemia\nfalciforme. Umas das medidas para prevenção da sepse fulminante pós-esplenectomia é vacinação\ncontra germes encapsulados, que deve oferecer proteção para quais patógenos:","options":{"A":"Streptococcus pneumoniae, neisseria meningitidis e haemophilus influenzae.","B":"Stafilococcus aureus, streptococcus pneumoniae e neisseria meningitidis.","C":"Stafilococcus epidermidis, haemophilus influenzae e proteus mirabilis.","D":"Streptococcus pneumoniae, haemophilus influenzae e pseudomonas aeruginosa.","E":"Streptococcus pneumoniae, neisseria meningitidis e klebisella pneumoniae."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-284459","number":"284459","sourceNumber":"284459","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação a síndrome de lise tumoral (SLT), sabemos que a mesma pode surgir de\nmaneira espontânea, principalmente em tumores com alta taxa de divisão celular e naqueles com\nboa resposta ao tratamento com quimioterapia. Em relação a SLT, é característica laboratorial:","options":{"A":"Hiperfosfatemia, hipercalcemia, hiperuricemia e hipercalemia.","B":"Hipofosfatemia, hipocalcemia, hipouricemia e hipocalemia.","C":"Hipofosfatemia, hipocalcemia, hipouricemia, hipercalemia.","D":"Hipofosfatemia, hipocalcemia, hiperuricemia e hipercalemia.","E":"Hiperfosfatemia, hipocalcemia, hiperuricemia, hipercalemia."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-254099","number":"254099","sourceNumber":"254099","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O aumento de linfonodos está presente em algumas situações da prática clínica, tais\ncomo quadros infecciosos, alterações imunológicas e neoplásicas. Diferenciar um linfonodo\ninflamatório de um neoplásico pode ser um desafio para o pediatra e motivo de grande ansiedade\npor parte dos pais. Considere as afirmações a seguir e escolha a alternativa CORRETA.","options":{"A":"O comprometimento linfonodal é dito localizado quando apenas um linfonodo está\ncomprometido, e disseminado quando dois ou mais estão aumentados de tamanho.","B":"Linfadenopatia localizada é mais comum em um processo bacteriano agudo (adenite), podendo\ntambém ser consequência de um linfoma,\ntumor sólido, tuberculose ou outros. As linfadenopatias\ndisseminadas estão associadas aos processos virais, bacterianos sistêmicos, doenças inflamatórias\ne neoplásicas (p.ex., leucemias).","C":"Linfonodos duros, aderidos aos planos profundos e dolorosos, medindo em torno de 3 cm são\nassociados a quadros reacionais em quase totalidade.","D":"A elevação da DHL não guarda relação com morte celular, apesar de ser comumente valorizada\nnos casos de leucemias. Não tem indicação de sua\nsolicitação no diagnóstico/tratamento de\nneoplasias sólidas.","E":"O ácido úrico eleva-se apenas quando instituída a quimioterapia nos tratamentos de neoplasias."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-240944","number":"240944","sourceNumber":"240944","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino, 74 anos, com quadro de pancitopenia associada à\nesplenomegalia maciça. Hematoscopia evidenciou células em lágrima. Quando submetido ao\nmielograma, observou-se dificuldade na progressão da agulha, e o aspirado apresentou-se\nescasso, do ponto de vista macroscópico. Considerando os dados acima, o diagnóstico mais\nprovável é:","options":{"A":"Tricoleucemia.","B":"Leishmaniose visceral.","C":"Leucemia mieloide crônica.","D":"Mielofibrose primária.","E":"Mielodisplasia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-252205","number":"252205","sourceNumber":"252205","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A mãe leva seu filho de 4 anos ao serviço de saúde com palidez e manchas vermelhas\nna pele há mais ou menos 21 dias, nos últimos\ndias a palidez piorou acentuadamente. Ao exame\nfísico: estado geral comprometido, hipoativo, hipocorado 3+/4+, anictérico e acianótico. Presença\nde linfoadenomegalia cervical e inguinal. As auscultas respiratória e cardíaca estavam normais. O\nabdome estava globoso, flácido, com fígado palpável a 4 cm do rebordo costal direito e o baço\npalpável a 4 cm do rebordo costal esquerdo. Presença de petéquias e equimoses disseminadas na\npele e em mucosa oral e palato. O hemograma, hemoglobina de 5,7 g/dL, volume corpuscular\nmédio de 88 fL, leucometria de 112.000 leucócitos/mm³ com predomínio de linfócitos e 35%\napresentando alta relação núcleo citoplasmática e cromatina nuclear frouxa; plaquetometria de\n\n11.000 plaquetas/mm³. Considerando a principal hipótese, qual dos fatores descritos neste caso\nestá associado a um bom prognóstico para este paciente?","options":{"A":"Leucometria > 50.000 leucócitos/mm.","B":"Evolução de doença < 6 meses.","C":"linfoblastos de > 30% no sangue periférico.","D":"Idade do paciente > 1 ano."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-241007","number":"241007","sourceNumber":"241007","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na investigação de linfonodomegalia na infância deve chamar atenção para\nmalignidade, EXCETO:","options":{"A":"Febre inexplicada, astenia, dores ósseas, perda de peso.","B":"Hepatoesplenomegalia.","C":"Pequenos linfonodos em região occipital e retroauricular.","D":"Manifestações hemorrágicas.","E":"Linfonodos supraclaviculares."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-218189","number":"218189","sourceNumber":"218189","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Jovem de 26 anos apresenta sangramento gengival, febre há 2 dias, hematúria e\npetéquias em membros inferiores. Hemograma:\nHb = 9,6 g/dl; leucócitos = 1.900/mm³\n(segmentados = 14%, linfócitos 41% e presença de 44% de células imaturas); plaquetas =\n17.000/mm³. Qual a hipótese mais provável, conduta para confirmação diagnóstica e terapia inicial?","options":{"A":"Leucemia Mieloide Crônica (LMC), pesquisa de mutação BCR/ABL, transfusão de plaquetas.","B":"Púrpura trombocitopênica imunológica, pesquisa de anticorpos antiplaquetas e corticoterapia.","C":"Leucemia mieloide aguda, mielograma, transfusão de plaquetas e antibioticoterapia empírica.","D":"Leucemia hairy cell, pesquisa de cromossomo Philadelphia e interferon gama.","E":"Leucemia linfoide crônica, mielograma e quimioterapia."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-185347","number":"185347","sourceNumber":"185347","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar de quatro anos de idade, sexo feminino, da zona rural de Sapé/Paraíba, é\nlevado ao pediatra com história de febre, dor nas articulações distais dos membros inferiores,\nfraqueza progressiva e palidez há 15 dias. Exame físico: temp. axilar: 37 oC, palidez cutânea e das\nconjuntivas 4+/5+, petéquias em membros inferiores; hepatomegalia: 4 cm abaixo do rebordo costal\ndireito e esplenomegalia: 6 cm abaixo do rebordo costal esquerdo. Hemograma: pancitopenia. O\ndiagnóstico mais provável é:","options":{"A":"Salmonelose septicêmica prolongada.","B":"Artrite idiopática juvenil (forma sistêmica).","C":"Calazar.","D":"Leucemia linfoblástica aguda.","E":"Esquistossomose mansônica."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-185370","number":"185370","sourceNumber":"185370","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Escolar de sete anos de idade, apresenta quadro agudo de lesões petequiais e\nequimóticas disseminadas pelo corpo e palidez\ncutânea . Os exames revelam: hemoglobina 8,3g%;\nhematócrito: 24%; VCM: 70; RDW: 15%; hipocromia e microcitose; leucócitos 9800/ mm³; plaquetas\n12000/mm³. Exame físico: estado geral bom, hidratado, afebril,palidez cutânea: 2++/5+++++,\neupneico, perfusão periférica regular. Ritmo cardíaco regular, bulhas rítmicas e normofonéticas,\nsem sopros, FC = 108bpm, murmúrio vesicular positivo, sem ruídos adventícios. Abdome plano,\ndepressível, fígado e baço impalpáveis. Gânglios móveis, indolores, de consistência elástica,\nmedindo 0,5 cm de diâmetro nas cadeias submandibulares e cervicais. Assinale a afirmativa\nINCORRETA:","options":{"A":"O diagnóstico provável é púrpura trombocitopênica imune e apesar de o número de plaquetas\nestar diminuído\n\nnão há indicação de infusão de concentrado de plaquetas, entretanto o uso de imunoglobulina\nendovenosa é\n\nefetivo para elevar as plaquetas em 80% dos casos.","B":"A hospitalização é apropriada, pois há risco de sangramento.","C":"O aspirado de medula óssea está formalmente indicado para excluir leucemia aguda.","D":"Deve-se orientar aos pais que se trata de doença benigna e autolimitada.","E":"O uso de concentrado de hemácias deve ser a principio desaconselhado para este caso."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-161928","number":"161928","sourceNumber":"161928","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente feminina, 42 anos, realizou segundo ciclo de quimioterapia adjuvante para\nneoplasia de mama, há 15 dias. Procura UPA com quadro de febre há 2 dias (03 medidas acima de\n38°C). Nega quaisquer outros sintomas, inclusive urinários. Hipertensa, em uso de enalapril\n10mg/dia. Ao exame físico geral apresenta bom estado, corada, eupneica, orientada, T: 38,5°C,\nPA: 130 x 90 mmHg, FC: 90 bpm, FR: 16 irm. Sem alterações ao exame fisico especial. Colhe\nhemograma que apresenta o seguinte resultado: Hb: 10 g/dL, Ht: 32,0%, leucócitos: 1.000/mm³,\nsegmentados: 400/mm³, sem desvio, plaquetas: 120.000/mm³. Além de coleta de culturas e\nsintomáticos, qual a conduta correta?","options":{"A":"Suspender o enalapril que pode ser a causa da neutropenia e retornar ao posto de saúde em\n48hs.","B":"Tratamento ambulatorial com amoxicilina-clavulanato + ciprofloxacina, encaminhar ao\nambulatório de origem para reavaliação em 48hs e se piorar retornar à emergência.","C":"Providenciar internamento em isolamento para a paciente e iniciar cefepime ou um\ncarbapenêmicos.","D":"Providenciar internamento em isolamento para a paciente e iniciar cefepime ou um\ncarbapenêmicos + vancomicina.","E":"Providenciar internamento em isolamento para a paciente e iniciar cefepime ou um\ncarbapenêmicos + vancomicina + antifúngico"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-160573","number":"160573","sourceNumber":"160573","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Na investigação de um homem de 24 anos, com quadro de linfadenopatia cervical\npersistente, foram encontrados, à microscopia óptica da biópsia excisional do linfonodo, os\nseguintes achados: células gigantes, multinucleadas, com núcleos bilobulados, nucléolos\neosinofílicos, imersos em um infiltrado inflamatório fibrótico. O diagnóstico mais provável é:","options":{"A":"Linfoma difuso de grandes células B.","B":"Linfoma de Hodgkin.","C":"Tuberculose ganglionar.","D":"Sarcoidose.","E":"Mononucleose pelo Epstein-Barr vírus."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-160587","number":"160587","sourceNumber":"160587","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com relação a linfonodomegalia em crianças, são sinais de alerta para a possibilidade\nde doença grave, EXCETO:","options":{"A":"Localização supraclavicular.","B":"Linfonodos endurecidos e aderidos aos planos profundos.","C":"Associação com febre persistente e de causa desconhecida.","D":"Linfonodomegalia de evolução maior que duas semanas.","E":"Calor, dor e rubor local."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-138497","number":"138497","sourceNumber":"138497","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual das seguintes proteínas quiméricas é expressa pela codificação do gene de fusão\npresente no cromossomo Philadelphia [t(9,22)] em pacientes portadores de leucemia mieloide\ncrônica?","options":{"A":"E2a-Pbx1.","B":"MLL-ENL.","C":"ETV6-NTRK3.","D":"BCR-ABL1.","E":"FIP1-PDGFRa."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-110379","number":"110379","sourceNumber":"110379","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual o antibiótico abaixo não necessita ajuste para a função renal?","options":{"A":"Ciprofloxacina.","B":"Cefepime.","C":"Clindamicina.","D":"Vancomicina.","E":"Meropenem."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-109100","number":"109100","sourceNumber":"109100","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Conforme as recomendações do KDOQI para o diagnóstico e estadiamento da doença\nrenal crônica, analise os seguintes casos e\nassinale a alternativa que contém apenas os pacientes\nnos quais se pode afirmar que há critérios diagnósticos para doença renal crônica (considere todas\nas alterações laboratoriais ou de imagem confirmadas em uma segunda amostra ou em novo\nexame laboratorial): I) Homem, 54 anos, com quatro cistos em rim direito e três em rim esquerdo,\nmedindo em média 30 mm, vistos através de ultrassonografia abdominal. Albuminúria de 24 horas\n\n= 10 mg. Taxa de filtração glomerular de 100 ml/min/1,73 m²; II) Mulher, 69 anos, diabética de longa\ndata, com microalbuminúria de 24 horas = 50 mg; TFG de 70 ml/min/1,73 m². USG renal sem\nalterações; III) Homem, 45 anos, hipertenso, com albuminúria de 10 mg em 24 horas, TFG de 54\nml/min/1,73 m², USG renal sem alterações.","options":{"A":"I, II e III.","B":"I e II.","C":"I e III.","D":"II e III.","E":"I."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-88471","number":"88471","sourceNumber":"88471","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Luciana tem 3 anos e foi diagnosticada portadora de GNDA pós-estreptocócica. Fez o\ntratamento adequado, porém não evoluiu satisfatoriamente e há um dia o médico assistente\nsolicitou uma biópsia renal. De acordo com o caso descrito, qual a assertiva contém critério para\nindicação de biópsia renal nos casos de GNDA?","options":{"A":"Proteinúria nefrótica por 5 dias.","B":"C3 elevado por mais de 8 semanas.","C":"Oligúria importante por mais de 72h.","D":"A doença em crianças menores de 4 anos.","E":"Hipertensão ou hematúria abaixo de 2 semanas"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-65867","number":"65867","sourceNumber":"65867","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 45 anos, com hipertensão arterial sistêmica e diabetes mellitus há 15\nanos tem como complicação insuficiência\nrenal há 3 anos. Assinale a alternativa que indicaria a\nnecessidade do início de programa de hemodiálise.","options":{"A":"Pericardite aguda e hipercalcemia.","B":"Encefalopatia urêmica e hipernatremia.","C":"Hipercalemia e acidose metabólica (pH = 7,25).","D":"Anemia grave (normocrômica e normocítica) e hiperfosfatemia.","E":"Hipervolemia refratária e hiponatremia (sódio < 125 mg/dl)."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-65937","number":"65937","sourceNumber":"65937","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à linfonodomegalia, assinale o que NÃO é indicativo de sinal de alerta:","options":{"A":"Presença de sinais flogísticos.","B":"Linfonodos endurecidos.","C":"Febre persistente de causa não esclarecida.","D":"Linfonodos aderidos aos tecidos circundantes.","E":"Localização supraclavicular."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-49933","number":"49933","sourceNumber":"49933","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A hipoperfusão renal pode acarretar:","options":{"A":"Vasodilatação da arteríola aferente.","B":"Vasoconstricção da arteríola eferente.","C":"Taxa de filtração glomerular diminuída.","D":"Ativação do sistema renina-angiotensina-aldosterona.","E":"Todas as alternativas estão corretas."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-27584","number":"27584","sourceNumber":"27584","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente do sexo masculino, 14 anos, negro, é internado devido a intensas dores\narticulares e no dorso. O mesmo sabe ser\nportador de anemia falciforme, confirmado por\neletroforese de hemoglobina (SS), já tendo se internado em cinco ocasiões prévias devido a quadro\nsemelhante. Apresenta-se hipocorado 2+/4+, ictérico 1+/4+, apirético e taquicárdico, sopro sistólico\n2+/6+ em foco mitral, sem irradiação, abdômen inocente, sem visceromegalias e sem sinais\ninflamatórios nos locais dolorosos. Os exames iniciais mostram uma anemia normo/normo e o EAS\napresenta hematuria 1+/4+ e densidade de 1,009. Você diria que esta densidade é devida a:","options":{"A":"Erro laboratorial.","B":"Desidratação hipertônica.","C":"Lesão renal induzida por infartos medulares.","D":"Fase de recuperação pós-insuficiência renal aguda.","E":"Liberação de hormônio natriurético atrial por comprometimento cardíaco."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-27594","number":"27594","sourceNumber":"27594","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a insuficiência renal é FALSO afirmar:","options":{"A":"As causas mais comuns de insuficiência renal crônica são diabetes mellitus, hipertensão,\nglomerulonefrite crônica e doença dos rins policísticos.","B":"Agentes de contraste radiológico não estão envolvidos na patogênese da insuficiência renal\naguda.","C":"Anorexia, náuseas, soluço, vômitos, hematêmese, prejuízo na hemostasia são mais frequentes\nna retenção aguda de toxinas urêmicas.","D":"Prurido cutâneo, pericardite e anemia são mais frequentemente vistas após uremia prolongada.","E":"A ureia é o mais importante metabólito do catabolismo de proteínas, sendo excretada\nprimariamente pelos rins."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-27608","number":"27608","sourceNumber":"27608","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em que situação clínica um aumento de creatinina sérica seria explicado apenas por\numa redução na taxa de filtração glomerular?","options":{"A":"Uso de cimetidina em um paciente com úlcera péptica.","B":"Diabético com bexiga neurogênica.","C":"Convulsões em paciente com estado epiléptico.","D":"Contração severa de volume extracelular em paciente com diarreia.","E":"Uso de trimetropim em paciente com infecção urinária."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-10582","number":"10582","sourceNumber":"10582","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A insuficiência renal aguda pré-renal se caracteriza por apresentar:","options":{"A":"Sódio urinário menor que 20 mEq/L","B":"Excreção fracionada de sódio acima de 2","C":"Osmolaridade urinária abaixo de 350 mOsm","D":"Relação ureia/creatinina menor que 20","E":"Densidade urinária abaixo de 1010"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-257525","number":"257525","sourceNumber":"257525","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 63 anos de idade, com 1 mês de evolução de fadiga e perda ponderal dá\nentrada no pronto socorro por 3 dias de evolução de cefaleia de forte intensidade, holocraniana,\ncontínua, há 1 dia evoluiu com confusão mental e dispnéia. Realizou tomografia de crânio que não\ndemonstrou alterações ao método. Hemograma evidenciou 192.000 leucócitos/mm³ com\npredomínio de blastos. Considerando o diagnóstico mais provável, analise as assertivas: I. Para\navaliar a oxigenação neste paciente o método mais confiável é a gasometria arterial. II. A\nradiografia de tórax geralmente mostra infiltrados intersticiais ou alveolares. III. Hidroxiuréia\npode\nser iniciada para reduzir rapidamente o número de blastos. IV. Apesar da alta contagem celular\nestes pacientes não desenvolvem síndrome de lise tumoral. Estão corretas as assertivas:","options":{"A":"I e II apenas.","B":"I e III apenas.","C":"II e III apenas.","D":"II e IV apenas.","E":"III e IV apenas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-232729","number":"232729","sourceNumber":"232729","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 62 anos de idade, do sexo feminino, procura seu atendimento por alteração\ndo hemograma. Apresenta hemograma de quatro meses\nantes e atual com leucocitose à custa de\nlinfócitos (9.000/mm³). Nega perda ponderal, nega febre, nega outros sintomas associados. Você\nsolicitou TC de tórax, abdome e pelve que não demonstrou linfadenopatia ou\nhepatoesplenomegalia. Considerando o diagnóstico mais provável, analise as assertivas.\n\nI. A paciente tem indicação de tratamento com rituximabe, fludarabina ciclofosfamida.\n\nII. O acometimento da medula óssea ocorre apenas na menor parte dos casos.\n\nIII. O quadro pode estar associado à trombocitopenia autoimune.\n\nIV. A doença é rara em crianças. Estão CORRETAS somente as assertivas:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II e IV.","E":"III e IV."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-202799","number":"202799","sourceNumber":"202799","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Com respeito à miocardiopatia por doença de Chagas, identifique a alternativa\nINCORRETA:","options":{"A":"A fase aguda da doença é, em geral, incaracterística e passa despercebida.","B":"A transmissão do protozoário pode ser na forma oral ou transfusão de sangue.","C":"A doença caracteristicamente leva à disfunção sistólica de ventrículo esquerdo, poupando o\nsistema de condução intraventricular.","D":"O tratamento com agentes antiparasitários na fase crônica pode ser considerado, mesmo na\nausência de sinais de infecção ativa.","E":"Na doença crônica, com aneurismas ventriculares trombogênicos, a anticoagulação pode ser\nnecessária por tempo indeterminado."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-174254","number":"174254","sourceNumber":"174254","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 42 anos de idade, relata aumento de volume de linfonodo axilar à\nesquerda, doloroso, e febre. Trabalha como\ncuidador de animais, com cães e gatos. Nega\ncomorbidades. Ao exame apresenta: T = 37,9ºC, com linfadenopatia axilar à esquerda dolorosa,\nlesão pustulosa em antebraço esquerdo de 0,5 cm de diâmetro. Assinale a assertiva que contém o\npatógeno mais provável e o tratamento antimicrobiano CORRETO para este.","options":{"A":"S. aureus; sulfametoxazol + trimetoprima.","B":"M. tuberculosis; esquema RIPE.","C":"B. henselae; azitromicina.","D":"M. avium; azitromicina.","E":"Y. pestis; doxiciclina."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-148956","number":"148956","sourceNumber":"148956","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Você atende um lactente saudável, com história de início há um dia de\nlinfonodomegalia cervical esquerda. Pais\nrelatam febre baixa não mensurada, alimentando-se bem,\nsem contato com pessoas doentes. Ao exame linfonodos de cerca de dois centímetros de diâmetro,\ndolorosos, não fixos, cervicais altos, não aderidos, com restante do exame físico sem alterações. A\nconduta mais adequada é:","options":{"A":"Biópsia do maior linfonodo.","B":"Colher hemograma e sorologias.","C":"Observar por duas semanas e reavaliar.","D":"Iniciar cefalexina e reavaliar em uma semana.","E":"Solicitar raio X de tórax e teste tuberculínico intradérmico."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-358582","number":"358582","sourceNumber":"358582","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança com 4 anos de idade, apresentando dor óssea, febre, astenia, adenomegalias\ngeneralizadas, hepatoesplenomegalia, petéquias e equimoses, sugere diagnóstico mais provável\nde","options":{"A":"Linfoma Hodgkin.","B":"Leucemia linfoblástica aguda.","C":"Linfoma não Hodgkin.","D":"Leucemia mieloblástica aguda.","E":"Anemia aplástica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-354963","number":"354963","sourceNumber":"354963","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a alternativa CORRETA sobre as leucemias:","options":{"A":"A neutropenia febril é uma complicação frequente do tratamento quimioterápico das leucemias,\nsendo necessária uma intervenção rápida com\nantibioticoterapia intravenosa","B":"As leucemias mieloides agudas correspondem a 50% das leucemias da infância","C":"O pico de leucemia linfoide aguda ocorre em menores de 1 ano e adolescentes","D":"Tem prevalência muito elevada nos lactentes"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-360971","number":"360971","sourceNumber":"360971","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente, 32 anos, pós tratamento de indução de Leucemia Mielóide Aguda com\nquimioterapia, vem ao pronto socorro com\nrelato de febre com temperatura acima de 38 graus em\nduas ocasiões. Feito hemograma e visto leucócitos totais de 150/mm3 e plaquetas de 19.000/mm3.\nFeito rastreio infeccioso e visto pneumonia em Tomografia de Tórax. Paciente encontra-se com\nhipotensão apesar de expansão volêmica inicial, já solicitado vaga de UTI. Qual sua conduta?","options":{"A":"Coletar culturas, incluindo hemocultura do cateter e iniciar cefepime.","B":"Coletar culturas, incluindo hemocultura do cateter e iniciar antibioticoterapia de amplo espectro\ncom cefepime e vancomicina.","C":"Iniciar antibioticoterapia de amplo espectro com cefepime e vanco.","D":"Coletar culturas, incluindo hemocultura do cateter e aguardar o resultado para iniciar\nantibioticoterapia guiada.","E":"Coletar culturas, incluindo hemocultura do cateter, iniciar cefepime, vanco e anfotericina."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-349392","number":"349392","sourceNumber":"349392","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a doença de Chagas (DC) , considere as afirmativas a seguir. I. A ausência de\nalterações eletrocardiográficas é um indicador fidedigno de ausência de acometimento cardíaco. II.\nA duração do QRS > 140 ms e o intervalo QT > 450 ms tem acurácia moderada em predizer FEVE\nreduzida em pacientes com DC. III. A duração do QRS está diretamente relacionada ao tamanho\ndo ventrículo esquerdo e inversamente relacionada com a fração de ejeção do ventrículo esquerdo\n(FEVE) . IV. O Bloqueio de Ramo Direito (BRD) é a anormalidade eletrocardiográfica mais comum,\nisoladamente ou em associação com outras alterações. Assinale a alternativa correta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-326791","number":"326791","sourceNumber":"326791","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com 12 anos de idade, apresentando histórico de adenomegalia cervical\nlateral à direita com crescimento\nprogressivo, evolução de 10 meses, associado a febre, perda de\npeso e sudorese. Qual a hipótese diagnóstica mais provável?","options":{"A":"Linfoma Burkitt.","B":"Linfoma Hodgkin.","C":"Leucemia linfoide aguda.","D":"Leucemia mieloide aguda.","E":"Leucemia mieloide crônica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-341657","number":"341657","sourceNumber":"341657","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a Leucemia Linfoblástica Aguda (LLA), assinale a alternativa INCORRETA:","options":{"A":"Leucopenia febril é uma das emergências associadas à LLA.","B":"É o tipo de câncer mais comum em crianças, com pico de incidência entre 7 e 10 anos.","C":"Com relação ao imunofenótipo, a linhagem B é mais comumente afetada que a linhagem T\ncelular.","D":"Anemia e trombocitopenia estão presentes no hemograma comumente."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-346931","number":"346931","sourceNumber":"346931","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia, uma doença malígna dos leucócitos, tem como principal característica o\nacúmulo de células jovens (blásticas) anormais na medula óssea, que substituem as células\nsanguíneas normais. Em relação às leucemias, é correto afirmar:","options":{"A":"As translocações t (4;11) e t (9;22) estão relacionadas a melhor prognóstico nas leucemias\nlinfoides agudas.","B":"O pico de incidência da leucemia linfoide aguda é em menores de 1 ano de idade","C":"Hipertrofia gengival, coagulação intravascular disseminada e cloromas são manifestações\nclínicas mais frequentes na leucemia linfoide aguda.","D":"A neutropenia febril é uma complicação frequente do tratamento quimioterápico das leucemias,\nsendo necessária intervenção rápida com início\nde antibioticoterapia endovenosa.","E":"As leucemias mieloides agudas correspondem a 60% das leucemias na infância"},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-345074","number":"345074","sourceNumber":"345074","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A Policitemia Vera é uma síndrome mieloproliferativa originada de um clone neoplásico\nde célula tronco eritroides, que prolifera\nmesmo na ausência de eritropoetina. O diagnóstico\n\nbaseia-se na exclusão de outras causas de Policitemia, e no sangue periférico é esperada a\nevidência de:","options":{"A":"Eritrocitose com saturação de O2 > 70%","B":"Eritrocitose com saturação de O2 > 78%","C":"Eritrocitose com saturação de O2 > 84%.","D":"Eritrocitose com saturação de O2 > 92%."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-298743","number":"298743","sourceNumber":"298743","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"As unidades de transplante de medula óssea e de pacientes neutropênicos\npós-quimioterapia para leucemias agudas, especialmente leucemia mieloide aguda, que\nconseguiram implantar filtro HEPA (High Efficiency Particulate Air) nos quartos diminuíram\nsignificativamente principalmente as infecções invasivas por:","options":{"A":"Fusarium","B":"Mucorales","C":"Aspergillus","D":"Cryptococcus"},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-292346","number":"292346","sourceNumber":"292346","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 55 anos, sexo feminino, em tratamento quimioterápico de câncer de mama\navançado, procura o pronto atendimento por queixa de febre referida. Ela explica que a febre teve\ninício no dia de hoje, uma semana após ter feito sua última sessão de quimioterapia. Na avaliação\ninicial, a paciente encontra-se hemodinamicamente estável, com temperatura axilar de 38,3°C, sem\noutras alterações ao exame físico. Os exames laboratoriais iniciais mostram leucopenia importante,\ncom contagem absoluta de neutrófilos (CAN) de 100 células/mm³, sem outras alterações\nsignificativas. Você decide internar a paciente e iniciar antibioticoterapia empírica com cefepime.\nNo\n\n4.º dia de internação, a paciente encontra-se em bom estado geral, afebril há mais de 72 horas,\nsem outras queixas, com culturas negativas,\ncom CAN de 560 células/mm³ nos dois últimos dias.\nDiante do exposto, qual é a conduta correta nesse momento?","options":{"A":"Manter cefepime até completar 7 dias de tratamento antibiótico e realizar alta hospitalar após o\ntérmino do tratamento antibiótico.","B":"Suspender cefepime e realizar alta hospitalar para seguimento ambulatorial, com orientações\nsobre sinais de alerta e reavaliação de emergência\nse necessário.","C":"Manter cefepime e associar filgrastim para acelerar a recuperação neutrofílica antes de realizar\nalta hospitalar.","D":"Trocar cefepime por ciprofloxacino via oral e realizar alta hospitalar de forma que a paciente\ncomplete pelo menos 7 dias de tratamento antibiótico em regime ambulatorial.","E":"Suspender cefepime e manter a paciente em regime de internação hospitalar para avaliação de\ncurva térmica nas próximas 72 horas, com programação de realizar alta hospitalar se permanecer\nafebril."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-314887","number":"314887","sourceNumber":"314887","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem de 23 anos é tratado com quimioterapia de indução para leucemia\nlinfoblástica aguda. A contagem inicial de\nleucócitos antes do tratamento foi de 155.000/?L. Todas\nas seguintes complicações são esperadas durante o tratamento, EXCETO:","options":{"A":"Lesão renal aguda.","B":"Hipercalcemia.","C":"Hiperpotassemia.","D":"Hiperfosfatemia."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-298787","number":"298787","sourceNumber":"298787","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre as esplenectomias, todas as afirmativas estão corretas, EXCETO:","options":{"A":"Laparoscópica é a via de acesso preferencial nos pacientes de origem não traumática.","B":"No caso de cirurgias eletivas, deve ser realizada imunização para pneumococo, haemophilus e\nmeningocócica, no mínimo, duas semanas antes das cirurgias.","C":"Podem ser indicadas nos casos de púrpura trombocitopênica idiopática.","D":"Traumas esplênicos grau I podem necessitar de esplenectomia."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-297193","number":"297193","sourceNumber":"297193","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a micose fungoide, assinale a alternativa CORRETA.","options":{"A":"Pode ser causada por uma grande variedade de fungos, sendo geralmente relacionada a fungos\nleveduriformes.","B":"Suas lesões acometem mais as áreas protegidas do sol.","C":"Na sua variante eritrodérmica ocorre um eritema generalizado sem descamação ou prurido\nestando associado ao fungo Malassezia furfur.","D":"Seu diagnóstico é confirmado pela presença de hifas na biopsia cutânea."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-292415","number":"292415","sourceNumber":"292415","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente de 5 anos, com queixa de astenia, fadiga, manchas roxas pelo corpo e dor\nnas pernas há 2 semanas. Ao exame físico, hipocorada +++/4+, hidratada, ativa e reativa.\n\nTemperatura axilar 38,5ºC. Ausculta pulmonar sem alterações. Bulhas cardíacas rítmicas, 2\ntempos, com presença de sopro sistólico\n++/4+. Fígado palpável a 5 cm do rebordo costal e baço a\n6 cm. Petéquias e equimoses em membros inferiores. Hemograma evidenciando Hb 4,0 g/dl, VCM\n84 fl, leucócitos 600 x 10³/uL, plaquetas 2.000/ul. O diagnóstico provável é:","options":{"A":"Anemia aplástica severa.","B":"Deficiência de B12.","C":"Endocardite bacteriana.","D":"Leucemia linfocítica aguda.","E":"Trombocitopenia primária imune."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-283382","number":"283382","sourceNumber":"283382","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Pré-escolar de quatro anos, sexo feminino, apresenta há seis semanas dor nos\nmembros inferiores e dificuldade de deambular. O\nquadro vem evoluindo com febre baixa\nintermitente, dor articular, palidez e episódios de epistaxe. Exame físico: hipocorada; equimoses\ndifusas em membros; linfadenomegalia cervical e inguinal; hepatoesplenomegalia. O exame\ncomplementar indicado inicialmente para a investigação diagnóstica é:","options":{"A":"Hemograma.","B":"Coagulograma.","C":"Cintilografia óssea.","D":"Dosagem de ácido ascórbico.","E":"Pesquisa de anticorpo antinuclear."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-262817","number":"262817","sourceNumber":"262817","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação às adenomegalias generalizadas, assinale a alternativa correspondente a\ndoenças também associadas a hepatoesplenomegalias concomitantes:","options":{"A":"Leucemias, mononucleose, citomegalovírus.","B":"Rubéola, mononucleose, leucemias.","C":"Infecção de vias aéreas superiores, mononucleose, citomegalovírus.","D":"Doença da arranhadura do gato, mononucleose, citomegalovírus."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-269615","number":"269615","sourceNumber":"269615","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança do sexo masculino, 5 anos, chega ao pronto atendimento com temperatura de\n38,7 °C de início há 1 hora, sem outras queixas. Paciente em tratamento para leucemia linfoide\naguda, realizou quimioterapia há 2 dias e não apresenta alterações no exame físico. Hemograma\nrealizado no dia em que recebeu quimioterapia apresentava: hemoglobina 9,5 g/dl, leucócitos\n1600/mm³ (eosinófilos 100/mm³; linfócitos 900/mm³; neutrófilos 400/mm³; monócitos 200/mm³),\nplaquetas 60.000/mm³. Com base nas informações apresentadas, a conduta a ser tomada nesse\ncaso é:","options":{"A":"coletar hemograma e aguardar o resultado dos exames para decisão terapêutica.","B":"iniciar antibiótico via oral e antitérmico e reavaliar em 24 horas.","C":"prescrever antitérmico e orientar retorno se a febre persistir.","D":"coletar hemocultura, internar para observação e iniciar antibiótico via oral se a febre for\npersistente.","E":"coletar hemograma e hemocultura e iniciar antibiótico endovenoso imediatamente, sem aguardar\nresultados."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-238919","number":"238919","sourceNumber":"238919","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a doença de Chagas é correto afirmar que:","options":{"A":"O tratamento, preconizado pelo Ministério da Saúde (MS), deve ser feito com nifurtimox, e em\ncasos de intolerância ou que não respondam\nao tratamento, o MS disponibiliza o benznidazol.","B":"A doença de Chagas, se mantém confinada em áreas rurais, e estima-se que,\naproximadamente, seis milhões de pessoas\nestejam infectadas na América Latina (América do Sul,\nAmérica Central, e México) (WHO, 2015).","C":"O resfriamento ou congelamento de alimentos previne a transmissão oral por T. cruzi, assim\ncomo o cozimento acima de 45°C, a pasteurização e a liofilização.","D":"O período de incubação para transmissão vetorial é de 4 a 15 dias, para transmissão\ntransfusional/transplante é de 30 a 40 dias ou mais, e para transmissão oral é de 3 a 22 dias."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-242012","number":"242012","sourceNumber":"242012","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"São indicações de esplenectomia relacionados aos distúrbios da medula óssea, exceto:","options":{"A":"Policitemia Vera","B":"Metaplasia mielóide agnogênica","C":"Tombocitopenia essencial","D":"Doença de Gaucher","E":"Nenhuma das alternativas acima está correta."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-253835","number":"253835","sourceNumber":"253835","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a investigação etiológica da plaquetopenia, escolha a alternativa correta:","options":{"A":"A Purpura Trombocitopenica Imune é etiologia rara e de alta mortalidade, é indicado tratamento\ncom plasmaferese de urgência.","B":"A Purpura Trombocitopenica Trombótica e a Síndrome Hemolítica Urêmica são causas de\nplaquetopenia grave porém sem repercussões sistêmicas relevantes","C":"Alterações em séries branca e vermelha no hemograma são sinais de alerta para doenças\nlinfoproliferativas, aplasia de medula ou outras doenças da medula óssea","D":"Medicamentos são causa pouco relevante no diagnóstico diferencial","E":"A presença de anemia hemolítica associada afasta o diagnóstico de Purpura Trombocitopênica\nTrombótica"},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-239164","number":"239164","sourceNumber":"239164","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O Baço mantém-se em sua posição anatômica devidos seus ligamentos, paciente em\nque não apresentam hipertensão portal,\nhabitualmente alguns ligamentos são avasculares, são\neles?","options":{"A":"Esplenofrênico, esplenorrenal e esplenocólico;","B":"Esplenogástrico, esplenorrenal e esplenofrenico;","C":"Esplenoaortico, esplenogástrico e esplenofrênico;","D":"Esplenocólico, esplenofrênico e esplenogástrico"},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-253664","number":"253664","sourceNumber":"253664","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre os linfomas não Hodgkin indolentes, assinale a alternativa INCORRETA:","options":{"A":"Apresentam sobrevida prolongada (acima de 5 anos).","B":"Acometem indivíduos idosos.","C":"Possuem alto potencial de cura.","D":"Se apresentam com estágio avançado ao diagnóstico.","E":"A presença de citopenia ou sintomas B são algumas indicações para início do tratamento."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-238508","number":"238508","sourceNumber":"238508","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Entre as alternativas abaixo, qual é a manifestação mais comum em crianças com\nleucemia linfóide aguda?","options":{"A":"Perda de peso","B":"Dor óssea","C":"Sonolência","D":"Epistaxe","E":"Petéquias e equimoses"},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-202559","number":"202559","sourceNumber":"202559","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Distúrbios metabólicos que ocorrem antes ou depois de 1 a 5 dias após o início do\ntratamento do câncer são comuns. Dentre\neles, os que caracterizam a Síndrome da Lise Tumoral e\nque cursam principalmente com convulsões são:","options":{"A":"Hipocalcemia e Hipomagnesemia.","B":"Hipermagnesemia e Hipercalemia.","C":"Hipofosfatemia e Hipercalemia.","D":"Hiperfosfatemia e Hipermagnesemia.","E":"Hipermagnesemia e Hipercalcemia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-210055","number":"210055","sourceNumber":"210055","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A ocorrência da Doença de Chagas e da Síndrome da Imunodeficiência Adquirida\n(SIDA) em algumas regiões tem permitido a\ndescrição de manifestações clínicas peculiares\ncausadas pelo Tripanosoma cruzi. Assinale a alternativa incorreta: (BURATTINI, MN. Doença de\nChagas. Em: SALOMÃO R, PIGNATARI ACC. Infectologia. Guia de Medicina Ambulatorial e\nHospitalar UNIFESP. Manole. 2006.).","options":{"A":"As manifestações da doença de Chagas em pacientes com SIDA são semelhantes àquelas\ndescritas em outros grupos de pacientes com alterações da resposta imunológica, como os\ntransplantados e portadores de doenças malignas hematológicas como o linfoma.","B":"O tripanosoma pode apresentar características de agente oportunista em pacientes chagásicos\ntratados com quimioterápicos para o\ntratamento da SIDA os quais podem causar imunodepressão.","C":"No sistema nervoso central o Tripanosoma cruzi causa meningoencefalite aguda com efeito de\nmassa e grande edema perilesional, cuja\nimagem tomográfica é muitas vezes indistinguível daquela\nprovocada pelo Toxoplasma gondii.","D":"No coração é comumente verificada as ocorrências de estenoses mitrais e aórticas e lesões\ntricúspides associadas em pacientes chagásicos com SIDA, sob tratamento antirretroviral.","E":"No coração ocorre uma pancardite, com predomínio de miocardite."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-205734","number":"205734","sourceNumber":"205734","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação às adenomegalias da infância, os maiores tamanhos ganglionares são\nobservados nas crianças entre:","options":{"A":"1 e 2 anos de idade.","B":"2 e 4 anos de idade.","C":"4 e 8 anos de idade.","D":"8 e 10 anos de idade.","E":"Qualquer faixa etária."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-205687","number":"205687","sourceNumber":"205687","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Entre as alternativas abaixo, qual seria uma causa frequente de adenomegalia axilar\nepitroclear?","options":{"A":"Doença da arranhadura do gato.","B":"Toxoplasmose.","C":"Citomegalovírus.","D":"Linfoma Hodgkin.","E":"Linfoma não Hodgkin."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-179048","number":"179048","sourceNumber":"179048","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre o Linfoma Não Hodgkin podemos afirmar: (HRABE JE, CULLEN JJ. Tratamento\nde Tumores do Intestino Delgado em: Cameron 100\nedição Terapêutica Cirúrgica Elsevier 2013)","options":{"A":"São os linfomas extranodais mais frequentes","B":"Linfomas do trato gastrointestinal geralmente acometem múltiplos sítios, enquanto linfoma\nsecundário tende a ser observado em apenas um sítio.","C":"Os pacientes com doença celíaca não apresentam risco relativo de desenvolvimento de linfoma\ngastrointestinal.","D":"Os pacientes portadores de HIV e contagens de células CD4 baixas são suscetíveis ao\ndesenvolvimento de linfomas de linfócitos B, que geralmente são de baixo grau e bom prognóstico.","E":"Os tumores do tipo MALT não são associados à estimulação antigênica crônica, como\nobservado na infecção por Helicobacter pylori e nas doenças autoimunes, que provocam a\nproliferação de tecido linfóide."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-172618","number":"172618","sourceNumber":"172618","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Em relação à síndrome de lise tumoral, identifique como Verdadeiras (V) ou Falsas (F)\nas seguintes afirmativas: ( ) Os principais\nfatores predisponentes são as grandes massas tumorais\ne hiperleucocitose. ( ) A hipercalcemia secundária à morte celular é fator de risco para\ninsuficiência\nrenal. ( ) São alterações laboratoriais: hiperuricemia, hiperpotassemia e hipofosfatemia. ( ) Ocorre\nmais frequentemente nos tumores sensíveis à quimioterapia, principalmente nos linfomas de\nBurkitt, leucemias e linfomas de células T. ( ) Deve-se prescrever restrição hídrica, para prevenção\nda insuficiência renal aguda, e alopurinol, para tratamento da hiperuricemia. Assinale a alternativa\nque apresenta a sequência CORRETA, de cima para baixo.","options":{"A":"V ? V ? V ? F ? F.","B":"V ? F ? F ? V ? F.","C":"F ? F ? V ? V ? V.","D":"F ? V ? V ? F ? V.","E":"V ? F ? F ? V ? V."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-162002","number":"162002","sourceNumber":"162002","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Entre as condições abaixo, a mais frequente causa de insuficiência renal crônica é:","options":{"A":"Rins policísticos.","B":"Diabetes mellitus.","C":"Pielonefrite crônica.","D":"Uropatia obstrutiva."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-151260","number":"151260","sourceNumber":"151260","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A Leucemia Promielocítica Aguda (LPA) é um subtipo de leucemia mieloide aguda que\ntem uma citogenética, características clínicas e comportamento biológico distintos. A LPA é\ncaracterizada por uma parada na maturação leucocitária na fase de promielócito. A descoberta e\nelucidação da patogênese molecular para LPA levou a uma das principais terapias-alvo para\nleucemia. Ela é classificada como LMA (Leucemia Mielocítica Aguda) M3 pelo sistema FAB\n(Francês-Americano-Britânico) e como LPA com translocação entre cromossomos 15 e 17 pela\nOMS. A complicação fatal do tratamento alvo com Ácido Transretinoico (ATRA) é descrita como:","options":{"A":"Coagulação intravascular disseminada.","B":"Síndrome febril aguda.","C":"Síndrome eosinofílica.","D":"Síndrome retinoide.","E":"Pneumonite eosinofílica aguda."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-153699","number":"153699","sourceNumber":"153699","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A doença de Chagas é uma das consequências da infecção humana produzida pelo\nprotozoário flagelado Trypanosoma cruzi. Após a entrada do parasito no organismo, basicamente\nocorrem duas etapas fundamentais na infecção humana, que são a fase inicial aguda e a fase\ncrônica. Tendo em vista os aspectos clínicos dos portadores dessa enfermidade, verifique as\nafirmativas a seguir: I. Na fase inicial da doença ocorrem manifestações de doença febril, não\npersistindo mais do que 5 semanas. Nessa fase, os sinais e sintomas não desaparecem facilmente\ne podem progredir para formas agudas que levam ao óbito; II. A fase crônica inicialmente é\nassintomática e sem sinais de comprometimento cardíaco e/ou digestivo. Pode apresentar-se como\nforma indeterminada, forma cardíaca, forma digestiva e forma associada; III. Na forma\nindeterminada o paciente é assintomático e sem sinais de comprometimento do aparelho\ncirculatório e do aparelho digestivo. Esse quadro poderá perdurar por toda vida da pessoa\ninfectada; IV. A forma associada é a ocorrência concomitante de lesões compatíveis às formas\ncardíacas e do aparelho respiratório. Estão CORRETAS apenas as afirmativas:","options":{"A":"I e II.","B":"II e III.","C":"III e IV.","D":"I e IV.","E":"II e IV."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-153169","number":"153169","sourceNumber":"153169","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 22 anos, sexo masculino, com diagnóstico de linfoma de Hodgkin, foi admitido\nno setor de emergência de um hospital\nterciário referindo febre há 24 horas. Afirmava ter sido\nsubmetido a quimioterapia há 7 dias. O hemograma da admissão mostrava: Hb 9,6 g/dl; Leucócitos\n900/mm3; Neutrófilos 50/mm3; Plaquetas 120.000/mm3. Qual conduta imediata deve ser tomada\nfrente a esse caso?","options":{"A":"Administrar antitérmicos e orientar retorno a unidade caso haja persistência da febre.","B":"Iniciar antibiótico de amplo espectro após coleta de hemocultura.","C":"Coletar hemocultura, administrar antitérmicos e orientar retorno à unidade caso persista a\nfebre.","D":"Iniciar antibiótico de pequeno espectro após coleta de hemocultura.","E":"Administrar antitérmicos e solicitar transfusão de 01 concentrado de hemácias."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-151301","number":"151301","sourceNumber":"151301","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A leucemia aguda é o câncer mais frequente na criança, os principais sinais e sintomas\npodem ser: febre, adenomegalias, dor abdominal, hepatoesplenomegalia, petéquias. O\nHemograma é o exame de eleição para suspeita precoce do diagnóstico. Quais as alterações no\nhemograma que sugerem uma avaliação urgente pelo especialista?","options":{"A":"Anemia normocítica/normocrômica e plaquetopenia.","B":"Anemia normocítica/normocrômica e plaquetose.","C":"Anemia microcítica/hipocrômica e plaquetose.","D":"Anemia microcítica/normocrômica e plaquetopenia.","E":"Anemia normocítica/hipocrômica e plaquetopenia."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-151313","number":"151313","sourceNumber":"151313","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Uma criança de 6 anos apresenta sintomas de palidez progressiva há 15 dias, febre e\ndores ósseas. Qual a primeira conduta?","options":{"A":"Internar a criança, prescrever antibiótico via endovenosa e observar por pelo menos 48 horas,\npois a criança pode apresentar febre\nreumática.","B":"Tranquilizar a família, prescrever antibiótico via oral, sulfato ferroso e liberar o paciente\nporque o\nquadro clínico é compatível com anemia ferropriva e febre sem foco.","C":"Tranquilizar a família, solicitar hemograma, prescrever antibiótico via oral e sulfato ferroso,\nliberar o paciente e agendar retorno em 48h,\nporque o quadro clínico é compatível com anemia\nferropriva e febre sem foco.","D":"Solicitar hemograma de urgência, agendar retorno em 24h, pois a criança pode apresentar\nleucose aguda.","E":"Tranquilizar a familiar, prescrever sintomáticos, observar e solicitar retorno em 1 semana."},"answer":"D","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-153977","number":"153977","sourceNumber":"153977","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Sobre a anemia no paciente com insuficiência renal crônica (IRC), assinale a alternativa\nINCORRETA;","options":{"A":"Todos os pacientes com IRC devem ter seus níveis de hemoglobina avaliados periodicamente e\nao ser detectado anemia o tratamento com\neritropoetina deve ser prontamente instituído.","B":"A administração de eritropoetina pode ser feita por via subcutânea ou intravenosa.","C":"Só podemos considerar que houve uma resposta inadequada ao tratamento com eritropoetina\nse os estoques de ferro estiverem adequados.","D":"Um dos efeitos colaterais do uso da eritropoetina é o aumento da pressão arterial sendo\npreferível o ajuste da medicação à suspensão da eritropoetina.","E":"Uma complicação grave do tratamento com eritropoetina é a aplasia pura de série vermelha\ncausada por anticorpos anti- eritropoetina recombinante."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-153185","number":"153185","sourceNumber":"153185","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A \"doença da arranhadura do gato\" ocorre com maior frequência na infância e\nadolescência. As manifestações clínicas\ndesta entidade nosológica compreendem febre, aumento\nde gânglios e o aparecimento de pápulas. O diagnóstico desta doença geralmente pode ser feito\natravés de estudo histopatológico através do método de Warthin-Starry. Sobre esta patologia,\ntemos como agente etiológico:","options":{"A":"Borrelia burgdorferi.","B":"Bordetella pertussis.","C":"Bartonella henselae.","D":"Pasteurella multocida.","E":"Actinomyces israelii."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-131216","number":"131216","sourceNumber":"131216","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente com história de hipertensão arterial sistêmica e diabetes mellitus apresenta-se\nassintomático em consulta com alteração de creatinina. Sobre a classificação da insuficiência renal\ncrônica:","options":{"A":"A classificação é baseada na taxa de filtração glomerular (dosada ou estimada pela creatinina).\n\nA\n\npresença de proteinúria pode indicar risco mais elevado de progressão.","B":"A classificação leva em conta os valores de creatinina e ureia.","C":"A classificação é baseada na taxa de filtração glomerular (dosada ou estimada pela creatinina),\nsendo o aspecto ecográfico renal\nnecessário para se confirmar cronicidade.","D":"É necessário uma dosagem de clearance de creatinina em urina 24 horas para a classificação.","E":"A classificação se baseia no valor absoluto de creatinina."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-128963","number":"128963","sourceNumber":"128963","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Dentre as causas de doença renal crônica dialítica, atualmente no Brasil, as três\nprincipais em ordem descrescente de prevalência são:","options":{"A":"Hipertensão arterial, glomerulonefrite crônica, doença renal policística.","B":"Hipertensão arterial, glomerulonefrite crônica, diabetes melito.","C":"Nefropatia tubulointersticial, hipertensão arterial, glomerulonefrite crônica.","D":"Diabetes melito, hipertensão arterial, glomerulonefrite crônica.","E":"Diabetes melito, nefrolitíase, hipertensão arterial."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-126273","number":"126273","sourceNumber":"126273","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Criança do sexo masculino, 4 anos, chegou no pronto atendimento com história de\nfraqueza e palidez há 6 dias, aparecimento\nde equimoses e petéquias pelo corpo há 3 dias e\nepistaxe hoje. Sem febre. Ao exame físico: palidez; hepatoesplenomegalia; petéquias e equimoses\ndisseminadas. Hemograma: hemoglobina = 5,1 g/dl; hematócrito = 15%; VCM = 80 fl; leucócitos =\n180.000/mm³; plaquetas = 9.000/mm³. A principal hipótese diagnóstica e a conduta inicial indicada\nnessa situação são:","options":{"A":"Leucemia aguda; iniciar hidratação EV e realizar transfusão de concentrado de hemácias e de\nplaquetas.","B":"Trombocitopenia primária imune; iniciar prednisona e realizar transfusão de concentrado de\nhemácias.","C":"Leucemia aguda; iniciar prednisona e realizar transfusão de concentrado de hemácias.","D":"Síndrome de Evans; iniciar prednisona e realizar transfusão de concentrado de hemácias e\nplaquetas.","E":"Leucemia aguda; iniciar hidratação EV, realizar transfusão de plaquetas e não transfundir\nconcentrado de hemácias."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-128902","number":"128902","sourceNumber":"128902","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Assinale a afirmação INCORRETA.","options":{"A":"A etiologia da doença renal crônica (DRC) na criança é semelhante à encontrada no adulto.","B":"A etiologia da DRC na criança apresenta predominância de anomalias congênitas renais e\ngeniturinárias.","C":"A distribuição etiológica da DRC varia com a idade, sendo as uropatias mais frequentes como\ncausa de DRC em pacientes mais jovens e as\nglomerulopatias, em crianças com mais de 12 anos\nde idade.","D":"A presença de alteração na urinálise, de caráter persistente, em pré-escolar, durante pelo menos\n3 meses pode ser considerada doença renal\ncrônica.","E":"A DRC em estágio 1 é caracterizada por dano renal com ritmo de filtração glomerular (RFG)\nnormal ou aumentado."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-141097","number":"141097","sourceNumber":"141097","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Das abaixo, qual constitui causa de insuficiência renal pré-renal?","options":{"A":"Síndrome hemolítico-urêmica.","B":"Nefrotoxinas.","C":"Cetoacidose diabética.","D":"Insuficiência hepática.","E":"Necrose cortical renal."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-126389","number":"126389","sourceNumber":"126389","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"O linfoma de Hodgkin é uma neoplasia maligna dos sistemas reticuloendotelial e\nlinfático. Linfadenomegalia cervical ou\nsupraclavicular se apresentam em até 60% dos casos; estes\nlinfonodos são firmes, pouco dolorosos e sem calor ou rubor local. O alargamento de mediastino é\nclassicamente definido como a razão entre o maior diâmetro da massa mediastinal e o diâmetro\ntransverso do tórax, sendo que o mediastino deve ocupar um terço ou mais do tórax. Os sintomas\ncorrelacionados com o prognóstico e classicamente conhecidos como \"sistemas B\" são: febre (dois\npicos diários acima de 38ºC sem foco infeccioso determinado, por três dias consecutivos), perda de\npeso (> 10% em 6 meses) e sudorese noturna. Após a avaliação clínica de um paciente com as\ncaracterísticas semiológicas descritas acima, qual alternativa abaixo descreve a melhor ferramenta\nde auxílio para o estabelecimento do diagnóstico desta patologia?","options":{"A":"Biópsia excisional do linfonodo.","B":"Tomografia abdominal.","C":"Ressonância magnética de tórax.","D":"Tomografia por emissão de pósitrons (PET).","E":"Radiografia de tórax."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-109615","number":"109615","sourceNumber":"109615","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente internado em UTI por choque séptico pulmonar com disfunção hemodinâmica\ne necessidade de vasopressores. Recebeu reposição\nvolêmica adequada com cristaloides. Mantém\ndébito urinário de 3 ml/kg/hora. A creatinina de entrada era 0,9 mg/dl, a creatinina do dia é 3,4\nmg/dl. Sobre a classificação e investigação da insuficiência renal aguda:","options":{"A":"Os critérios de Akin buscam uniformizar o\n\ndiagnóstico da IRA e levam em conta a etiologia e o débito urinário, independente dos valores de\ncreatinina.","B":"Os critérios de Akin levam em conta o valor da creatinina e o débito urinário para classificação.\nda IRA, o paciente acima apresenta IRA Akin\n3. Avaliação complementar com parcial de urina,\nfração excretora de uréia e fração excretora de sódio podem ajudar a diferenciar causas pré-renais\nde necrose tubular aguda.","C":"Diferenciar causas pré-renais de lesão renal intrínseca é irrelevante no manejo da IRA.","D":"A reposição volêmica na IRA deve ser feita de maneira agressiva para manter perfusão renal.","E":"O paciente acima classifica-se em uma IRA Akin 2 por não apresentar oligúria, o que caracteriza\num bom prognóstico em relação ao risco de\ndiálise."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-102791","number":"102791","sourceNumber":"102791","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente é atendido no pronto socorro por queixa de sede e tonturas. No exame físico\napresenta taquicardia, redução da pressão venosa jugular, turgor cutâneo reduzido e mucosas\nsecas. A respeito do quadro acima é correto afirmar:","options":{"A":"Razão ureia/creatinina alta (= 20) é sugestiva mas não diagnóstica.","B":"Comum nos pacientes com fibrilação atrial ou trombose arterial.","C":"Associada a quadros de infecção recente como endocardite.","D":"Presença de cálculos renais na ultrassonografia.","E":"História de síndrome nefrótica está relacionado ao quadro."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103621","number":"103621","sourceNumber":"103621","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Qual dos seguintes antibióticos pode aumentar o risco de injúria renal aguda em idosos\nquando prescrito em associação com bloqueador de canal de cálcio?","options":{"A":"Doxiciclina.","B":"Trimetoprim sulfametoxazol.","C":"Cefalexina.","D":"Azitromicina.","E":"Claritromicina."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103551","number":"103551","sourceNumber":"103551","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um paciente de 67 anos de idade procura o médico para a realização de check-up. Ele\nnão apresentava queixas, era um indivíduo ativo (atividade física 4 vezes por semana), negava\netilismo, negava tabagismo, negava possuir comorbidades. O exame físico não apresentava\nparticularidades. Nos exames laboratoriais solicitados, apresentou o seguinte resultado de\nhemograma: hematócrito = 39%; hemoglobina = 13,9 g/dl; leucócitos = 37.000/mm³; neutrófilos =\n24%; linfócitos = 70%; eosinófilos = 1%; monócitos = 5%; plaquetas = 250.000. Para o paciente\nacima, a hipótese mais provável é:","options":{"A":"Leucemia linfoblástica aguda.","B":"Leucemia linfocítica crônica.","C":"Síndrome mielodisplásica.","D":"Trombocitemia essencial.","E":"Leucemia mieloide crônica."},"answer":"B","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-103597","number":"103597","sourceNumber":"103597","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A classificação de Rifle para injúria renal aguda pode ser utilizada tanto para adultos\nquanto para crianças. Na faixa etária\npediátrica, foram feitas algumas adaptações. Em relação ao\ndébito urinário da criança, o volume/ tempo que caracteriza essa injúria é:","options":{"A":"< 0,3 ml/kg/horas em 24 horas.","B":"< 0,5 ml/kg/hora em 12 horas.","C":"anúria por 12 horas.","D":"< 0,5 ml/kg/hora em 8 horas.","E":"< 0,5 ml/kg/hora em 16 horas."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-100845","number":"100845","sourceNumber":"100845","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Os Anti-Inflamatórios Não Esteroidais (AINEs) constituem uma das classes de\nmedicamentos mais comumente prescritas no mundo. Quanto aos seus efeitos nefrotóxicos, é\nCORRETO afirmar:","options":{"A":"O uso de AINE não é associado a distúrbios hidroeletrolíticos. Portanto, edema secundário ao\nseu uso deve ser acompanhado de eosinofilúria\npor nefrite intersticial aguda.","B":"O principal mecanismo de ação dos AINEs é a inibição das ciclo-oxigenases, induzindo assim a\nsíntese de prostaglandinas desencadeantes de seu efeito nefrotóxico.","C":"Indivíduos tratados com betabloqueadores ou\n\ndiuréticos são menos suscetíveis ao descontrole pressórico secundário ao uso de AINE.","D":"O uso crônico de acetaminofen, assim como de salicilatos, mesmo que em altas doses, pode\nsubstituir o uso de AINE para analgesia sem nenhum prejuízo renal.","E":"Os anti-inflamatórios seletivos afetam menos os indivíduos com função renal normal, e\nafetam de modo semelhante os pacientes com alterações renais prévias."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-77967","number":"77967","sourceNumber":"77967","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem de 60 anos com Doença Renal Crônica (DRC) estágio 4, hipertensão\narterial, diabetes mellitus tipo 2 e anemia, vem à\nconsulta para avaliação. Os exames de sangue\ndemonstram: cálcio = 9,0 mg/dl; creatinina = 3,5 mg/dl; potássio = 3,8 mEq/L; bicarbonato = 18\nmEq/L; fósforo = 4,3 mg/dl; albumina = 4,0 mg/dl; hemoglobina = 11,1 g/dl. Qual dos exames\nabaixo é o mais indicado para avaliar a presença de osteodistrofia renal nesse paciente?","options":{"A":"Densitometria óssea lombar e de fêmur.","B":"Proteína C-Reativa (PCR).","C":"Paratormônio (PTH).","D":"Dosagem de alumínio plasmático.","E":"Hormônio Tireoestimulante (TSH)."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-81780","number":"81780","sourceNumber":"81780","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Você atende na unidade básica de saúde um paciente de 54 anos, diabético, com\nalbuminúria de 850 mg/g de creatinina em amostra isolada de urina, uma creatinina de 3,5 mg/dl (o\nque indica uma taxa de filtração glomerular estimada pela equação CKD-EPI de 19 ml/min). Após\nduas avaliações anteriores nos 3 últimos meses, com creatininas de 3,6 e 3,4 mg/dl, e um\nultrassom com rins de tamanho normal e ecogenicidade aumentada, podemos afirmar que esse\npaciente tem o diagnóstico de:","options":{"A":"Insuficiência renal aguda.","B":"Doença renal crônica estágio 3.","C":"Doença renal crônica estágio 4.","D":"Doença renal crônica estágio 5.","E":"Doença renal crônica estágio 2."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-78960","number":"78960","sourceNumber":"78960","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"A função renal de uma mulher de 80 anos, com 40 kg e creatinina sérica de 0,85 mg/dl\n(valor de referência 0,6 a 1,2 mg/dl) é:","options":{"A":"30% do normal.","B":"45% do normal.","C":"60% do normal.","D":"abaixo de 20% do normal.","E":"normal."},"answer":"A","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-80509","number":"80509","sourceNumber":"80509","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Um homem de 27 anos, previamente hígido, é admitido na emergência de um hospital\nterciário com queixa de dor abdominal de\nforte intensidade, iniciada há 05 horas. Ao exame, é\ncompletamente normal, exceto pelo baço palpável a 10 cm do RCE. O hemograma mostra Hb =\n13,0 g/dl; leucócitos = 8.200/mm³ e 800.000 plaquetas/mm³. A tomografia de abdome mostra sinais\nde trombose em veia hepática. É estabelecido, então, o diagnóstico de síndrome de Budd-Chiari e\niniciada a anticoagulação plena. O diagnóstico etiológico mais provável é:","options":{"A":"Policitemia vera.","B":"Deficiência de proteína C.","C":"Deficiência de proteína S.","D":"Síndrome do anticorpo antifosfolipídeo.","E":"Trombocitemia essencial."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-79481","number":"79481","sourceNumber":"79481","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente masculino, 22 anos, interna na UTI, após acidente de trânsito, com\nesmagamento de ambas as pernas. Chega\nhipocorado (2+/4); pressão arterial: 80 x 50 mmHg;\ntaquicárdico (FC: 130 bpm); taquipneico (FR: 45 irpm). Instalado dois acessos venosos, iniciado\nreposição volêmica, instalado PVC (Pressão Venosa Central), sondagem vesical. O paciente, em\nseis horas, evoluiu com anúria, mesmo com a reposição volêmica de 1 litro de soro fisiológico 0,9%\npor hora. Melhora da pressão arterial: 120 x 70 mmHg. Os exames iniciais e de 06 (seis) horas de\nevolução foram os seguintes (VER IMAGEM). Considerando que o paciente evoluiu para anúria e\ninsuficiência renal aguda, quais as principais complicações metabólicas e qual conduta a ser\ntomada para reversão do caso:","options":{"A":"Alcalose metabólica, hiperpotassemia. Iniciar hemodiálise.","B":"Acidose metabólica, hiperpotassemia. Iniciar bicarbonato de sódio.","C":"Acidose metabólica, hiperpotassemia. Iniciar hemodiálise.","D":"Alcalose metabólica, hiperpotassemia. Iniciar furosemida.","E":"Acidose metabólica, hiperpotassemia. Iniciar furosemida."},"answer":"C","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-18/79481.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-18-80505","number":"80505","sourceNumber":"80505","collectionBlock":"med:med-clinica-medica-med-clm-18","collectionLabel":"MED · MED CLM 18","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 18","subtopic":"","stem":"Paciente 58 anos, feminina, operada há 7 dias de um CA de cólon, mantém-se com\nnecessidade de ventilação mecânica e drogas vasoativas para tratamento de um choque séptico\ndecorrente de complicações pós-operatórias e pneumonia. Exames de hoje mostram uma acidose\nmetabólica com HCO3- de 9.0, ureia de 142 mg/dl, potássio de 6,1 mmol/l, sódio de 128 mmol/l,\ncreatinina de 3,9 mg/dl e hematócrito de 27%. Diurese de apenas 100 ml nas últimas 24 horas,\nmesmo após estímulo com diuréticos de alça, fechando um balanço hídrico positivo de 2900 ml e já\napresentando sinais radiográficos de congestão pulmonar. A conduta adotada pelo médico foi:","options":{"A":"Iniciar imediatamente dose alta de furosemida.","B":"Iniciar imediatamente bicarbonato de sódio.","C":"Iniciar imediatamente poliestirenossulfonato de cálcio.","D":"Implantar catéter de Tenckhoff para diálise peritoneal.","E":"Implantar cateter duplo-lúmen para central hemodiálise."},"answer":"E","source":"Clinica médica/MED CLM 18/MED CLM 18.txt","sourceLabel":"MED · MED CLM 18","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 18","MED"],"answerSource":"explicit","commentDeferred":true}]};
